(window.GIM_TS=window.GIM_TS||{})["Sotah.0"]={"from":0,"a":[["\u0003המקנא לאשתו,\u0004 שמזהיר אותה שלא תסתר עם אדם מסויים, ואם אחר כך נסתרה איתו הרי היא חשודה שנבעלה, והרי היא אסורה לבעלה, ובעלה משקה אותה מי סוטה, \u0003ר' אליעזר אומר: מקנא לה על פי שנים\u0004 עדים, כלומר, אין קינוי מועיל שתיאסר בו על בעלה אם נסתרה עם אותו איש ושישקנה מי סוטה, אלא אם כן נעשה הקינוי בפני שני עדים, \u0003ומשקה\u0004 אותה מי סוטה גם \u0003על פי עד אחד\u0004 שראה אותה שנסתרה, \u0003או\u0004 אפילו \u0003על פי עצמו,\u0004 אם הוא עצמו ראה אותה שנסתרה. \u0003ר' יהושע אומר: מקנא לה על פי שנים, ומשקה\u0004 אותה \u0003על פי שנים.\u0004","\u0003כיצד מקנא לה?\u0004 כלומר, כיצד נעשה קינוי זה באופן שתצטרך להבדק על ידי המים המרים? אם \u0003אומר לה בפני שנים,\u0004 שני עדים: \u0003\"אל תדברי עם איש פלוני\" ודברה עמו —\u0004 \u0003עדיין היא מותרת לביתה\u0004 (בעלה) \u0003ו\u0004אם אשת כהן היא \u0003מותרת לאכול בתרומה,\u0004 שאף שהזהירה שלא תדבר עימו, אין הדיבור בלבד אוסר אותה.","ואולם אם \u0003נכנסה עמו\u0004 עם האיש שהוזהרה עליו \u0003לבית הסתר\u0004 (מקום נסתר) \u0003ושהתה עמו\u0004 שם זמן \u0003כדי טומאה\u0004 (ביאה) — \u0003אסורה לביתה\u0004 (בעלה), שאסור לו לנהוג עימה יחסי אישות, \u0003ואסורה לאכול בתרומה\u0004 עד שיתברר הדבר בשתיית מי סוטה. \u0003ואם מת\u0004 בעלה לפני שהספיקה להבדק ואין לה בנים ממנו — הרי זו מספק \u0003חולצת\u0004 ליבם, \u0003ולא מתייבמת.\u0004","תחילה מבררים את מקומה של המסכת בתוך סדר נשים. \u0003מכדי\u0004 \u0005[הרי]\u0006 ה\u0003תנא מ\u0004מסכת \u0003נזיר סליק\u0004 \u0005[עולה\u0006 ובא\u0005],\u0006 שמסכת נזיר קודמת למסכת זו לפי סדר המסכתות, \u0003מאי תנא דקא תנא\u0004 \u0005[מה שנה ששנה]\u0006 \u0003סוטה?\u0004 מה ראה התנא לשנות מסכת סוטה אחריה, כלומר, מה הקשר בין מסכת זו למסכת נזיר?","ומשיבים: \u0003כ\u0004דברי \u0003רבי, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003רבי אומר: למה נסמכה\u0004 בתורה \u0003פרשת נזיר לפרשת סוטה —\u0004 \u0003לומר לך: שכל הרואה סוטה בקלקולה,\u0004 בבזיונה, כששותה מי סוטה — \u0003יזיר עצמו מן היין,\u0004 ששתיית יין היא לעתים קרובות הסיבה לזנות, וצריך אדם לתת דבר זה על ליבו. ולפי זה יש איפוא קשר ענייני בין סוטה ונזיר, ומשום כך נסמכו המסכתות.","ושואלים: אם כן, לפי סברה זו \u0003וליתני\u0004 \u0005[ושישנה]\u0006 קודם מסכת \u0003סוטה והדר ליתני\u0004 \u0005[ויחזור\u0006 אחר כך ו\u0005ישנה]\u0006 מסכת \u0003נזיר\u0004 כפי הסדר בתורה, וכפי שמסביר רבי! ומשיבים: \u0003איידי דתנא\u0004 \u0005[מתוך ששנה]\u0006 מסכת \u0003כתובות ותנא\u0004 \u0005[ושנה\u0006 בה\u0005]\u0006 פרק \u0003\"המדיר\"\u0004 שבה נזכרים מקצת דיני נדרים שבין איש לאשתו, \u0003תנא\u0004 \u0005[שנה]\u0006 לאחריה מסכת \u0003נדרים\u0004 שכולה עוסקת בענייני נדרים, \u0003ואיידי דתנא\u0004 \u0005[ומתוך ששנה]\u0006 מסכת \u0003נדרים, תנא\u0004 \u0005[שנה]\u0006 אחריה מסכת \u0003נזיר דדמי\u0004 \u0005[שדומה]\u0006 \u0003לנדרים\u0004 מבחינת ההלכה, שהרי נדר הנזירות הוא אחד מסוגי הנדרים, \u0003וקתני\u0004 \u0005[ושנה]\u0006 אחר כך \u0003סוטה, כדרבי\u0004.","לאחר הקדמה זו, באים לברר את לשון המשנה. שנינו במשנה \u0003\"המקנא\u0004 לאשתו \u0003\",\u0004 ומלשון זו משמע ב\u0003דיעבד\u0004 אם עשה כן — \u0003אין\u0004 \u0005[כן]\u0006 אבל \u0003לכתחילה —\u0004 \u0003לא\u0004 יקנא. שאילו היה מעשה הקינוי חובה או מצווה שיש לעשותן לכתחילה צריך היה לומר במשנה \"מקנא אדם לאשתו\". משמע מכאן, כי \u0003קסבר\u0004 \u0005[סבור]\u0006 ה\u0003תנא דידן\u0004 \u0005[שלנו]\u0006 ש\u0003אסור לקנאות\u0004 לכתחילה, וכל הדינים שנאמרו בסוטה הם רק אם עשה מעשה וקינא.","\u0003אמר רב שמואל בר רב יצחק: כי הוה פתח\u0004 \u0005[כאשר היה פותח]\u0006 \u0003ריש לקיש\u0004 לדרוש \u0003ב\u0004פרשת \u0003סוטה, אמר הכי\u0004 \u0005[כך]\u0006 כפתיחה: \u0003אין מזווגין לו לאדם\u0004 משמים \u0003אשה אלא לפי מעשיו, שנאמר: \"כי לא ינוח שבט הרשע על גורל הצדיקים\"\u0004 (תהלים קכה, ג), ומי שיש לו אשה רעה — הרי זה בהתאם למעשיו הרעים. \u0003אמר רבה בר בר חנה אמר ר' יוחנן: וקשין\u0004 בני זוג \u0003לזווגן\u0004 זה לזה \u0003כקריעת ים סוף,\u0004 שעצם זיווגו של אדם לאשה המתאימה לו הוא מעשה נס כקריעת ים סוף, \u0003שנאמר\u0004 במזמור המדבר על יציאת מצרים: \u0003\"אלהים מושיב יחידים ביתה מוציא אסירים בכושרות\"\u0004 \u0003(תהלים סח, ז), כלומר, להושיב אנשים בודדים (\"יחידים\") ולעשות מהם בית (\"ביתה\"), כלומר, לזווגם זה לזה, הוא דבר הדומה ליציאת מצרים (\"מוציא אסירים\"). ומקשים:\u0004","\u0003איני\u0004 \u0005[וכי כן הוא]\u0006 שמזווגים לאדם אשה לפי מעשיו? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב יהודה אמר רב: ארבעים יום קודם יצירת הולד בת קול יוצאת ואומרת: בת פלוני\u0004 תנשא \u0003לפלוני,\u0004 וכן מכריזים על כי \u0003בית פלוני\u0004 יהיה שייך \u0003לפלוני,\u0004 ו\u0003שדה פלוני לפלוני,\u0004 משמע שהדבר נגזר על האדם עוד לפני יצירתו, ואיך אמר ריש לקיש שזיווגו של אדם לפי מעשיו! ומשיבים: \u0003לא קשיא\u0004 \u0005[קשה],\u0006 \u0003הא\u0004 \u0005[זה] —\u0006 \u0003בזוג ראשון\u0004 גוזרים על האדם קודם בריאתו מי תהיה אשתו, \u0003הא\u0004 \u0005[זה]\u0006 שמזווגים לאדם לפי מעשיו — \u0003בזוג שני,\u0004 ואז קשה זיווגו של אדם.","ולענין הדין במשנה ש \u0003ר' אליעזר אומר: מקנא לה על פי שנים\u0004 ומשקה על פי אחד, ולדעת ר' יהושע אף משקה על פי שנים, מעירים: \u0003עד כאן לא\u0004 שמענו כי \u0003פליגי\u0004 \u0005[נחלקו]\u0006 ר' אליעזר ור' יהושע \u0003אלא ב\u0004עדות \u0003קינוי וסתירה\u0004 אם נעשית על פי שנים או אחד, \u0003אבל ב\u0004עדות \u0003טומאה,\u0004 להעיד שהאשה גם נטמאה בביאה, מסכימים הם כי אפילו \u0003עד אחד מהימן\u0004 (נאמן),","\u0003ותנן נמי\u0004 \u0005[ושנינו גם כן]\u0006 כעין זה במשנתנו במסכת זו: \u0003עד אחד אומר \"אני ראיתי שניטמאת\" —\u0004 \u0003לא היתה שותה\u0004 מי סוטה, משום שסומכים על עדותו וצריך הבעל לגרשה, ואין מקום לבדיקה אחרת.","ושואלים: \u0003מדאורייתא מנלן דמהימן\u0004 \u0005[מן התורה מניין לנו שנאמן]\u0006 \u0003עד אחד?\u0004 ומשיבים, \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 נאמר בסוטה שנטמאה ונאסרת לבעלה \u0003\"\u0004ונסתרה והיא נטמאה \u0003ועד אין בה\"\u0004 (במדבר ה, יג), ודנים: \u0003בשנים הכתוב מדבר\u0004 שכוונת המילים \"ועד אין בה\" היא שאף שאין בה עדות שלימה של שני עדים, אך יש בה עדות של עד אחד הרי היא אסורה.","\u0003או אינו אלא אפילו באחד,\u0004 כמשמעו, שאין בה אף עדות של עד אחד? \u0003תלמוד לומר: \"לא יקום עד אחד באיש\u0004 לכל עוון ולכל חטאת... על פי שני עדים או על פי שלושה עדים יקום דבר\u0003\"\u0004 (דברים יט, טו),"],["\u0003ממשמע שנאמר \"לא יקום עד באיש\" איני יודע שהוא\u0004 עד \u0003אחד?\u0004 הלא לשון יחיד היא! אם כן \u0003מה תלמוד לומר \"אחד\"?\u0004 אלא \u0003זה בנה אב\u0004 (מקור ראשון), ללמוד ממנו הלכה כללית: \u0003כל מקום שנאמר\u0004 בתורה \u0003\"עד\"\u0004 סתם — \u0003הרי כאן שנים, עד שיפרוט לך הכתוב \"אחד\".\u0004","\u0003ואמר רחמנא\u0004 \u0005[ואמרה תורה]\u0006 לגבי סוטה \"ועד אין בה\", והכוונה לפי זה: \u0003תרי לית\u0004 \u0005[שנים אין]\u0006 \u0003בה אלא\u0004 עד \u0003חד\u0004 \u0005[אחד]\u0006 בלבד, והמשך הכתוב \u0003\"והיא לא נתפשה\"\u0004 (במדבר ה, יג), כלומר, לא נאנסה, הרי היא \u0003אסורה.\u0004","על נימוק זה שהבאנו מקשים: \u0003אלא טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 משום \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 במפורש \u0003\"לא יקום עד אחד באיש\",\u0004 ומשם למדנו שסתם \"עד\" האמור בתורה — משמעו שנים, \u0003הא לאו הכי הוה אמינא\u0004 \u0005[הרי לולא כך הייתי אומר]\u0006 ש\u0003\"עד\"\u0004 הכתוב ב\u0003סוטה חד\u0004 \u0005[אחד]\u0006 \u0003הוא.\u0004 אולם אם מפרשים כך, נמצא שפירוש הכתוב הוא שאף אם אין עד כלל הריהי נאסרת. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003אפילו\u0004 עד \u0003חד ליכא\u0004 \u0005[אחד אין\u0006 בה\u0005]\u0006 \u0003אלא במאי מיתסרא\u0004 \u0005[במה\u0006 היא \u0005נאסרת],\u0006 הרי אין בה כל עדות?","ומשיבים: \u0003איצטריך\u0004 \u0005[נצרך]\u0006 הלימוד של \"לא יקום עד באיש\" להיאמר, שאם לא כן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 כי \u0003\"עד אין בה\"\u0004 כוונתו — \u0003אין נאמן בה,\u0004 שלמרות שיש בה עד — אין עד אחד נאמן לגבי סוטה.","ותוהים: \u0003אין נאמן בה?! ואלא מאי בעי\u0004 \u0005[מה צריך]\u0006 כדי לאסור סוטה —","\u0003עד דאיכא תרי\u0004 \u0005[שיש שנים]?\u0006 \u0003לישתוק קרא מיניה\u0004 \u0005[שישתוק הכתוב ממנו].\u0006 שאם עד אחד אינו נאמן, אין צורך שיזכירנו הכתוב אלא מעצמנו נדע, \u0003דאתיא\u0004 \u0005[ש\u0006הרי \u0005באה,\u0006 נלמדת\u0005]\u0006 עדות בעריות דווקא בשני עדים, בגזירה שווה מן המילים \u0003\"דבר\" \"דבר\" מממון\u0004 (מדיני ממונות), שבדיני עריות נאמר \"כי מצא בה ערות דבר\" (דברים כד, א) ובדיני ממונות נאמר \"על פי שני עדים... יקום דבר\" (דברים יט, טו), \u0003ואנא ידענא\u0004 \u0005[ואני יודע]\u0006 שזהו הדין גם בסוטה \u0003מידי דהוה אכל\u0004 \u0005[כמו שהוא בכל]\u0006 \u0003עדיות שבתורה\u0004 שצריך שיעידו שני עדים!","ומשיבים: \u0003איצטריך\u0004 \u0005[צריך]\u0006 הדבר להיאמר, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 כי \u0003סוטה שאני\u0004 \u0005[שונה]\u0006 מכל עדויות, ויכולים היינו לחשוב שיהיה נאמן בה גם עד אחד, ומדוע? לפי ש\u0003רגלים לדבר,\u0004 כלומר, יש בסיס להאמין לעדות זו, \u0003שהרי\u0004 לפני כן \u0003קינא לה\u0004 בעלה מאיש זה \u0003ו\u0004אחרי כן \u0003נסתרה\u0004 איתו, ומשום כך \u0003ליתהימן\u0004 \u0005[שיהא נאמן]\u0006 \u0003בה\u0004 אפילו \u0003עד אחד,\u0004 לכן השמיע לנו הכתוב שאין עד אחד נאמן לאוסרה.","וממשיכים להקשות על סברה זו: \u0003ומי מצית אמרת\u0004 \u0005[והאם יכול היית לומר]\u0006 שהכוונה בפסוק היא ש\u0003אין\u0004 עד אחד \u0003נאמן בה ושריא\u0004 \u0005[ומותרת]!\u0006? \u0003והא מדכתיב\u0004 \u0005[והרי מ\u0006מה \u0005שנאמר]\u0006 בהמשך הפסוק \u0003\"והיא לא נתפשה\"\u0004 (נאנסה) — \u0003מכלל\u0004 הדברים אתה יכול להבין שהפסוק עוסק במקרה בו היא \u0003אסורה!\u0004","ומשיבים: בכל זאת \u0003איצטריך\u0004 \u0005[נצרך]\u0006 הדבר להיאמר ש\"עד\" כוונתו בכל מקום שני עדים, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[עולה היה על דעתך לומר]\u0006 ולפרש את הפסוק כך: עד אחד \u0003אין נאמן בה\u0004 — כוונתו \u0003עד דאיכא תרי\u0004 \u0005[שיש שני]\u0006 עדים והם אוסרים אותה, \u0003ובתרי נמי\u0004 \u0005[ובשנים גם כן]\u0006 \u0003היא\u0004 דווקא כש\u0003לא נתפשה\u0004 (נאנסה), על כן \u0003קא משמע לן\u0004 \u0005[השמיעה לנו]\u0006 הברייתא ש\"עד\" בכל מקום פירושו שנים, וממילא גם הפסוק הנאמר בסוטה \"ועד אין בה\" כוונתו לשנים, אבל אם היה אחד היה נאמן.","שנינו במשנה ש \u0003ר' יהושע אומר: מקנא לה על פי שנים\u0004 ומשקה על פי שנים. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהושע?\u0004 ומשיבים, \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"\u0004והיא נטמאה ועד אין \u0003בה\"\u0004 (במדבר ה, יג), וכפי שהוכחנו לעיל הכוונה היא שלענין עדות טומאה די בעד אחד, ויש לדייק: \u0003\"בה\"\u0004 בטומאה דווקא יש דין זה \u0003ולא בקינוי, \"בה\" —\u0004 \u0003ולא בסתירה,\u0004 שבאלה צריך שתהיה עדות גמורה, של שנים.","\u0003ור' אליעזר אומר: \"בה\"\u0004 כוונתו למעט: בה — \u0003ולא בקינוי\u0004 בלבד.","ושואלים לשיטת ר' אליעזר: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שנלמד מן הדיוק להיפך: \u0003\"בה\" —\u0004 \u0003ולא בסתירה!\u0004 ומשיבים: אי אפשר לומר כן, כי \u0003סתירה איתקש\u0004 \u0005[הוקשה,\u0006 הושוותה\u0005]\u0006 בכתוב \u0003לטומאה, דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"ונסתרה והיא נטמאה\"\u0004 (במדבר ה, יג).","ומקשים: \u0003קינוי נמי איתקש\u0004 \u0005[גם כן הוקש]\u0006 \u0003לטומאה, דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"וקנא את אשתו והיא נטמאה\"\u0004 (במדבר ה, יד)! ומשיבים: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003מיעט רחמנא\u0004 \u0005[הכתוב]\u0006 על ידי המלה \u0003\"בה\",\u0004 לומר שבדבר אחר דרושים שני עדים.","ושואלים: \u0003ומה ראית\u0004 לומר שמיעוט זה מתייחס דווקא לענין קינוי, שמא מתייחס הוא לענין סתירה, שהרי שניהם הוקשו לטומאה? ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 לומר ש\u0003סתירה עדיפא\u0004 \u0005[עדיפה]\u0006 שלא יהא צריך בה שני עדים, \u0003שכן\u0004 עדות על סתירה \u0003אוסרתה\u0004 על בעלה \u0003כ\u0004עדות על \u0003טומאה\u0004 ממש, וכשם שבטומאה מספיק עד אחד כך גם בסתירה.","ודוחים: \u0003אדרבה\u0004 (להיפך), \u0003קינוי עדיף, שכן\u0004 הוא ה\u0003עיקר\u0004 ש\u0003גרם לה.\u0004 שהרי ללא הקדמת הקינוי לא היתה נאסרת בסתירה!","\u0003ודוחים:\u0004 \u0003אי לאו\u0004 \u0005[אם לא]\u0006 היתה \u0003סתירה —\u0004 \u0003קינוי מי איכא\u0004 \u0005[האם ישנו]?\u0006 שהרי אם אין סתירה אין משמעות הלכתית לקינוי. ומקשים: אולם אפשר לומר גם מצד שני: \u0003ואי לאו\u0004 \u0005[ואם לא]\u0006 היה \u0003קינוי —\u0004 \u0003סתירה מאי אהני\u0004 \u0005[מה הועילה]?\u0006 והלא בלא קינוי לא נאסרה!","ומשיבים: \u0003אפילו הכי\u0004 \u0005[כך]\u0006 \u0003סתירה עדיפא\u0004 \u0005[עדיפה]\u0006 על קינוי משום שבכל זאת \u0003אתחלתא\u0004 \u0005[תחילתה]\u0006 של \u0003טומאה היא,\u0004 ולכן מסתבר שאותה ממעט הכתוב המדבר בטומאה.","ומעירים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 ש\u0003לא כי האי תנא\u0004 \u0005[כ\u0006שיטת \u0005תנא זה]\u0006 שיש לו שיטה אחרת בדברי ר' אליעזר. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יוסי בר' יהודה אומר משום\u0004 (בשם) \u0003ר' אליעזר: המקנא לאשתו —\u0004 \u0003מקנא על פי עד אחד או על פי עצמו, ומשקה לה על פי שנים.\u0004 וממשיכה הברייתא, \u0003השיבו חכמים: לדברי ר' יוסי בר' יהודה אין לדבר סוף,\u0004 שכיון שאין צורך בעדים לגבי הקינוי — אין לדבר גבול, שאם במקרה תתייחד אשתו לתומה עם אחר יוכל בעלה להשקותה.","ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יוסי בר' יהודה? אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"בה\",\u0004 וכוונתו: \u0003בה\u0004 בטומאה — \u0003ולא בסתירה,\u0004 שלהעיד על טומאה מספיק עד אחד אבל לא בסתירה.","ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שכך הדיוק: \u0003\"בה\" —\u0004 \u0003ולא בקינוי?\u0004 ומשיבים: אי אפשר לומר כן, כי \u0003קינוי איתקש\u0004 \u0005[הוקש,\u0006 הושווה\u0005]\u0006 \u0003לטומאה, דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"וקנא את אשתו והיא נטמאה\"\u0004 (במדבר ה, יג).","ומקשים: \u0003סתירה נמי איתקש\u0004 \u0005[גם כן הוקשה,\u0006 הושוותה\u0005]\u0006 \u0003לטומאה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ונסתרה והיא נטמאה\"\u0004 (במדבר ה, יג)?! ומשיבים: הכתוב \u0003ההוא,\u0004 המקיש סתירה לטומאה בא להסביר \u0003לכמה שיעור סתירה —\u0004 \u0003כדי טומאה, הוא דאתא\u0004 \u0005[שבא]\u0006 ולא להשוואה אחרת ביניהם.","וממשיכים לבאר את הברייתא, \u0003השיבו חכמים: לדברי ר' יוסי בר' יהודה אין לדבר סוף. מאי ניהו\u0004 \u0005[מה הוא]\u0006 הדבר שאין לו סוף? ומשיבים: \u0003דזמנין דלא קני ואמר \"קנאי\"\u0004 \u0005[שפעמים שלא קנא\u0006 לאשתו \u0005ואומר\u0006 מתוך כעסו \u0005\"קנאתי\"]\u0006 ומביא עדים שנסתרה עם אדם אחר, ונאסרת.","ותוהים: \u0003הא\u0004 \u0005[וכי]\u0006 \u0003ל\u0004שיטת \u0003משנתינו יש לדבר סוף?\u0004 הלא גם לשיטת ר' אליעזר במשנתנו שמשקה על פי עצמו, \u0003זמנין\u0004 \u0005[פעמים]\u0006 ש\u0003לא איסתתר\u0004 \u0005[נסתרה]\u0006 עם האיש \u0003ואמר \"איסתתר\"\u0004 \u0003[ו\u0004הבעל \u0005אומר \"נסתרה\"]\u0006 ואין לדבר סוף!","\u0003אמר רב יצחק בר יוסף אמר ר' יוחנן:\u0004 הכוונה היא ש\u0003אף לדברי ר' יוסי בר' יהודה אין לדבר סוף.\u0004 כלומר, רצו חכמים לומר שאף לשיטתו אין הדבר מגביל את האיש, ופעמים שהוא יכול לגרום לה לשתות ללא סיבה.","ומקשים: לפי פירוש זה, מורה סגנון הדברים כי \u0003אף לדברי ר' יוסי בר' יהודה ולא מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 \u0003ל\u0004שיטת ר' אליעזר ב\u0003משנתינו\u0004 שאין לדבר סוף, אך \u0003אדרבה\u0004 (להיפך), \u0003למשנתינו\u0004 לפחות \u0003איכא\u0004 \u0005[יש]\u0006 \u0003עיקר,\u0004 חשש רציני שנטמאה, שהרי יש צורך לפחות בעדות לגבי הקינוי, ויש איפוא בסיס למה שאומר הבעל שראה שנסתרה. ואילו \u0003התם\u0004 \u0005[שם]\u0006 לדעת ר' יוסי בר' יהודה \u0003ליכא\u0004 \u0005[אין]\u0006 \u0003עיקר\u0004 בסיס רציני לאסור, שהרי אין עדים שקינא לה בעלה!","\u0003אלא אי איתמר\u0004 \u0005[אם נאמר\u0006 הדבר\u0005] —\u0006 \u0003הכי איתמר\u0004 \u0005[כך נאמר],\u0006 בלשון זו, \u0003אמר רב יצחק בר יוסף אמר ר' יוחנן: לדברי ר' יוסי בר' יהודה אף למשנתינו אין לדבר סוף.\u0004 שרצה ר' יוסי בר' יהודה לומר שבעצם גם למשנתנו אפשר שלא יהיה הדבר בדוק היטב ויכול להעליל עליה שנסתרה.","\u0003אמר רב חנינא מסורא: לא לימא איניש לאיתתיה\u0004 \u0005[יאמר אדם לאשתו]\u0006 \u0003בזמן הזה \"לא תיסתרי בהדי\u0004 \u0005[עם]\u0006 \u0003פלוני\",\u0004 ומדוע? \u0003דילמא קיימא לן\u0004 \u0005[שמא מוחזק לנו\u0006 להלכה\u0005]\u0006 \u0003כ\u0004דעת \u0003ר' יוסי בר' יהודה,\u0004 ש\u0003אמר קינוי על פי עצמו, ומיסתתרא\u0004 \u0005[ונסתרת]\u0006 האשה עם האיש, \u0003וליכא האידנא\u0004 \u0005[ואין עכשיו]\u0006 \u0003מי סוטה למיבדקה\u0004 \u0005[לבדוק אותה],\u0006 \u0003וקאסר לה עילויה איסורא דלעולם\u0004 \u0005[ו\u0006נמצא \u0005אוסר אותה עליו איסור עולם].\u0006","\u0003אמר ריש לקיש: מה\u0004 פירוש \u0003לשון \"קינוי\" —\u0004 \u0003דבר המטיל קנאה בינה לבין אחרים.\u0004 שאחרים אינם מבינים מדוע היא נמנעת מלהתחבר אליהם. ומעירים: \u0003אלמא קסבר\u0004 \u0005[מכאן\u0006 שהוא \u0005סבור]\u0006 ש\u0003קינוי\u0004 עושה אדם \u0003על פי עצמו, וכולי עלמא לא ידעי דקני לה\u0004 \u0005[והכל אינם יודעים שקינא לה\u0006 בעלה\u0005]\u0006 ומשום כך כועסים עליה \u0003ואמרי\u0004 \u0005[ואומרים]:\u0006 \u0003מאי דקמא דקא בדלא\u0004 \u0005[מה\u0006 זאת \u0005שלפנינו שמתבדלת\u0006 מאיתנו\u0005],\u0006 \u0003ואתו למיעבד\u0004 \u0005[ובאים לעשות]\u0006 \u0003קנאה בהדה\u0004 \u0005[איתה],\u0006 שמתקוטטים איתה על כך.","\u0003ורב יימר בר ר' שלמיא משמיה\u0004 \u0005[משמו]\u0006 של \u0003אביי אמר:\u0004 קינוי הוא \u0003דבר המטיל קנאה\u0004 (איבה, קטטה) \u0003בינו לבינה. אלמא קסבר\u0004 \u0005[מכאן\u0006 שהוא \u0005סבור]\u0006 \u0003קינוי על פי שנים עדים,\u0004 וכיון שיש שני עדים הם מפרסמים את הדבר, \u0003וכולי עלמא ידעי דקני לה\u0004 \u0005[והכל יודעים שקינא לה]\u0006 ולכן אין הקינוי גורם לאיבה בינה לבין אחרים, \u0003ואיהו הוא דאתי למיעבד\u0004 \u0005[והוא,\u0006 בעלה, \u0005הוא שבא לעשות]\u0006 \u0003קנאה\u0004 \u0003בהדה\u0004 \u0005[איתה].\u0006"],["\u0003אלמא קסברי\u0004 \u0005[מכאן\u0006 ש\u0005סבורים\u0006 הם\u0005]\u0006 ש\u0003אסור לקנאות,\u0004 ששניהם מדברים על קינוי כלשון הטלת קנאה שהוא ענין שלילי.","ושואלים: \u0003ומאן דאמר\u0004 \u0005[ו\u0006לדעת \u0005מי שאומר]\u0006 \u0003מותר לקנאות, מהו לשון \"קינוי\"? אמר רב נחמן בר יצחק: אין \"קינוי\" אלא לשון התראה, וכן הוא אומר: \"ויקנא ה' לארצו\u0004 ויחמול על עמו","\u0003\"\u0004(יואל ב, יח) — שהתרה בפולש מלבוא אליה. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003היה ר' מאיר אומר: אדם עובר עבירה בסתר והקדוש ברוך הוא מכריז עליו בגלוי\u0004 שעשאה, \u0003שנאמר\u0004 בסוטה שזנתה בסתר \u0003\"ועבר עליו רוח קנאה\"\u0004 (במדבר ה, יד), \u0003ואין עבירה\u0004 (\"ועבר עליו\") \u0003אלא לשון הכרזה, שנאמר: \"ויצו משה ויעבירו קול במחנה\"\u0004 (שמות לו, ו).","\u0003ריש לקיש אמר: אין אדם עובר עבירה אלא אם כן נכנס בו רוח שטות, שנאמר: \"איש איש כי תשטה אשתו\"\u0004 (במדבר ה, יב) \u0003\"תשטה\"\u0004 בשי\"ן \u0003כתיב\u0004 \u0005[נכתב],\u0006 ויכולה להקרא בשי\"ן שמשמעה לשון שטות.","\u0003תניא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: מפני מה האמינה תורה עד אחד בסוטה\u0004 לענין טומאה — לפי \u0003שרגלים לדבר,\u0004 שיש בסיס לחשד זה, \u0003שהרי קינא לה, ו\u0004אחר כך \u0003נסתרה, ועד אחד מעידה שהיא טמאה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: והא כי כתיבה\u0004 \u0005[והרי כאשר כתוב]\u0006 \u0003קינוי\u0004 (\"ועבר עליו רוח קנאה וקנא את אשתו\". (במדבר ה, \u0003יד)\u0004 \u0003בתר\u0004 \u0005[אחר]\u0006 \u0003סתירה וטומאה הוא דכתיבה\u0004 \u0005[שכתוב],\u0006 ולכאורה משמע שעד אחד נאמן על טומאה גם אם לא היה קינוי!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: הכתוב בפסוק \u0003\"ועבר\u0004 עליו רוח קנאה \u0003\"\u0004— כוונתו \u0003וכבר עבר\u0004 לפני כן, לפני הסתירה והטומאה.","ומקשים: \u0003אלא מעתה,\u0004 התנאי שהתנה משה עם בני גד וראובן לפני הכניסה לארץ \u0003\"ועבר לכם כל חלוץ\"\u0004 (במדבר \u0003לב, כא)\u0004 \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר שהכוונה היא שכבר עבר? והרי על העתיד מדובר!","ומשיבים: \u0003התם מדכתיב\u0004 \u0005[שם מ\u0006מה \u0005שנאמר]\u0006 \u0003\"ונכבשה הארץ לפני ה' ואחר תשבו\"\u0004 (במדבר \u0003לב, כב)\u0004 \u0003משמע\u0004 שמדובר \u0003להבא. אלא הכא\u0004 \u0005[כאן],\u0006 \u0003אי סלקא דעתך כדכתיבי\u0004 \u0005[אם עולה על דעתך כפי\u0006 הסדר \u0005שכתובים]\u0006 המקראות, ותפרש כי \u0003\"ועבר\"\u0004 כוונתו שהקינוי היה \u0003בתר\u0004 \u0005[אחר]\u0006 \u0003טומאה וסתירה,\u0004 אם כן \u0003קינוי למה לי?\u0004 הרי כבר נסתרה ונטמאה! אם כן חייבים לומר שהכוונה שכבר עבר וקינא.","\u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: אין אדם מקנא לאשתו אלא אם כן נכנסה בו רוח, שנאמר:\u0004 \u0003\"ועבר עליו רוח קנאה וקנא את אשתו\"\u0004 (במדבר \u0003ה, יד). ושואלים:\u0004 \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 \u0003רוח\u0004 זו שנכנסה בו?","\u0003רבנן אמרי\u0004 \u0005[חכמים אומרים]:\u0006 הכוונה היא שנכנסה בו \u0003רוח טומאה,\u0004 לפי שלא היה צריך לעשות זאת. \u0003רב אשי אמר: רוח טהרה.\u0004","ומעירים: \u0003ומסתברא כמאן דאמר\u0004 \u0005[ומסתבר כמי שאומר]\u0006 שהכוונה היא שנכנסה בו \u0003רוח טהרה. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003\"וקנא את אשתו\"\u0004 — הרי זו \u0003רשות,\u0004 אלו \u0003דברי ר' ישמעאל. ר' עקיבא אומר: חובה\u0004 היא, שאם רואה אותה שנוהגת כך — חובה עליו לקנא. \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 ש\"עבר עליו רוח\" הוא \u0003רוח טהרה —\u0004 \u0003שפיר\u0004 \u0005[יפה]\u0006 נחלקו אם רשות או חובה, \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 ש\u0003רוח טומאה\u0004 היא זו, וכי \u0003רשות\u0004 או \u0003חובה לעיולי לאיניש\u0004 \u0005[להכניס לאדם]\u0006 \u0003רוח טומאה בנפשיה\u0004 \u0005[בעצמו]?\u0006 אלא ודאי הכוונה היא שהרוח הזו — רוח טהרה היא.","\u0003ב\u0004\u0003גופא\u0004 \u0005[לגופה]\u0006 של אותה ברייתא, נאמר: \u0003\"וקנא את אשתו\"\u0004 (במדבר ה, יד) — הרי זו \u0003רשות,\u0004 אלו \u0003דברי ר' ישמעאל. ור' עקיבא אומר: חובה.\u0004 כיוצא בו נחלקו במה שנאמר בדין טומאת הכהן לקרובתו שנפטרה: \u0003\"לה יטמא\"\u0004 (ויקרא כא, ג) הרי זו \u0003רשות,\u0004 אלו \u0003דברי ר' ישמעאל. ור' עקיבא אומר: חובה\u0004 היא.","וכן הכתוב האמור בעבדים כנענים \u0003\"לעלם בהם תעבדו\"\u0004 (ויקרא כה, מו) — הרי זו \u0003רשות,\u0004 שמותר לשעבדם לעולם, אלו \u0003דברי ר' ישמעאל. ר' עקיבא אומר: חובה\u0004 היא, ואסור לשחררם.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב משרשיא לרבא: לימא\u0004 \u0005[\u0006האם \u0005נאמר]\u0006 כי \u0003ר' ישמעאל ור' עקיבא בכל התורה כולה,\u0004 בכל מקום שיש בו משפט חיווי, שאין ברור אם הוא סיפור דברים או ציווי \u0003הכי פליגי\u0004 \u0005[כך\u0006 הם \u0005חלוקים],\u0006 \u0003דמר\u0004 \u0005[שחכם זה]\u0006 ר' ישמעאל \u0003אמר רשות ומר\u0004 \u0005[וחכם זה]\u0006 ר' עקיבא \u0003אמר חובה? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכא בקראי פליגי\u0004 \u0005[כאן בכתובים\u0006 הם \u0005חלוקים],\u0006 ואין זו מחלוקת כללית, אלא דווקא במקרים מסויימים אלה.","ומפרשים: נאמר \u0003\"וקנא את אשתו\" —\u0004 \u0003רשות,\u0004 אלו \u0003דברי ר' ישמעאל. ר' עקיבא אומר: חובה.\u0004","\u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' ישמעאל —\u0004 \u0003סבר לה כי האי תנא\u0004 \u0005[סבור\u0006 הוא \u0005בה\u0006 בהלכה זו \u0005כ\u0006דברי \u0005תנא זה],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אליעזר בן יעקב אומר: כלפי\u0004 (כנגד) מה\u0003 שאמרה תורה \"לא תשנא את אחיך בלבבך\"\u0004 (ויקרא יט, יז), \u0003יכול\u0004 גם \u0003כגון זו\u0004 כשרואה שאשתו אינה נוהגת בצניעות יימנע מסיכסוך ומריבה? \u0003תלמוד לומר: \"ועבר עליו רוח קנאה וקנא את אשתו\"\u0004 (במדבר ה, יד), והוצרכה התורה לומר שמותר לו לאדם לעשות כן. ומשום כך פירש ר' ישמעאל שבא הכתוב לתת רשות לקנא לאשתו.","\u0003ו\u0004לדעת \u0003ר' עקיבא: קינוי אחרינא כתיב\u0004 \u0005[אחר,\u0006 נוסף, נאמר\u0005]\u0006 (\"או איש אשר תעבור עליו רוח קנאה וקנא את אשתו\". במדבר ה, ל), מכתוב אחד למדים שהדבר מותר, ומן הכתוב האחר למדים שחובה היא.","ושואלים: \u0003ור' ישמעאל\u0004 מה סבור הוא? הרי נאמר קינוי פעם נוספת! ומשיבים: \u0003איידי דבעי למיכתב\u0004 \u0005[מתוך שהיה צריך לכתוב]\u0006 גם \u0003\"והיא נטמאה\"\u0004 וגם \u0003\"והיא לא נטמאה\"\u0004 בפסוק שלאחריו, כלומר, שגם שהדבר ספק אם נטמאה — אסורה, \u0003כתיב נמי\u0004 \u0005[כתוב גם כן]\u0006 שנית \u0003\"וקנא את אשתו\",\u0004 אבל אין ללמוד מכך להלכה.","ושיטה זו בפירוש המקרא היא \u0003ל\u0004פי שיטת \u0003תנא דבי\u0004 \u0005[החכם מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל, דתנא דבי\u0004 \u0005[ששנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: כל פרשה\u0004 בתורה \u0003שנאמרה\u0004 פעם אחת \u0003ונישנית\u0004 פעם נוספת — \u0003לא נישנית אלא בשביל דבר שנתחדש בה.\u0004 אבל שאר הדברים שנשנו בה, לא באו ללמד הלכה חדשה אלא לחזור על הענין הקודם. ואף כאן החזרה על הקינוי שהוזכר קודם לכן אינה מלמדת הלכה חדשה.","וכך, בפירוש הפסוקים יש להסביר את המחלוקת הנוספת: \u0003\"לה יטמא\"\u0004 (ויקרא כא, ג) — \u0003רשות,\u0004 אלו \u0003דברי ר' ישמעאל. ר' עקיבא אומר: חובה.\u0004","\u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' ישמעאל —\u0004 \u0003איידי דכתיב\u0004 \u0005[מתוך שנאמר]\u0006 \u0003\"אמר אל הכהנים בני אהרן ואמרת אלהם לנפש לא יטמא בעמיו\"\u0004 (ויקרא כא, א), \u0003איצטריכא למיכתב\u0004 \u0005[צריך היה לכתוב]\u0006 \u0003\"לה יטמא\"\u0004 שמותר להיטמא לקרובותיו.","\u0003ור' עקיבא\u0004 אומר שדין זה שמותר להיטמא \u0003מ\"כי אם לשארו\"\u0004 (ויקרא כא, ב) \u0003נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005],\u0006 וכיון שכך מה שנאמר \u0003\"לה יטמא\" למה לי\u0004 — הרי זה בא לומר שהדבר אינו רק רשות אלא \u0003חובה.\u0004","\u0003ור' ישמעאל\u0004 סבור שמה שנאמר \"לה יטמא\" בא לדייק: \u0003לה\u0004 בשלימותה \u0003מיטמא, ואין מיטמא לאיבריה,\u0004 שעל אבר של קרובותיו אסור לו להיטמא."],["\u0003ור' עקיבא\u0004 מה הוא אומר על כך — \u0003אם כן\u0004 שבא הכתוב למעט שאינו מיטמא לאברים, \u0003ליכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 \u0003\"\u0004לנפש לא יטמא בעמיו כי אם... \u0003לה\" ולישתוק\u0004 \u0005[ושישתוק]\u0006 הכתוב ולא יכתוב עוד, \u0003\"יטמא\" למה לי? שמע מינה\u0004 \u0005[למד מכאן]\u0006 שהכוונה היא שיש חובה להיטמא.","\u0003ור' ישמעאל\u0004 מה הוא אומר על כך — \u0003איידי\u0004 \u0005[מתוך]\u0006 ש\u0003כתב \"לה\" —\u0004 \u0003כתב נמי\u0004 \u0005[גם כן]\u0006 \u0003\"יטמא\". לכדתני דבי\u0004 \u0005[לכפי ששנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל, דתנא דבי\u0004 \u0005[ששנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: כל פרשה שנאמרה ונישנית —\u0004 \u0003לא נישנית אלא בשביל דבר\u0004 אחד \u0003שנתחדש בה,\u0004 ואין צורך שבכל מלה יהיה חידוש.","וכן \u0003\"לעלם בהם תעבדו\"\u0004 (ויקרא כה, מו) \u0003רשות\u0004 הוא, אלו \u0003דברי ר' ישמעאל, ר' עקיבא אומר: חובה.\u0004","\u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' ישמעאל —\u0004 \u0003איידי דכתיב\u0004 \u0005[מתוך שנאמר]\u0006 בכנענים \u0003\"לא תחיה כל נשמה\"\u0004 (דברים כ, טז), \u0003איצטריך נמי למיכתב\u0004 \u0005[צריך היה גם כן לכתוב]\u0006 \u0003\"לעלם בהם תעבדו\" למישרי\u0004 \u0005[להתיר]\u0006 \u0003אחד מכל האומות\u0004 שאינו כנעני \u0003שבא על הכנענית והוליד ממנה בן, שאתה רשאי לקנותו\u0004 את הבן ולקיימו כעבד, ואיננו בכלל \"לא תחיה\" האמור בכנענים.","\u0003דתניא\u0004 \u0003[ש\u0004כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מנין לאחד מן האומות שבא על הכנענית והוליד ממנה בן, שאתה רשאי לקנותו בעבד —\u0004 \u0003תלמוד לומר: \"וגם מבני התושבים הגרים עמכם מהם תקנו\"\u0004 (ויקרא כה, מה). שבא הכתוב להתיר לקנות עבדים מאלה שבאו מרחוק ונתיישבו בארץ.","\u0003יכול אף הכנעני שבא על אחת מן האומות והוליד ממנה בן, שאתה רשאי לקנותו בעבד —\u0004 \u0003תלמוד לומר: \"אשר הולידו בארצכם\"\u0004 (ויקרא כה, מה), לומר: \u0003מן הנולדים בארצכם\u0004 שאינם תושבי הארץ הקבועים, רק נולדו כאן, \u0003ולא מן הגרים\u0004 כבר \u0003בארצכם,\u0004 שהם כנענים. ולכן בן הכנעני אסור לקיימו.","\u0003ור' עקיבא\u0004 סבור כי \u0003מ\"מהם תקנו\" נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005]\u0006 הדין שמותר לקנות ולקיים דווקא מבני שאר האומות, ואם כן \u0003\"לעלם בהם תעבדו\" למה לי —\u0004 \u0003לחובה.\u0004","\u0003ור' ישמעאל\u0004 סבור: מה שנאמר \"לעולם בהם תעבודו\" בא למעט — \u0003בהם ולא באחיכם,\u0004 שבישראל אסור לעבוד עבודת עבד ולשעבדם לעולם.","\u0003ור' עקיבא\u0004 אומר: איסור עבודה \u0003באחיכם —\u0004 \u0003מסיפא דקרא נפקא\u0004 \u0005[מסופו של הכתוב יוצא],\u0006 שנאמר במפורש \u0003\"ובאחיכם בני ישראל איש באחיו לא תרדה בו בפרך\"\u0004 (ויקרא כה, מו).","\u0003ור' ישמעאל\u0004 סבור: \u0003איידי דכתיב\u0004 \u0005[מתוך שנאמר]\u0006 \u0003\"ובאחיכם\"\u0004 שאסור לעבוד בישראל, \u0003כתיב נמי\u0004 \u0005[נאמר גם כן]\u0006 בכנענים \"לעולם \u0003בהם\u0004 תעבודו\". וזהו \u0003לכדתני דבי\u0004 \u0005[לכפי ששנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל. דתנא דבי\u0004 \u0005[ששנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: כל פרשה שנאמרה ונישנית —\u0004 \u0003לא נישנית אלא בשביל דבר שנתחדש בה.\u0004","אגב דברי ההלכה שנאמרו עד כאן מביאים כמה עניינים באגדה השייכים לנושא הכללי של הסוטה. \u0003אמר רב חסדא: זנותא בביתא כי קריא לשומשמא\u0004 \u0005[זנות בבית\u0006 מזיקה \u0005כמו תולעת לשומשומים],\u0006 שכשם שהתולעת מכלה את השומשומים, כך הזנות הורסת את הבית. \u0003ואמר רב חסדא: תוקפא בביתא\u0004 \u0005[כעס בבית]\u0006 \u0003כי קריא לשומשמא\u0004 \u0005[כמו תולעת לשומשומים]\u0006 שהורסת את הבית. ומעירים: \u0003אידי ואידי\u0004 \u0005[זה וזה]\u0006 זנות וכעס שהורסים את הבית, נאמרו \u0003באיתתא\u0004 \u0005[באשה]\u0006 \u0003אבל —\u0004 \u0003בגברא לית לן\u0004 \u0005[באיש אין לנו]\u0006 \u0003בה,\u0004 משום שכעסו וזנותו אינם משפיעים כל כך על הבית כולו.","\u0003ואמר רב חסדא: בתחילה, קודם שחטאו ישראל, היתה שכינה שורה עם כל אחד ואחד\u0004 מישראל, \u0003שנאמר:\u0004 \u0003\"כי ה' אלהיך מתהלך בקרב מחנך\"\u0004 (דברים כג, טו). \u0003כיון שחטאו נסתלקה שכינה מהם, שנאמר \"ולא יראה בך ערות דבר ושב מאחריך\"\u0004 (דברים כג, טו), שמפני החטא (\"ערות דבר\") מסתלקת השכינה (\"ושב מאחריך\").","\u0003אמר ר' שמואל בר נחמני אמר ר' יונתן: כל העושה מצוה אחת בעולם הזה —\u0004 \u0003מקדמתו\u0004 אותה מצוה \u0003והולכת לפניו לעולם הבא, שנאמר: \"והלך לפניך צדקך\u0004 כבוד ה' יאספך\u0003\"\u0004 (ישעיה נח, ח). \u0003וכל העובר עבירה אחת בעולם הזה —\u0004 \u0003מלפפתו\u0004 (נצמדת אליו) העבירה \u0003והולכת לפניו\u0004 עד \u0003ליום הדין, שנאמר: \"ילפתו ארחות דרכם יעלו בתהו ויאבדו\"\u0004 (איוב ו, יח).","\u0003ר' אלעזר אומר:\u0004 העבירה \u0003קשורה בו\u0004 ומלווה אותו \u0003ככלב, שנאמר: \"ולא שמע אליה לשכב אצלה להיות עמה\"\u0004 (בראשית לט, י), והכוונה היא: אם יקיים \u0003\"לשכב אצלה\" בעולם הזה\u0004 הרי סופו \u0003\"להיות עמה\"\u0004 גם \u0003לעולם הבא.\u0004","\u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 לענין נאמנות עד אחד בטומאה: \u0003שהיה\u0004 אפשר ללמוד \u0003בדין\u0004 (בקל וחומר):","\u0003ומה עדות הראשונה\u0004 של סתירה \u0003שאין אוסרתה איסור עולם,\u0004 שאם תיבדק במי סוטה ותימצא כשירה — מותרת לבעלה, \u0003אינה מתקיימת בפחות משנים,\u0004 שלשיטת המשנה שם עדות סתירה היא בשני עדים דווקא, \u0003עדות האחרונה\u0004 של טומאה \u0003שאוסרתה איסור עולם —\u0004 \u0003אינו דין שלא תתקיים בפחות משנים?\u0004","על כן \u0003תלמוד לומר: \"\u0004והיא נטמאה \u0003ועד אין בה\"\u0004 (במדבר ה, יג), לומר ש\u0003כל\u0004 עדות טומאה \u0003שיש בה\u0004 אוסרתה.","ומעירים, בדרך זאת אפשר ללמוד להיפך: \u0003וקל וחומר לעדות הראשונה מעתה: ומה עדות האחרונה שאוסרתה איסור עולם\u0004 — \u0003מתקיימת בעד אחד, עדות הראשונה שאין אוסרתה איסור עולם —\u0004 \u0003אינו דין שתתקיים בעד אחד?\u0004","\u0003תלמוד לומר:\u0004 \u0003\"\u0004כי יקח איש אשה ובעלה והיה אם לא תמצא חן בעיניו \u0003כי מצא בה ערות דבר\"\u0004 (דברים כד, א), \u0003ולהלן\u0004 בדיני ממונות \u0003הוא אומר \"על פי שני עדים או על פי שלשה עדים יקום דבר\"\u0004 (במדבר יט, טו), \u0003מה \"דבר\" האמור להלן\u0004 בממון \u0003על פי שנים עדים\u0004 דווקא — \u0003אף כאן\u0004 בעניינים שבעריות \u0003על פי שנים\u0004 דווקא.","ושואלים: \u0003האי\u0004 \u0005[\u0006דבר \u0005זה]\u0006 \u0003מ\"כי מצא בה ערות דבר\" נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005]?\u0006 הלא \u0003מ\u0004מה שנאמר לענין טומאה \u0003\"\u0004ועד אין \u0003בה\" נפקא\u0004 \u0005[יוצא]\u0006 הדבר, שעל כך דייקנו: \u0003בה\u0004 (בטומאה) — \u0003ולא בקינוי, בה —\u0004 \u0003ולא בסתירה מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 להביא כראיה לדבר שעל סתירה צריכים שניים!","ומשיבים, \u0003הכי נמי קאמר\u0004 \u0005[כך גם כן אמר]\u0006 כך הכוונה: \u0003תלמוד לומר \"בה\", בה —\u0004 \u0003ולא בקינוי, בה —\u0004 \u0003ולא בסתירה.\u0004","אבל \u0003וטומאה בעלמא\u0004 \u0005[בכלל]\u0006 \u0003בלא קינוי ובלא סתירה,\u0004 ש\u0003לא מהימן\u0004 \u0005[נאמן]\u0006 \u0003עד אחד, מנלן\u0004 \u0005[מניין לנו]?\u0006 — \u0003נאמר כאן: \"כי מצא בה ערות דבר\" ונאמר להלן: \"על פי שני עדים או על פי שלשה עדים יקום דבר\", מה \"דבר\" האמור להלן —\u0004 \u0003עדים שנים, אף כאן —\u0004 \u0003עדים שנים.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אי זו היא עדות הראשונה —\u0004 \u0003זו עדות סתירה, עדות אחרונה —\u0004 \u0003זו עדות טומאה.\u0004"],["ומבררים: \u0003וכמה\u0004 הוא \u0003שיעור סתירה —\u0004 \u0003כדי טומאה,\u0004 כלומר, \u0003כדי ביאה,\u0004 ולא ביאה גמורה, אלא \u0003כדי העראה\u0004 (מגע ראשוני של ביאה).","וכמה זמן נחוץ לכך — \u0003כדי הקפת דקל,\u0004 כמשך הזמן הנחוץ להקיף בהליכה עץ דקל, אלו \u0003דברי ר' ישמעאל. ר' אליעזר אומר: כדי מזיגת\u0004 (מהילת) \u0003הכוס\u0004 של יין שיש בה שיעור רביעית. \u0003ר' יהושע אומר: כדי לשתותו,\u0004 את היין, מן הכוס שנמזגה.","\u0003בן עזאי אומר: כדי לצלות ביצה. ר' עקיבא אומר: כדי\u0004 לצלותה ו\u0003לגומעה. ר' יהודה בן בתירא אומר: כדי לגמוע שלש ביצים זו אחר זו. ר' אלעזר בן ירמיה אומר: כדי\u0004 משך הזמן שבו צריך \u0003לקשור גרדי\u0004 (אורג) \u0003נימא\u0004 (חוט).","\u0003חנין בן פנחס אומר: כדי שתושיט\u0004 האשה \u0003ידה לתוך פיה ליטול קיסם\u0004 מבין שיניה. החכם \u0003פלימו אומר: כדי שתושיט\u0004 אשה \u0003ידה לסל ליטול ככר.\u0004 ומוסיף: \u0003אף על פי שאין\u0004 מן הכתובים \u0003ראיה לדבר,\u0004 מכל מקום יש \u0003זכר לדבר: \"כי בעד אשה זונה עד ככר לחם\"\u0004 (משלי ו, כו).","ותחילה שואלים: \u0003וכל הני\u0004 \u0005[אלה]\u0006 שיעורי זמן שנאמרו: כדי טומאה, כדי ביאה, כדי העראה, כדי הקפת דקל, \u0003למה לי?\u0004","ומשיבים: \u0003צריכי\u0004 \u0005[צריכים]\u0006 הדברים, \u0003דאי תנא\u0004 \u0005[שאילו היה שונה]\u0006 החכם רק \u0003כדי טומאה, הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שהכוונה למשך הזמן שנדרש \u0003כדי טומאתה\u0004 בביאה \u0003ו\u0004גם כדי \u0003ארצותה\u0004 \u0005[ריצויה,\u0006 פיתויה\u0005]\u0006 קודם לכן, \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 \u0003כדי ביאה\u0004 בלבד.","\u0003ואי תנא\u0004 \u0005[ואילו\u0006 היה \u0005שונה]\u0006 רק \u0003כדי ביאה, הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 עד \u0003כדי גמר ביאה,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 \u0003כדי העראה\u0004 בלבד.","\u0003ואי אשמעינן\u0004 \u0005[ואילו היה משמיע לנו]\u0006 \u0003כדי העראה\u0004 בלבד, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003כדי העראה וארצותה\u0004 \u0005[וריצויה,\u0006 פיתויה\u0005],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 \u0003כדי טומאה,\u0004 וכבר למדנו שאין היא כוללת את הריצוי. \u0003ו\u0004אחר כך בא להשמיענו \u0003כמה כדי [העראה] —\u0004 \u0003כדי הקפת דקל.\u0004","\u0003ורמינהי\u0004 \u0005[ומטילים,\u0006 מראים סתירה\u0005]\u0006 מברייתא אחרת; נאמר בסוטה \u0003\"ונסתרה\"\u0004 (במדבר ה, יג) \u0003וכמה שיעור סתירה לא שמענו, כשהוא אומר \"והיא נטמאה\"\u0004 (במדבר ה, יג) \u0003הוי אומר\u0004 ששיעור סתירה — \u0003כדי טומאה,\u0004 והוא \u0003כדי ביאה,\u0004 כלומר, \u0003כדי העראה,\u0004 והוא \u0003כדי חזרת דקל,\u0004 אלו \u0003דברי ר' אליעזר,\u0004","\u0003ר' יהושע אומר: כדי מזיגת הכוס. בן עזאי אומר: כדי לשתותו, ר' עקיבא אומר: כדי לצלות ביצה. ר' יהודה בן בתירא אומר: כדי לגומעה.\u0004","ומעירים: \u0003קא סלקא דעתין\u0004 \u0005[עלה על דעתנו]\u0006 לומר \u0003היינו\u0004 \u0005[הוא]\u0006 \u0003הקפת דקל\u0004 המוזכרת בברייתא הקודמת \u0003היינו\u0004 \u0005[הוא]\u0006 \u0003חזרת דקל\u0004 ששני שיעורי זמן אלה זהים, ואם כן יש סתירה בין המקורות, שכן \u0003התם\u0004 \u0005[שם]\u0006 בברייתא הראשונה \u0003אמר ר' ישמעאל כדי הקפת דקל, ופליג\u0004 \u0005[וחלק]\u0006 \u0003ר' אליעזר עליה\u0004 \u0005[עליו],\u0006 ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003אמר ר' אליעזר\u0004 עצמו \u0003כדי חזרת דקל!\u0004","\u0003אמר אביי:\u0004 אין שיעורם שווה, אלא \u0003הקפה\u0004 כוונתה משך הזמן שאדם מקיף דקל \u0003ברגל,\u0004 ו\u0003חזרה\u0004 היא \u0003ברוח\u0004 שהרוח מניעה את הדקל ואחר חוזר הדקל למקומו, והוא שיעור קצר יותר.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי: חזרה\u0004 זו \u0003ברוח\u0004 האם שיעורה \u0003כי היכי דאזיל והדר אתי\u0004 \u0005[כדי ש\u0006הדקל \u0005הולך ושב]\u0006 ואפילו הוא עדיין נע, \u0003או דילמא כי היכי דאזיל ואתי והדר קאי בדוכתיה\u0004 \u0005[שמא כשהוא הולך ובא ושב\u0006 ו\u0005עומד במקומו]\u0006 שנמשך הדבר זמן ארוך יותר עד שהדקל נשאר עומד ונח במקומו. לשאלה זו לא נמצאה תשובה ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","וסתירה נוספת: \u0003התם\u0004 \u0005[שם]\u0006 בברייתא ראשונה \u0003אמר ר' אליעזר: כדי מזיגת הכוס, הכא\u0004 \u0005[כאן]\u0006 הוא אומר: \u0003כדי חזרת דקל!\u0004 ומשיבים, \u0003אידי ואידי חד שיעורא\u0004 \u0005[זה וזה שיעור אחד]\u0006 \u0003הוא.\u0004","ועוד שואלים: \u0003התם\u0004 \u0005[שם]\u0006 \u0003אמר ר' יהושע: כדי לשתותו, הכא\u0004 \u0005[כאן]\u0006 \u0003אמר: כדי מזיגת הכוס!\u0004 ומשיבים: \u0003אימא\u0004 \u0005[אמור]\u0006 שיש לצרף את הדברים ולומר שהכוונה בשתי הברייתות היא לשיעור זמן \u0003כדי למזוג ולשתות.\u0004 ושואלים: \u0003ולימא\u0004 \u0005[ושיאמר]:\u0006 \u0003אידי ואידי חד שיעורא\u0004 \u0005[זה וזה שיעור אחד]\u0006 \u0003הוא,\u0004 כפי שתירצנו את שיטת ר' אליעזר! ומשיבים: \u0003אם כן היינו\u0004 \u0005[זוהי]\u0006 שיטת \u0003ר' אליעזר\u0004 שאמר: כדי חזרת דקל, וכבר אמרנו שמזיגת הכוס וחזרת דקל הם שיעור אחד.","ועוד שואלים: \u0003התם\u0004 \u0005[שם]\u0006 \u0003אמר בן עזאי: כדי לצלות ביצה,\u0004 ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003אמר: כדי לשתותו.\u0004 ומשיבים: \u0003אידי ואידי חד שיעורא\u0004 \u0005[זה וזה שיעור אחד]\u0006 \u0003הוא.\u0004","ועוד, \u0003התם\u0004 \u0005[שם]\u0006 \u0003אמר ר' עקיבא: כדי לגומעה, הכא\u0004 \u0005[כאן]\u0006 \u0003אמר: כדי לצלות ביצה!\u0004 ומשיבים: \u0003אימא\u0004 \u0005[אמור]\u0006 שהכוונה היא \u0003כדי לצלות ביצה ולגומעה.\u0004 ושואלים: \u0003ולימא\u0004 \u0005[ושיאמר]:\u0006 \u0003אידי ואידי חד שיעורא\u0004 \u0005[ושיאמר זה וזה שיעור אחד]\u0006 \u0003הוא!\u0004 ומשיבים: \u0003אם כן\u0004 אתה מפרש, \u0003היינו\u0004 \u0005[זו היא]\u0006 שיטת \u0003בן עזאי,\u0004 שאמר: כדי לשתותו, וצריך לומר שיש חילוק ביניהם.","ועוד שואלים: \u0003התם\u0004 \u0005[שם]\u0006 \u0003אמר ר' יהודה בן בתירא: כדי לגמוע שלש ביצים זו אחר זו, הכא\u0004 \u0005[כאן]\u0006 \u0003אמר: כדי לגומעה,\u0004 כלומר, ביצה אחת! ומשיבים: \u0003לדבריו\u0004 של \u0003ר' עקיבא קאמר\u0004 \u0005[אומר\u0006 הוא\u0005],\u0006 \u0003דקאמר\u0004 \u0005[שאמר]\u0006 ר' עקיבא \u0003משערין בצליאה\u0004 (בצליה) \u0003ובגמיעה,\u0004 והשיב לו ר' יהודה: \u0003אימא\u0004 \u0005[אמור]\u0006 \u0003שיעור גמיעה לחודה\u0004 \u0005[לבדה]\u0006 שיש בו \u0003כדי לגמע שלש ביצים זו אחר זו, דהיינו\u0004 \u0005[שהוא]\u0006 שווה שיעור \u0003צליאה וגמיעה,\u0004 ואין צורך לשער גם בצליה.","בברייתא הראשונה שנינו ש\u0003ר' אלעזר בן ירמיה אומר: כדי שיקשור גרדי\u0004 (אורג) \u0003נימא\u0004 (חוט). \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי:\u0004 האם מדובר שחלקי הנימה \u0003דמרחק\u0004 \u0005[שרחוקים]\u0006 הם, ומשך הזמן הנדרש לקשירתם ארוך יותר, \u0003או דמקרב\u0004 \u0005[שקרובים]\u0006 הם? לשאלה זו לא נמצאה תשובה ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","ועוד שנינו שם, \u0003חנין בן פנחס אומר: כדי שתושיט ידה לתוך פיה ליטול קיסם. בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי:\u0004 כיצד בדיוק מדובר, האם הקיסם \u0003דמהדק\u0004 \u0005[שמהודק]\u0006 בין השיניים ומשך הזמן להוציאו ארוך יותר \u0003או\u0004 ש\u0003לא מהדק\u0004 \u0005[מהודק]?\u0006 גם לשאלה זו לא נמצאה תשובה ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","ועוד, \u0003פלימו אומר: כדי שתושיט\u0004 אשה \u0003ידה לסל\u0004 כדי \u0003ליטול\u0004 מתוכו \u0003ככר. בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי:\u0004 האם מדובר \u0003דמהדק\u0004 \u0005[שמהודק]\u0006 הככר בתוך הסל \u0003או דלא מהדק\u0004 \u0005[שאינו מהודק],\u0006 \u0003בחדתא\u0004 \u0005[ב\u0006סל \u0005חדש]\u0006 \u0003או בעתיקא\u0004 \u0005[בישן],\u0006 שהסל הישן חלק יותר, ואילו בסל חדש מעכבים ראשי הנצרים את הככר, \u0003בחמימא\u0004 \u0005[ב\u0006לחם \u0005חם]\u0006 \u0003או בקרירא\u0004 \u0005[ב\u0006לחם \u0005קר],\u0006 שככר לחם חמה רכה ונצמדת יותר, וקשה יותר להוציאה."],["\u0003בדחטי\u0004 \u0005[בשל חיטים]\u0006 \u0003או בדשערי\u0004 \u0005[בשל שעורים],\u0006 שזו של חיטים מחליקה מן הידים, ושיעור הוצאתה מהסל ארוך יותר. \u0003ברכיכא\u0004 \u0005[ב\u0006ככר \u0005רכה]\u0006 \u0003או באקושא\u0004 \u0005[בקשה]?\u0006 לכל השאלות הללו לא נמצאה תשובה ועל כן \u0003תיקו\u0004 \u0005[תעמוד,\u0006 יעמדו\u0005]\u0006 במקומן.","\u0003אמר רב יצחק בר רב יוסף אמר ר' יוחנן: כל אחד ואחד\u0004 מן החכמים הללו שחלקו מהו שיעור זמן העראה — \u0003בעצמו\u0004 מתוך נסיונו שלו \u0003שיער\u0004 (העריך) את הזמן. ושואלים: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 בין חכמים אלה \u0003בן עזאי\u0004 ש\u0003לא נסיב\u0004 \u0005[נשא\u0006 אשה\u0005]\u0006 וכיצד שיער בעצמו?","ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003נסיב ופירש הוה\u0004 \u0005[\u0006ש\u0005נשא\u0006 אשה \u0005ופרש\u0006 ממנה \u0005היה]\u0006 ולכן ידע מעצמו. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003מרביה שמיע ליה\u0004 \u0005[מרבו\u0006 \u0005נשמע לו\u0006 הדבר\u0005],\u0006 \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003\"סוד ה' ליראיו\"\u0004 (תהלים כה, יד) ויודעים הם אפילו דברים שלא התנסו בהם בעצמם.","כיון שהוזכרה דרשת החכם פלימו על הכתוב \"כי בעד אשה זונה וכו'\" (משלי ו, כו), מביאים דרשה אחרת על אותו פסוק. \u0003דרש רב עוירא, זמנין אמר לה\u0004 \u0005[פעמים אמר אותה,\u0006 את השמועה הזו\u0005]\u0006 \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' אמי, וזמנין אמר לה משמיה\u0004 \u0005[ופעמים אמר אותה משמו]\u0006 של \u0003ר' אסי: כל האוכל לחם בלא נטילת ידים\u0004 — הרי זה עוון חמור ונחשב לו \u0003כאילו בא על אשה זונה. שנאמר \"כי בעד אשה זונה עד ככר לחם\".\u0004","\u0003אמר רבא: האי\u0004 \u0005[\u0006כתוב \u0005זה]\u0006 \u0003\"בעד אשה זונה עד ככר לחם\"\u0004 הרי אינו מבטא כלל רעיון זה, שאם כן בסדר הפוך: \u0003\"בעד ככר לחם עד אשה זונה\" מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 שיאמר! \u0003אלא אמר רבא,\u0004 כך צריך לדרוש את הכתוב: \u0003כל הבא על אשה זונה —\u0004 \u0003לסוף\u0004 מגיע לידי עניות והוא \u0003מבקש\u0004 מן הבריות \u0003ככר לחם.\u0004","ובענין נטילת ידיים, \u0003אמר ר' זריקא אמר ר' אלעזר: כל המזלזל בנטילת ידים נעקר מן העולם. אמר רב חייא בר אשי אמר רב: מים ראשונים\u0004 כשנוטל את ידיו לפני האכילה — \u0003צריך שיגביה ידיו למעלה\u0004 לאחר מכן שלא יחזרו המים לידיו, וכשנוטל \u0003מים אחרונים\u0004 בסוף הסעודה — \u0003צריך שישפיל ידיו למטה. תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003הנוטל ידיו\u0004 לסעודה — \u0003צריך שיגביה ידיו למעלה\u0004 לאחר הנטילה, \u0003שמא יצאו המים\u0004 בשעת נטילה \u0003חוץ לפרק\u0004 על חלק היד שלא תקנו חכמים נטילה עליו, \u0003ו\u0004אם אינו מגביה ידיו יש לחשוש שמא \u0003יחזרו\u0004 המים האלו, \u0003ויטמאו את הידים.\u0004","\u0003אמר ר' אבהו: כל האוכל פת בלא ניגוב ידים\u0004 לאחר נטילה, וממאיס הוא בכך את הפת — \u0003כאילו אוכל לחם טמא, שנאמר\u0004 על אכילת לחם מאוס: \u0003\"ויאמר ה' ככה יאכלו בני ישראל את לחמם טמא\u0004 בגויים","כיון שדרשו את הכתוב \"כי בעד אשה זונה עד ככר לחם\" שואלים: \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 המשך הפסוק \u0003\"ואשת איש נפש יקרה תצוד\"? אמר ר' חייא בר אבא אמר ר' יוחנן: כל אדם שיש בו גסות הרוח\u0004 (גאוה) — \u0003לבסוף נכשל באשת איש, שנאמר \"ואשת איש נפש יקרה תצוד\".\u0004","\u0003אמר רבא: האי\u0004 \u0005[\u0006ביטוי \u0005זה]\u0006 \u0003\"נפש יקרה\"\u0004 אינו מתאים לפירוש זה, אלא \u0003\"נפש גבוהה\" מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר, שזה הוא הביטוי הראוי עבור גאוה. \u0003ועוד: \"היא תצוד\" מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר \"נפש יקרה היא תצוד אשת איש\"! \u0003אלא אמר רבא,\u0004 כך יש לדרוש את הכתוב: \u0003כל הבא על אשת איש, אפילו למד תורה, דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003בה \"יקרה היא מפנינים\"\u0004 (יחזקאל ג, טו), ופירשו חכמים כי יקרה וחשובה התורה עד שהלומדה נחשב יותר \u0003מכהן גדול שנכנס לפני ולפנים\u0004 (\"פנינים\") — \u0003היא\u0004 עבירה זו באשת איש \u0003תצודנו לדינה של גיהנם\u0004 ולא תועיל לו התורה שלמד.","\u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' שמעון בן יוחי: כל אדם שיש בו גסות הרוח —\u0004 \u0003כאילו עובד עבודה זרה.\u0004 והראיה לכך: \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 \u0003\"תועבת ה' כל גבה לב\"\u0004 (יחזקאל טז, ה) \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בכתובים המדברים על השמדת עבודה זרה: \u0003\"ולא תביא תועבה אל ביתך\"\u0004 (דברים ז, כו).","\u0003ור' יוחנן דידיה\u0004 \u0005[\u0006מ\u0005של עצמו]\u0006 \u0003אמר:\u0004 מי שיש בו גסות הרוח \u0003כאילו כפר בעיקר, שנאמר: \"ורם לבבך ושכחת את ה' אלהיך\"\u0004 (דברים ח, יד).","\u0003ר' חמא בר חנינא אמר:\u0004 מי שמתגאה \u0003כאילו בא על כל העריות,\u0004 והראיה לכך: \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 \u0003\"תועבת ה' כל גבה לב\",\u0004 \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בסיום פרשת העריות \u0003\"כי את כל התועבת האל\u0004 עשו אנשי הארץ","\u0003\"\u0004(ויקרא יח, כז). \u0003עולא אמר:\u0004 המתגאה \u0003כאילו בנה במה\u0004 לעבודה זרה, \u0003שנאמר: \"חדלו לכם מן האדם אשר נשמה באפו כי במה נחשב הוא\"\u0004 (ישעיה ב, כב) בזה שמרגיש ומדגיש את מציאותו (\"אשר נשמה באפו\") — \u0003אל תיקרי\u0004 \u0005[תקרא]\u0006 \u0003\"במה\" אלא \"במה\u0004 של עבודה זרה נחשב הוא\u0003\".\u0004","כיון שדרשו את הכתוב \"תועבת ה' כל גבה לב\" שואלים לגבי המשכו של פסוק זה: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"יד ליד לא ינקה\"?\u0004 \u0003אמר רב: כל הבא על אשת איש, אפילו הקנהו להקדוש ברוך הוא שמים וארץ כאברהם אבינו, דכתיב ביה\u0004 \u0005[שנאמר בו]:\u0006 \u0003\"הרימתי ידי אל ה' אל עליון קנה שמים וארץ\"\u0004 (בראשית יד, כב) שידו דומה מבחינה זו לידו של אברהם אבינו (\"יד ליד\") — \u0003לא ינקה מדינה של גיהנם.\u0004","\u0003קשיא להו\u0004 \u0005[היה קשה להם]\u0006 \u0003לדבי\u0004 \u0005[לחכמים בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' שילא: האי\u0004 \u0005[זה]\u0006 הביטוי \u0003\"יד ליד לא ינקה\"\u0004 אינו מתאים לדרשה זו, אלא \u0003\"ידי\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]\u0006 אם הוא מרמז לדברי אברהם אבינו!","\u0003אלא אמרי דבי\u0004 \u0005[אומרים החכמים מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' שילא: אפילו קיבל תורה\u0004 מידיו של הקדוש ברוך הוא \u0003כמשה רבינו, דכתיב ביה\u0004 \u0005[שנאמר בו]\u0006 \u0003\"מימינו אש דת למו\"\u0004 (דברים לג, ב), שכביכול נתן ה' את התורה מימינו שלו לידו של משה — \u0003לא ינקה מדינה של גיהנם.\u0004","\u0003קשיא ליה\u0004 \u0005[קשה לו]\u0006 \u0003לר' יוחנן\u0004 על פירוש זה: \u0003האי\u0004 \u0005[\u0006ביטוי \u0005זה]\u0006 \u0003\"יד ליד\"\u0004 אינו מתאים, אלא \u0003\"יד מיד\" מיבעיא ליה\u0004 \u0005[נצרכה לו]\u0006 לומר!","\u0003אלא אמר ר' יוחנן:\u0004"],["\u0003אפילו עושה צדקה\u0004 ונותן מידו ליד העני (\"יד ליד\") מתן \u0003בסתר, דכתיב\u0004 \u0005[שנאמר]\u0006 בענין זה: \u0003\"מתן בסתר יכפה אף\"\u0004 (משלי כא, יד) — \u0003לא ינקה מדינה של גיהנם.\u0004","למדנו קודם כמה מגונה היא גסות הרוח. ושואלים: \u0003אזהרה לגסי הרוח מנין,\u0004 היכן נאמר שאסור להתגאות? \u0003אמר רבא אמר זעירי,\u0004 שנאמר: \u0003\"שמעו והאזינו אל תגבהו\"\u0004 (ירמיה יג, טו). \u0003רב נחמן בר יצחק אמר: מהכא\u0004 \u0005[מכאן],\u0006 שנאמר \u0003\"ורם לבבך ושכחת\u0004 את ה' אלהיך\u0003\"\u0004 (דברים ח, יד), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"השמר לך פן תשכח את ה' אלהיך\"\u0004 (דברים ח, יא), \u0003וכ\u0004שיטת","\u0003ר' אבין אמר ר' אילעא,\u0004 ש\u0003אמר ר' אבין אמר ר' אילעא: כל מקום\u0004 בתורה \u0003שנאמר\u0004 בו ציווי בלשון \u0003\"השמר\" \"פן\" ו\"אל\" —\u0004 \u0003אינו אלא ב\u0004איסור \u0003לא תעשה.\u0004 ואם כן מצות לא תעשה היא שלא לבוא לשכחת ה', וזו באה על ידי גאוה.","\u0003דרש רב עוירא\u0004 את הכתוב \"רומו מעט ואיננו והומכו ככל יקפצון וכראש שבלת ימלו\" (איוב כד, כד), \u0003זמנין אמר לה משמיה\u0004 \u0005[פעמים אמר אותה\u0006 שמועה \u0005משמו]\u0006 של \u0003רב אסי וזמנין אמר לה משמיה\u0004 \u0005[ופעמים אמר אותה משמו]\u0006 של \u0003רב אמי: כל אדם שיש בו גסות הרוח —\u0004 \u0003לסוף מתמעט\u0004 (יורד בערכו), \u0003שנאמר: \"רומו מעט\",\u0004 שהמתרומם סופו שנעשה מעט. \u0003ושמא תאמר\u0004 אף על פי שנתמעט \u0003ישנו בעולם —\u0004 \u0003תלמוד לומר: \"ואיננו\",\u0004 שמת קודם זמנו.","\u0003ואם חוזר בו\u0004 מגאוותו — \u0003נאסף\u0004 (מת) \u0003בזמנו כאברהם אבינו, שנאמר \"והמכו ככל יקפצון\"\u0004 (איוב כד, כד), שמפרשו: כאשר מנמיך את עצמו (\"הומכו\") מגאוותו, הוא נאסף (\"יקפצון\" = יקבצון) \u0003כאברהם יצחק ויעקב דכתיב בהו\u0004 \u0005[שנאמר בהם]\u0006 שנתברכו \u0003\"בכל\", \"מכל\", \"כל\"\u0004 (בראשית כד, א; בראשית כז, לג; בראשית לג, יא). \u0003ואם לאו\u0004 שאינו חוזר בו מגאוותו — \u0003\"וכראש שבלת ימלו\"\u0004 (נקטף).","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"וכראש שבלת\"? רב הונא ורב חסדא\u0004 נחלקו בכך, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: כי סאסא דשיבלתא\u0004 \u0005[כמו מטען\u0006 עטרת השיער \u0005שב\u0006ראש ה\u0005שיבולת]\u0006 \u0003וחד\u0004 \u0005[ואחד]\u0006 \u0003אמר: כשיבולת עצמה.\u0004 ומעירים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003כי סאסא דשיבלתא\u0004 \u0005[כמו שיער השיבולת] —\u0006 \u0003היינו דכתיב\u0004 \u0005[זה הוא שנאמר]\u0006 \u0003\"וכראש שבלת\",\u0004 ששיער זה מצוי בראש השיבולת, \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003כי שובלתא\u0004 \u0005[כמו השיבולת]\u0006 \u0003עצמה, מאי\u0004 \u0005[מהי]\u0006 לשון \u0003\"וכראש שבלת\"? אמר רב אסי, וכן תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: משל לאדם שנכנס לתוך שדהו —\u0004 \u0003גבוהה גבוהה הוא מלקט,\u0004 והכתוב קורא לגבוהה שבשיבולים \"ראש השיבולת\".","ועוד בענין גסות הרוח. נאמר: \u0003\"\u0004מרום וקדוש אשכון \u0003ואת דכא ושפל רוח\"\u0004 (ישעיה נז, טו). \u0003רב הונא ורב חסדא\u0004 נחלקו בדיוקו של פסוק זה, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: אתי\u0004 נמצא האיש שהוא \u0003דכא\u0004 — עניו, כלומר, הקדוש ברוך הוא מגביהו אליו. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: אני\u0004 כביכול יורד ונמצא \u0003את\u0004 (עם) \u0003דכא.\u0004","ומעירים: \u0003ומסתברא כמאן דאמר\u0004 \u0005[ומסתבר כמי שאומר]\u0006 \u0003אני את דכא,\u0004 וראיה לדבר \u0003שהרי הקדוש ברוך הוא הניח כל הרים וגבעות\u0004 הגבוהים \u0003והשרה שכינתו על הר סיני\u0004 הנמוך \u0003ולא גבה\u0004 (הגביב) את \u0003הר סיני למעלה.\u0004 משמע שאין הקדוש ברוך הוא מגביה את הדכא אליו, אלא הוא יורד אליו.","\u0003אמר רב יוסף: לעולם ילמד אדם מדעת קונו, שהרי הקדוש ברוך הוא הניח כל הרים וגבעות\u0004 גבוהים \u0003והשרה שכינתו על הר סיני\u0004 שהוא נמוך, \u0003והניח כל אילנות טובות, והשרה שכינתו בסנה\u0004 שהוא צמח קטן וקוצני.","\u0003אמר ר' אלעזר: כל אדם שיש בו גסות הרוח ראוי לגדעו\u0004 (לקצצו) כפי שקוצצים את ה\u0003אשירה\u0004 שהיא עץ המשמש בפולחן עבודה זרה, שכן \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 \u0003\"ורמי הקומה גדעים\"\u0004 (ישעיה י, לג), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 \u0003\"ואשריהם תגדעון\"\u0004 (דברים ז, ה).","\u0003ואמר ר' אלעזר: כל אדם שיש בו גסות הרוח אין עפרו\u0004 שבקברו \u0003ננער\u0004 בתחיית המתים, \u0003שנאמר: \"הקיצו ורננו שכני עפר\"\u0004 (ישעיה כו, יט), \u0003\"שכבי בעפר\" לא נאמר, אלא \"שכני עפר\",\u0004 לומר: \u0003מי שנעשה שכן לעפר בחייו\u0004 שהיה עניו מאד — הוא יקיץ בזמן התחייה.","\u0003ואמר ר' אלעזר: כל אדם שיש בו גסות הרוח שכינה מיללת עליו, שנאמר: \"וגבה ממרחק יידע\"\u0004 (תהלים קלח, ו), שמפרש \"יידע\" לשון כאב ויללה.","\u0003דרש רב עוירא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 \u0003ר' אלעזר: בא וראה\u0004 ש\u0003לא\u0004 \u0003כמדת הקדוש ברוך הוא מדת בשר ודם, מדת בשר ודם —\u0004 \u0003גבוה רואה את הגבוה\u0004 שלעומתו, \u0003ואין גבוה רואה את השפל, אבל מדת הקדוש ברוך הוא אינו כן, הוא גבוה ורואה את השפל, שנאמר: \"כי רם ה' ושפל יראה\"\u0004 (תהלים קלח, ו).","\u0003אמר רב חסדא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003מר עוקבא: כל אדם שיש בו גסות הרוח, אמר הקדוש ברוך הוא: אין אני והוא יכולין לדור\u0004 יחד \u0003בעולם, שנאמר: \"מלשני בסתר רעהו אותו אצמית גבה עינים ורחב לבב אתו לא אוכל\u0004 עיני בנאמני ארץ לשבת עמדי\u0003\"\u0004 (תהלים קא, ה-ו), \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"אותו\" אלא \"אתו לא אוכל\". איכא דמתני לה\u0004 \u0005[ויש ששונים,\u0006 אומרים דבר \u0005זה]\u0006 שאמרנו, על \u0003מספרי לשון הרע, שנאמר\u0004 בתחילת הפסוק: \u0003\"מלשני בסתר רעהו אותו אצמית\".\u0004","\u0003אמר ר' אלכסנדרי: כל אדם שיש בו גסות הרוח אפילו רוח קימעא\u0004 (מועטת, קלה) \u0003עוכרתו, שנאמר: \"והרשעים כים נגרש\"\u0004 (ישעיה נז, כ), \u0003ומה ים שיש בו כמה רביעיות\u0004 הלוג (מידה) של מים בכל זאת \u0003רוח קימעא\u0004 הנושבת עליו \u0003עוכרתו, אדם שאין בו\u0004 לצורך קיומו \u0003אלא רביעית אחת\u0004 של דם \u0003על אחת כמה וכמה.\u0004","\u0003אמר ר' חייא בר אשי אמר רב: תלמיד חכם צריך שיהא בו\u0004 בכל זאת \u0003אחד משמונה בשמינית\u0004 של גאוה. \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: ומעטרא ליה כי סאסא לשבולתא\u0004 \u0005[ומעטרת אותו\u0006 הגאוה \u0005כמו השער\u0006 שבראש השיבולת \u0005לשיבולת].\u0006 \u0003אמר רבא: בשמתא דאית ביה, ובשמתא דלית ביה\u0004 \u0005[בנידוי\u0006 יהיה מי \u0005שיש בו\u0006 גאוה \u0005ובנידוי\u0006 יהיה מי \u0005שאין בו],\u0006 שהרי אמרנו שתלמיד חכם צריך שתהיה בו מקצת גאוה.","\u0003אמר רב נחמן בר יצחק:\u0004 לא תהא בתלמיד חכם \u0003לא מינה\u0004 \u0005[ממנה]\u0006 \u0003ולא מקצתה\u0004 של גאוה, \u0003מי זוטר דכתיב ביה\u0004 \u0005[האם קטן\u0006 הוא מה \u0005שנאמר בו\u0006 במתגאה\u0005]\u0006 \u0003\"תועבת ה' כל גבה לב\"\u0004 (משלי טז, ה)? ודבר שהוא תועבת ה' — ודאי שאסור לעשות אותו אפילו במקצת.","\u0003אמר חזקיה: אין תפלתו של אדם נשמעת אלא אם כן משים לבו כבשר\u0004 בלבד, שאינו מתגאה, \u0003שנאמר: \"והיה מדי חדש בחדשו\u0004 ומדי שבת בשבתו \u0003יבא כל בשר להשתחות\"\u0004 (ישעיה סו, כג).","\u0003אמר ר' זירא: \"בשר\" כתיב ביה\u0004 \u0005[נאמר בו]\u0006 \u0003\"ונרפא\"\u0004 (ויקרא יג, יח), \u0003\"אדם\" לא כתיב ביה\u0004 \u0005[נאמר בו]\u0006 \u0003\"ונרפא\",\u0004 לומר: מי שרואה עצמו כבשר בלבד — יש לו תקנה ורפואה, ומי שמגדיל עצמו — אין לו רפואה.","\u0003אמר ר' יוחנן: אד\"ם\u0004 הוא ראשי תיבות: \u0003אפר, דם, מרה,\u0004 להראות כמה מעטה חשיבותו, \u0003בש\"ר\u0004 הוא ראשי תיבות: \u0003בושה, סרוחה\u0004 (האות שי\"ן שמאלית כמו האות סמ\"ך), \u0003רמה. איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בפתרון ראשי התיבות בש\"ר: לא סרוחה אלא \u0003שאול, דכתיב\u0004 \u0005[שכתוב]\u0006 בשר \u0003בשין.\u0004","\u0003אמר רב אשי: כל אדם שיש בו גסות הרוח לסוף נפחת\u0004 מחשיבותו, \u0003שנאמר\u0004"],["\u0003\"ולשאת ולספחת\"\u0004 (ויקרא יד, נו), \u0003ואין \"שאת\" אלא לשון גבוה, שנאמר: \"ועל כל ההרים הרמים ועל כל הגבעות הנשאות\"\u0004 (ישעיה ב, יד). \u0003ואין \"ספחת\" אלא\u0004 לשון \u0003טפילה\u0004 (נספח), \u0003שנאמר: \"ספחני נא אל אחת הכהנות לאכל פת לחם\"\u0004 (שמואל א ב, לו), לרמז שמי שקודם מתנשא (\"ולשאת\") לבסוף נעשה ספחת (טפל) בלבד.","\u0003אמר ר' יהושע בן לוי: בא וראה כמה גדולים נמוכי הרוח לפני הקדוש ברוך הוא, שבשעה שבית המקדש קיים אדם מקריב\u0004 קרבן \u0003עולה —\u0004 \u0003שכר עולה\u0004 בלבד \u0003בידו, מנחה —\u0004 \u0003שכר מנחה בידו. אבל מי שדעתו שפלה —\u0004 \u0003מעלה עליו הכתוב כאילו הקריב\u0004 את \u0003כל הקרבנות כולם, שנאמר: \"זבחי אלהים רוח נשברה\"\u0004 (תהלים נא, יט), משמע, מי שרוחו נשברה הריהו כמקריב את כל הזבחים (\"זבחי אלקים\") כולם. \u0003ולא עוד אלא שאין תפלתו נמאסת, שנאמר\u0004 בסוף הפסוק: \u0003\"לב נשבר ונדכה אלהים לא תבזה\"\u0004 (תהלים נא, יט).","\u0003ו\u0004עוד \u0003אמר ר' יהושע בן לוי: כל השם\u0004 (מעריך, ומודד) \u0003אורחותיו בעולם הזה —\u0004 \u0003זוכה ורואה בישועתו של הקדוש ברוך הוא, שנאמר: \"ושם דרך אראנו בישע אלהים\"\u0004 (תהלים נ, כג), \u0003אל תקרי \"ושם\"\u0004 (ב־ש) \u0003אלא \"ושם\u0004 (ב־ש) \u0003דרך\".\u0004","שנינו במשנה: \u0003כיצד מקנא לה?\u0004 — אמר לה: \"אל תדברי עם איש פלוני\" וכו'. על לשון המשנה שואלים: \u0003הא גופא קשיא\u0004 \u0005[היא עצמה קשה],\u0006 שכן \u0003אמרת: אמר לה בפני שנים \"אל תדברי עם איש פלוני זה\" —\u0004 \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003דבור סתירה הוא,\u0004 שנחשב כאילו נסתרה עימו ונאסרת על בעלה,","\u0003והדר תני\u0004 \u0005[וחזר\u0006 ו\u0005שנה]:\u0006 \u0003דיברה עמו,\u0004 עם האיש שהוזהרה עליו — \u0003עדיין מותרת לביתה, ומותרת לאכול בתרומה, אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003דבור לא כלום הוא,\u0004 שהרי אם נסתרה ודאי אסורה עליו!","\u0003אמר אביי: הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש להבין את דברי המשנה: אמר לה \u0003\"אל תדברי\" ודברה,\u0004 או \u0003\"אל תדברי\" ונסתרה \u0004— הרי זה \u0003ולא כלום,\u0004 שמה שאסר עליה דיבור איננו קינוי של ממש. אמר לה \u0003\"אל תסתרי\u0004 עם איש פלוני \u0003\"\u0004, \u0003ודברה עמו\u0004 בלא להיסתר — \u0003עדיין מותרת לביתה ומותרת לאכול בתרומה.\u0004 אולם אם \u0003נכנסה עמו לבית הסתר ושהתה\u0004 עמו \u0003כדי טומאה,\u0004 אז \u0003אסורה לביתה ואסורה לאכול בתרומה.\u0004","שנינו במשנה ש \u0003אם\u0004 \u0003מת\u0004 הבעל לאחר שנסתרה בלא שנבדקה, ונפלה לפני היבם — \u0003חולצת\u0004 ולא מתייבמת. ושואלים: \u0003אמאי\u0004 \u0005[\u0006ו\u0005מדוע] ?\u0006 \u0003תתייבם נמי יבומי\u0004 \u0005[גם כן],\u0006 שהרי לא היה כאן אלא חשד בלבד, וכיון שלא הוכח החשד מדוע תיאסר על היבם?","\u0003אמר רב יוסף: אמר קרא\u0004 \u0005[הכתוב]\u0006 לענין גירושין: \u0003\"\u0004כי מצא בה ערות דבר... \u0003ויצאה מביתו והלכה והיתה לאיש אחר\"\u0004 (דברים כד, א-ב), שמדובר באשה שיש בה ערות דבר, אף שלא הוכח שזנתה, שבעלה מגרש אותה. ויש לדייק: יכולה היא להיות אשה \u0003לאיש אחר ו\u0004אולם הריהי \u0003לא\u0004 יכולה להיות אשה \u0003ליבם,\u0004 שאינו נחשב \"אחר\" אלא כבא במקום אחיו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אלא מעתה\u0004 אם יש להסיק להלכה מלשון הכתוב \"איש אחר\" ולא יבם — \u0003חליצה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא תיבעי\u0004 \u0005[תצטרך]\u0006 מן היבם, שהרי משמע שיכולה להינשא לאחר ואינה עומדת כלל ליבום! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003אילו איתיה\u0004 \u0005[ישנו]\u0006 \u0003לבעל\u0004 בחיים, \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא בעיא\u0004 \u0005[צריכה\u0006 היתה\u0005]\u0006 ממנו \u0003גט\u0004 כדי להתיר את עצמה לכל אדם, על אף שנאסרה עליו? \u0003השתא נמי תיבעי\u0004 \u0005[עכשיו גם כן תצטרך]\u0006 \u0003חליצה\u0004 כדי להתיר את הקשר שהיה לה עם היבם, אבל להתייבם אסור לה.","\u0003ואית דאמרי\u0004 \u0005[ויש שאומרים]\u0006 בנוסח אחר, \u0003אמר רב יוסף: רחמנא אמר\u0004 \u0005[התורה אמרה]\u0006 על אשה שמצא בה ערות דבר \u0003\"ויצאה מביתו והלכה והיתה לאיש אחר\"\u0004 והכוונה היא — ש\u0003לא ליסתריה לביתיה\u0004 \u0005[יסתור,\u0006 יחריב \u0005את ביתו]\u0006 על ידי חיים עם אשה רעה זו, \u0003ואת אמרת תתייבם נמי יבומי\u0004 \u0005[ואתה אומר תתייבם גם כן]?\u0006 אבל חליצה מן היבם חייבת.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אלא מעתה\u0004 שאנו חוששים שאשה זו פרוצה ועלולה להחריב בית בעלה, אם כן \u0003לאחר\u0004 גם כן \u0003לא תינשא,\u0004 ש\u0003לא\u0004 \u0003תיסתריה לביתיה\u0004 \u0005[תסתור את ביתו]!\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף:"],["\u0003מי קא רמינן לה עליה בעל כרחיה\u0004 \u0005[האם מטילים אנו אותה עליו בעל כורחו]\u0006 לשאת אותה? הרי מי שנושאה עושה כן מרצונו. אבל היבם שהיא מוטלת עליו בעל כורחו, אמרה התורה שאם נסתרה לא יהיה לו חיוב לייבמה. וכיון שאין מצוה בדבר, ממילא הרי היא עליו כאשת אחיו.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 שכך \u0003אמר רב יוסף: הכתוב קראו\u0004 למי שנשאה אחרי שהתגרשה מבעלה הראשון \u0003\"אחר\"\u0004 (\"והלכה והיתה לאיש אחר\". דברים כד, ב), לומר \u0003שאין\u0004 הוא \u0003בן זוגו של ראשון, שזה\u0004 בעלה הראשון \u0003הוציא רשעה מביתו\u0004 (שהרי הוציאה משום \"ערות דבר\") \u0003וזה הכניס רשעה לתוך ביתו, ואת אמרת תתיבם נמי יבומי\u0004 \u0005[ואתה אומר תתייבם גם כן]\u0006 למרות רצונו של היבם?!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אלא מעתה\u0004 לפי פירוש זה, אם \u0003נשאת לאחר\u0004 ונהגה תחתיו בצניעות, \u0003ומת בלא בנים —\u0004 \u0003לא תתיבם\u0004 לאחיו של בעלה השני, ש\u0003הכתוב קראו\u0004 למי שנשא אותה \u0003\"אחר\"\u0004 בלשון גנאי! השיב לו: \u0003גביה דהאי מיהא\u0004 \u0005[אצל זה,\u0006 הבעל השני, \u0005על כל פנים]\u0006 \u0003בשם טוב הוה קיימא\u0004 \u0005[היתה עומדת],\u0006 וכיון שלגביו היתה אשה כשירה, הריהי מתייבמת לאחיו.","\u0003רבא אמר:\u0004 זה שאין הסוטה מתייבמת \u0003קל וחומר\u0004 הוא: \u0003אם נאסרה במותר לה\u0004 (בבעלה) — \u0003ב\u0004אחי בעלה שהוא היבם שהיה \u0003אסור לה\u0004 קודם שמת האח, משום אשת אחיו — \u0003לא כל שכן\u0004 שתיאסר?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אלא מעתה,\u0004 לפי קל וחומר זה, \u0003כהן גדול שקידש את האלמנה,\u0004 שלמרות שאסורה עליו, קידושיו תופסים בה, \u0003ומת\u0004 לפני שנשאה, \u0003ויש לו אח כהן הדיוט\u0004 שמותר באלמנה, \u0003לא תתיבם\u0004 אשה זו, כי נאמר באותו אופן: \u0003אם נאסרה במותר לה\u0004 בבעלה הכהן הגדול שהיה אסור באלמנה, אם כן \u0003באסור לה\u0004 באחיו היבם שהיתה אסורה לו כל עוד אחיו חי, \u0003לא כל שכן\u0004 שתיאסר!","ודוחים: וכי על זו אתה אומר \u0003נאסרה?! הא אסירא וקיימא\u0004 \u0005[הרי\u0006 האלמנה \u0005אסורה\u0006 היא \u0005ועומדת]\u0006 ולא מחמת קלקול שהיה בתוך הנישואין נאסרה! ועוד יש לדחות קל וחומר זה: וכי אפשר לומר על בעלה הכהן הגדול \u0003\"מותר לה\"?!\u0004 הרי \u0003אסור לה הוא\u0004 מאז ומתמיד! ואם כן אין השאלה מן הענין כלל.","\u0003אלא\u0004 כך צריך לשאול: \u0003אשת כהן שנאנסה\u0004 שבעלה הכהן אסור בה, \u0003ומת\u0004 הבעל, \u0003ויש לו אח חלל\u0004 שהוא אחיו מאביו, אבל אמו היתה גרושה. ואח זה, אף שהוא בנו של כהן בטלה ממנו קדושת כהונה, ודינו כישראל שמותר באשתו שנאנסה, \u0003לא תתיבם.\u0004 ומדוע? — ש\u0003אם נאסרה במותר לה,\u0004 בבעלה — \u0003באסור לה,\u0004 אחיו כל עוד הוא עצמו חי, \u0003לא כל שכן?\u0004","ומשיבים: כאן אין קל וחומר זה תופס, כי \u0003אונס\u0004 (אשה אנוסה) לבעלה \u0003בישראל מישרא שרי\u0004 \u0005[מותר\u0006 הוא\u0005],\u0006 \u0003וגבי דהאי מיהא ליכא איסורא\u0004 \u0005[ואצל זה,\u0006 האח החלל, \u0005על כל פנים אין איסור]\u0006 אף אם היא היתה אשתו ונאנסה, לא היה אסור בה, שהרי הוא כישראל מאחר ונתחלל.","\u0003ואלו\u0004 נשים החשודות בזנות ש\u0003אסורות מלאכול בתרומה\u0004 אם היה הבעל כהן: האשה \u0003האומרת \"טמאה אני לך\",\u0004 שהודתה שנבעלה לאיש אחר. או \u0003שבאו עדים\u0004 ומעידים \u0003שהיא טמאה, והאומרת \"איני שותה\"\u0004 את המים המרים, \u0003ו\u0004זו \u0003שבעלה אינו רוצה להשקותה\u0004 אף על פי שקינא לה ונסתרה, \u0003ו\u0004זו \u0003שבעלה בא עליה בדרך\u0004 כשהלך להשקותה את המים המרים.","\u0003אמר רב עמרם: הא מילתא\u0004 \u0005[דבר זה]\u0006 \u0003אמר לן\u0004 \u0005[לנו]\u0006 \u0003רב ששת, ואנהר לן עיינין ממתניתין\u0004 \u0005[והאיר לנו עינינו ממשנתנו]\u0006 להראות שדבריו רמוזים בה, וכך אמר: \u0003סוטה שיש לה עדים במדינת הים\u0004 שהיא טמאה — \u0003אין המים בודקין אותה\u0004 ואף שחטאה אין היא ניזוקת, משום שהיא יכולה לידון בדיני אדם, ואין צורך בהוכחה שבדרך נס. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"ונסתרה והיא נטמאה ועד אין בה\"\u0004 (במדבר ה, יג), להדגיש שאין דין סוטה אלא בזו \u0003דליכא\u0004 \u0005[שאין]\u0006 מי ש\u0003ידע בה, לאפוקי הא, דהא איכא\u0004 \u0005[להוציא\u0006 את \u0005זו, שהרי יש]\u0006 מי ש\u0003ידע בה.\u0004","\u0003ואנהר לן עיינין ממתניתין\u0004 \u0005[והאיר לנו\u0006 רב ששת \u0005עינינו ממשנתנו],\u0006 \u0003דקתני\u0004 \u0005[ששנה]\u0006 בה: \u0003ושבאו לה עדים שהיא טמאה\u0004 אסורה לאכול תרומה. ונברר: \u0003דאתו\u0004 \u0005[שבאו]\u0006 \u0003עדים\u0004 אלה \u0003אימת\u0004 \u0005[מתי]?\u0006 \u0003אי נימא מקמי דתשתי\u0004 \u0005[אם נאמר\u0006 שבאו \u0005מלפני שתשתה]\u0006 אם כן מה חידוש יש בכך שאסורה בתרומה? הלא \u0003זונה היא!\u0004","\u0003אלא\u0004 ודאי שבאו \u0003לבתר דשתאי\u0004 \u0005[לאחר ששתתה].\u0006 \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 ש\u0003אין המים בודקין אותה\u0004 במקרה כזה — \u0003שפיר\u0004 \u0005[יפה]\u0006 אמרה המשנה שאינה אוכלת בתרומה מפני שסומכים על העדים שאמרו שנטמאה. \u0003אלא אי\u0004 \u0005[אם]\u0006 \u0003אמרת\u0004 ש\u0003מים בודקין אותה,\u0004 ונבדקה ונמצאה טהורה — \u0003תיגלי מילתא\u0004 \u0005[יתגלה הדבר]\u0006 \u0003למפרע דסהדי שקרי נינהו\u0004 \u0005[שעדי שקר הם],\u0006 שהרי בדקוה המים והוכח שטהורה היתה ומדוע תיאסר בתרומה?!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף\u0004 לרב ששת: \u0003לעולם אימא\u0004 \u0005[\u0006יכול \u0005אני לומר]\u0006 \u0003לך\u0004 ש\u0003מים בודקין אותה\u0004 אם היו העדים במדינת הים, \u0003והא\u0004 \u0005[וזו]\u0006 שנבדקה ונמצאה טהורה — \u0003אימור\u0004 \u0005[אמור]\u0006 \u0003זכות\u0004 שהיתה לה \u0003תולה\u0004 (משהה) \u0003לה\u0004 את גזר הדין, שלא תנזק מהמים מיד.","ומסבירים: \u0003במאי קמיפלגי\u0004 \u0005[במה חולקים]\u0006 רב ששת ורב יוסף — \u0003ב\u0004זו שהזכות תולה לה שלא מתה מיד, אלא \u0003מתנוונה\u0004 \u0005[מתנוונת,\u0006 חולה\u0005],\u0006 על דרך שאמר \u0003רבי. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003רבי אומר: זכות תולה במים המרים,\u0004 שגם אם האשה באמת חטאה בזנות, מפני זכות שיש לה אינה מתה מיד, \u0003ו\u0004אולם משום החטא — \u0003אינה יולדת ואינה משבחת\u0004 (מבריאה ומתייפה) כמו זו שנבדקה ונמצאה טהורה, \u0003אלא\u0004 הריהי \u0003מתנוונה\u0004 \u0005[מתנוונת]\u0006 \u0003והולכת,\u0004 עד \u0003לסוף שהיא מתה באותה מיתה\u0004 הכתובה בסוטה.","\u0003רב ששת סבר: בין ל\u0004שיטת \u0003רבי ובין ל\u0004שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 החולקים עליו \u0003הויא מתנוונה\u0004 \u0005[הריהי מתנוונת],\u0006 ואם היו המים בודקים את זו שהיו עדיה במדינת הים — היה הדבר ניכר בה בניוון, ולכן חייבים לומר שאין בודקים אותה כלל. \u0003ורב יוסף סבר: ל\u0004שיטת \u0003רבי\u0004 במקרה שהזכות תולה לה \u0003הויא מתנוונה\u0004 \u0005[הריהי מתנוונת],\u0006 אבל \u0003ל\u0004שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003לא הויא מתנוונה\u0004 \u0005[אינה מתנוונת]\u0006 ואין ניכר בה כל שינוי. ולכן אין הוכחה באשה זו שלא בדקוה המים שעדים המעידים על טומאתה הם עדי שקר, שהרי ייתכן שהזכות תלתה לה.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב שימי בר אשי,\u0004 הרי שנינו ש\u0003ר' שמעון אומר: אין זכות תולה במים המרים,\u0004 שאין זכות האשה בדברים אחרים מועילה להצילה מעונש זה. \u0003ואם אתה אומר זכות תולה במים המרים\u0004 — אם כן \u0003מדחה\u0004 (דוחה וממעט) \u0003אתה את\u0004 כוח ההרתעה של \u0003המים בפני כל הנשים השותות,\u0004 שהן סבורות שהזכות תתלה להן, ולא ימנעו אף הטמאות מלשתות. \u0003ו\u0004עוד, \u0003אתה מוציא שם רע על הטהורות ששתו\u0004 והמים לא בדקו אותה \u0003והן,\u0004 האנשים, \u0003אומרים\u0004 וחושדים בהן: שמא \u0003טמאות היו, אלא שתלה להן זכות.\u0004","\u0003ואם איתא\u0004 \u0005[יש]\u0006 מקום להלכה זו שזו ש\u0003יש לה עדים במדינת הים נמי\u0004 \u0005[גם כן]\u0006 אינה נבדקת, אם כן אפשר לומר במקרה זה: \u0003אתה מוציא שם רע על הטהורות ששתו, והן,\u0004 האנשים, \u0003אומרים: טמאות היו אלא שיש להן עדים במדינת הים\u0004 ולפיכך לא נבדקו!","ומשיבים: \u0003ל\u0004דברי \u0003ר' שמעון קאמרת\u0004 \u0005[אומר אתה]?\u0006 \u0003ל\u0004דעת \u0003ר' שמעון, מדזכות לא תליא\u0004 \u0005[מ\u0006כיון \u0005ש\u0006ה\u0005זכות אינה תולה\u0006 להן\u0005]\u0006 \u0003עדים נמי לא תלו\u0004 \u0005[גם כן אינם תולים\u0006 להן\u0005],\u0006 ומודה רב ששת שאין דבריו לשיטת ר' שמעון.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב\u0004 ממה ששנינו: \u0003ואלו\u0004 הסוטות \u0003שמנחותיהן,\u0004 מנחות סוטה, \u0003נשרפות\u0004 ואינן מוקרבות על גבי המזבח, ואינן נפדות:"],["\u0003האומרת \"טמאה אני\", ו\u0004כן זו \u0003שבאו לה עדים שהיא טמאה.\u0004","ונברר: \u0003דאתו\u0004 \u0005[שבאו]\u0006 לה \u0003עדים אימת\u0004 \u0005[מתי]?\u0006 \u0003אילימא מקמי דתקדוש\u0004 \u0005[אם תאמר\u0006 שבאו \u0005לפני שקדשה]\u0006 המנחה, כלומר, לפני שניתנה בכלי שרת — \u0003תיפוק\u0004 \u0005[תצא\u0006 המנחה\u0005]\u0006 \u0003לחולין\u0004 כמו כל מנחה שהתברר לפני שקדשה בכלי שהובאה בטעות.","\u0003אלא\u0004 יש לומר שבאו העדים \u0003לבתר דקדוש\u0004 \u0005[לאחר שקדשה]\u0006 המנחה. \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 כי ה\u0003מים בודקין אותה —\u0004 \u0003אלמא בת מקדש ומקרב\u0004 \u0005[מכאן\u0006 שהמנחה עצמה \u0005ראויה להתקדש ולהיות מוקרבת]\u0006 \u0003היא, וכי קדוש מעיקרא\u0004 \u0005[וכאשר קדשה מתחילה] —\u0006 \u0003שפיר קדוש\u0004 \u0005[יפה קדשה],\u0006 \u0003ומשום הכי\u0004 \u0005[כך]\u0006 \u0003מנחתה נשרפת,\u0004 שכבר חלה עליה קדושה, ואינה יוצאת לחולין, אך מכיון שבאו אחר כך עדים, אין להקריבה, ונשרפת.","\u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי \u0003אין המים בודקין אותה,\u0004 אם כן \u0003תיגלי מילתא\u0004 \u0005[יתברר הדבר]\u0006 \u0003למפרע דכי קדוש מעיקרא\u0004 \u0005[שכאשר קדשה\u0006 המנחה \u0005מתחילה] —\u0006 \u0003בטעות קדוש\u0004 \u0005[קדשה]\u0006 \u0003ותיפוק\u0004 \u0005[ותצא]\u0006 המנחה \u0003לחולין!\u0004 ומדוע נשרפת?","\u0003אמר רב יהודה מדיסקרתא:\u0004 יש לדחות את הראיה ולומר שמדובר שם \u0003כגון שזינתה\u0004 עם אדם אחר \u0003בעזרה\u0004 של בית המקדש לאחר שקדשה המנחה בכלי, ועל זנות זאת היו עדים, \u0003דכי קדוש מעיקרא\u0004 \u0005[שכאשר קדשה מתחילה],\u0006 על הסתירה הקודמת — \u0003שפיר קדוש\u0004 \u0005[יפה קדשה],\u0006 לפי שעל אותה סתירה לא היו עדי טומאה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב משרשיא:\u0004 כיצד יכולה לזנות בעזרה? \u0003והלא פירחי כהונה מלוין אותה!\u0004 ומשיבים: ייתכן הדבר, כגון \u0003שזינתה מפירחי כהונה עצמן.\u0004","\u0003רב אשי אמר: כגון שנצרכה לנקביה\u0004 והניחוה מלוויה ללכת לצרכיה, ושם זינתה, \u0003דאטו\u0004 \u0005[שהאם]\u0006 \u0003פירחי כהונה בכיפה\u0004 (בבית הסוהר) \u0003תלי לה\u0004 \u0005[תולים\u0006 מחזיקים, \u0005אותה]?\u0006 ואין שמירתם יכולה למונעה לגמרי מלזנות.","\u0003רב פפא אמר: לעולם\u0004 יש לפרש \u0003כדאמרינן מעיקרא\u0004 \u0005[כפי שאמרנו מתחילה],\u0006 שהעדים מעידים שנטמאה מתחילה באותה סתירה ולא בעזרה, \u0003ודקאמרת תיפוק\u0004 \u0005[ו\u0006מה \u0005שאתה אומר\u0006 שבמקרה זה אין המים בודקים ו\u0005תצא]\u0006 \u0003לחולין,\u0004 כך באמת היה צריך להיות מעיקר הדין, וזה שאינה יוצאת לחולין הוא \u0003מדרבנן\u0004 \u0005[מ\u0006דברי \u0005סופרים] —\u0006 \u0003גזירה שמא יאמרו\u0004 אנשים שאינם יודעים שהיה כאן הקדש בטעות: \u0003מוציאין\u0004 מנחה שנתקדשה \u0003מכלי שרת לחול\u0004 בלא פדיון.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב מרי\u0004 על דבריו אלה של רב פפא, שנינו: \u0003נטמאת מנחתה\u0004 של הסוטה, אם \u0003עד\u0004 ש\u0003לא קדשה בכלי —\u0004 \u0003הרי היא ככל המנחות, ותפדה. משקדשה בכלי —\u0004 \u0003הרי היא ככל המנחות, ותשרף.\u0004","אם לאחר שקדשה בכלי וקמץ הכהן ממנה, \u0003קדש הקומץ,\u0004 שנתנו בכלי \u0003ולא הספיק להקריבו עד שמת הוא\u0004 (הבעל) \u0003או עד שמתה היא\u0004 (הסוטה) — \u0003הרי היא ככל המנחות, ותשרף.\u0004","\u0003קרב הקומץ ולא הספיק\u0004 הכהן \u0003לאכול שירים עד שמת הוא או עד שמתה היא —\u0004 \u0003הרי היא ככל המנחות ותאכל\u0004 לכהנים. ומדוע נוהגים בה כבכל המנחות, והרי כיון שמת אינה שותה ובטל עניינה של המנחה — מפני \u0003ש\u0004מנחת הסוטה \u0003על הספק באת\u0004 (באה) \u0003מתחילה,\u0004 שהיא באה מתחילה על דבר שהוא ספק, \u0003כיפרה\u0004 מנחה זו את \u0003ספיקה והלכה לה\u0004 שמבחינת המנחה היה הכל כראוי, והיא כשירה.","\u0003באו לה\u0004 לפני שקרב הקומץ \u0003עדים שהיא טמאה —\u0004 \u0003מנחתה נשרפת. נמצאו עדיה\u0004 אותם שהעידו עליה שנסתרה — שהם עדים \u0003זוממין —\u0004 \u0003מנחתה חולין.\u0004 וקשה לרב פפא, שהרי יש מקרה בו מנחה שקדשה בכלי יוצאת לחולין, ואין גוזרים שמא יאמרו מוציאים מכלי שרת לחול!","ודוחים: \u0003עדים זוממין קאמרת\u0004 \u0005[אומר אתה]?!\u0006 אין להקשות מכאן כי \u0003עדים זוממין קלא אית להו\u0004 \u0005[קול יש להם],\u0006 כלומר, הדבר מתפרסם ונודע, והכל יודעים שהיה זה הקדש בטעות.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב ששת\u0004 שאין המים בודקים סוטה שיש לה עדים במדינת הים, \u0003ו\u0004אולם \u0003לאו מטעמיה\u0004 \u0005[לא מטעמו],\u0006 אלא ממקור אחר:","על הכתוב \"ואם לא נטמאה האשה וטהורה היא ונקתה ונזרעה זרע\" (במדבר ה, כח) דרשו: דווקא אם \u0003\"טהורה\"\u0004 אז \"ונקתה ונזרעה זרע\" — \u0003ולא שיש לה עדים במדינת הים,\u0004 ואינה טהורה, אבל אין המים בודקים אותה ואינה נזרעת זרע.","ועוד דורשים ממלה זו, \u0003\"וטהורה\"\u0004 הרי זו וי\"ו יתירה שבאה למעט — \u0003ולא\u0004 במקרה \u0003שתלתה לה זכות\u0004 שאז אין המים בודקים אותה מיד,","\u0003\"היא\"\u0004 למעט — \u0003ולא שישאו ויתנו בה מוזרות בלבנה,\u0004 נשים הטוות בצוותא לאור הירח, שבזמן זה מספרות זו לזו את מה שנתרחש בעיר. ואם הן יודעות שזו זנתה משמע שהדבר ידוע ומפורסם, ואת זו אין המים בודקים, לפי שאין צורך בבירור זה.","ושואלים: \u0003ור' שמעון\u0004 הסבור שאין זכות תולה לה, \u0003נהי\u0004 \u0005[אם אמנם]\u0006 שאת ה\u0003וי\"ו\u0004 כלשון יתור הוא \u0003לא דריש\u0004 \u0005[דורש]\u0006 ולכן אינו למד מכאן שהזכות תולה, \u0003והא איכא\u0004 \u0005[והרי יש]\u0006"],["\u0003יש לה עדים במדינת הים\u0004 שלמדנו מן המקרא שאין המים בודקים אותה, ואם כן נשאר החשש שמא יבואו להוציא שם רע על הנשים השותות, שמא לא נבדקו במים רק משום שיש להן עדים במדינת הים, וטמאות הן!","ומשיבים: דבר זה שעדים נמצאים במדינת הים \u0003לא שכיחא\u0004 \u0005[מצוי],\u0006 ולכן אין אנשים באים לתלות בכגון זה.","ומעתה מפרטים את סדר השקאת הסוטה. \u0003כיצד עושה לה\u0004 בעלה לאחר שהיתרה בה ונסתרה? — \u0003מוליכה לבית דין שבאותו מקום, ומוסרין לו\u0004 בית הדין \u0003שני תלמידי חכמים\u0004 להשגיח עליו \u0003שמא יבא עליה בדרך\u0004 לבית המקדש ששם משקים אותה. \u0003ר' יהודה אומר: בעלה נאמן עליה.\u0004","מדברי המשנה שמוסרים לו שני תלמידי חכמים, מדייקים שנמצאים עם האשה \u0003תרי ואיהו\u0004 \u0005[שניים והוא\u0006 הבעל\u0005] —\u0006 \u0003הא תלתא\u0004 \u0005[הרי\u0006 שנמצאים \u0005שלושה]\u0006 אנשים ביחד. \u0003לימא מסייע ליה\u0004 \u0005[\u0006האם \u0005נאמר\u0006 ש\u0005מסייע לו]\u0006 הדבר \u0003לרב.\u0004 ש\u0003אמר רב יהודה אמר רב: לא שנו\u0004 במסכת קידושין (פ, ב), שאשה מותרת להתייחד עם שני אנשים \u0003אלא\u0004 דווקא \u0003בעיר, אבל בדרך —\u0004 \u0003עד דאיכא\u0004 \u0005[שיש]\u0006 \u0003שלשה,\u0004 שאם יהיו רק שניים \u0003שמא יצטרך אחד מהן לנקביו\u0004 ויפרוש למקום אחר, \u0003ונמצא אחד מהן מתייחד עם הערוה.\u0004","ודוחים: \u0003לא, הכא\u0004 \u0005[כאן]\u0006 אין זה משום יחוד, אלא \u0003היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 \u0003כי היכי דליהוו עליה סהדי\u0004 \u0005[כדי שיהיו עליו\u0006 שני \u0005עדים]\u0006 שיעידו במקרה ויבוא עליה.","ומעירים עוד: \u0003תלמידי חכמים —\u0004 \u0003אין\u0004 \u0005[כן],\u0006 \u0003כולי עלמא\u0004 \u0005[כל העולם,\u0006 סתם אנשים\u0005] —\u0006 \u0003לא. לימא\u0004 \u0005[\u0006האם \u0005נאמר]\u0006 ש\u0003מסייע ליה\u0004 \u0005[לו]\u0006 הדבר \u0003לאידך\u0004 \u0005[ל\u0006דבר \u0005אחר]\u0006 שאמר \u0003רב.\u0004 ש\u0003אמר רב יהודה אמר רב: לא שנו\u0004 ששניים מותרים להתייחד עם אשה \u0003אלא\u0004 כשהם אנשים \u0003כשרין, אבל\u0004 כשהם \u0003פרוצין —\u0004 \u0003אפילו עשרה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא.\u0004 ומביא ראיה לדבר, \u0003מעשה היה והוציאוה עשרה\u0004 אנשים לאשה אחת \u0003במטה\u0004 כאילו היתה מתה והם מלוויה, וזנו איתה. הרי שאנשים פרוצים אפילו עשרה אינם בושים זה מזה.","ודוחים: \u0003לא,\u0004 אין מכאן ראיה, \u0003הכא היינו טעמא\u0004 \u0005[כאן זה הטעם]\u0006 שיהיו תלמידי חכמים דווקא — משום \u0003דידעי לאתרויי ביה\u0004 \u0005[שיודעים להתרות בו]\u0006 שאסור לו לבוא עליה. אבל בכלל אפשר לומר ששני אנשים סתם נאמנים על האשה, ומותרת להתייחד עימם.","שנינו במשנה ש \u0003ר' יהודה אומר: בעלה\u0004 נאמן עליה. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה אומר: בעלה נאמן מקל וחומר: ומה נדה שהיא\u0004 אסורה על בועלה \u0003ב\u0004איסור \u0003כרת —\u0004 מכל מקום \u0003בעלה נאמן עליה\u0004 והתירו לו להתייחד איתה, \u0003סוטה שהיא\u0004 אסורה עליו רק \u0003בלאו\u0004 (מצות לא תעשה) — \u0003לא כל שכן\u0004 שיהא נאמן עליה?","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 אומרים: \u0003היא הנותנת,\u0004 מטעם זה עצמו יש להחמיר, \u0003נדה\u0004 שהיא באיסור \u0003כרת —\u0004 \u0003חמירא ליה ומהימן\u0004 \u0005[חמור לו,\u0006 בעיניו, האיסור \u0005ו\u0006לכן הוא \u0005נאמן]\u0006 שלא בעל, \u0003סוטה ש\u0004יש בה רק איסור \u0003לאו —\u0004 \u0003לא חמירא ליה\u0004 \u0005[חמור לו,\u0006 בעיניו\u0005],\u0006 \u0003ו\u0004לכך הוא \u0003לא מהימן\u0004 \u0005[נאמן].\u0006","ושואלים: \u0003ור' יהודה מקל וחומר מייתי לה\u0004 \u0005[מביא,\u0006 לומד \u0005אותה]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' יהודה מקראי מייתי לה\u0004 \u0005[מן הכתובים\u0006 הוא \u0005לומד אותה]!\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 על הכתוב \u0003\"והביא האיש את אשתו אל הכהן\"\u0004 (במדבר ה, טו), \u0003מן התורה האיש\u0004 עצמו \u0003מביא את אשתו, אבל אמרו חכמים: מוסרין לו שני תלמידי חכמים\u0004 שיילכו עמהם, \u0003שמא יבא עליה בדרך.\u0004","\u0003ר' יוסי אומר: בעלה נאמן עליה מקל וחומר: ומה נדה שהיא בכרת —\u0004 \u0003בעלה נאמן עליה, סוטה שהיא בלאו —\u0004 \u0003לא כל שכן?\u0004","\u0003אמרו לו: לא, אם אמרת בנדה\u0004 שנאמן, \u0003שכן יש לה היתר\u0004 לאחר זמן, כשתטבול, \u0003תאמר בסוטה שאין לה היתר,\u0004 שנאסרה עליו לעולם אם זנתה. \u0003ו\u0004ראיה לכך מהכתוב ה\u0003אומר \"מים גנובים ימתקו\u0004 ולחם סתרים ינעם\u0003\"\u0004 (משלי ט, יז). ואף סוטה האסורה לעולם (\"מים גנובים\") יש חשש שיבוא עליה.","\u0003ר' יהודה אומר: מן התורה האיש מביא את אשתו אל הכהן שנאמר: \"והביא האיש את אשתו\"\u0004 ואין צורך בתלמידי חכמים שילווהו. הרי שר' יהודה לומד דין זה מן המקרא עצמו!","ומתרצים: \u0003אמר להו\u0004 \u0005[להם]\u0006 ר' יהודה לחכמים \u0003קל וחומר ברישא\u0004 \u0005[תחילה]\u0006 \u0003ופרכוה\u0004 \u0005[ושברו אותו]\u0006 כפי שאמרנו, \u0003והדר\u0004 \u0005[וחזר]\u0006 ו\u0003אמר להו קרא\u0004 \u0005[להם כתוב].\u0006","ושואלים: \u0003ר' יהודה היינו\u0004 \u0005[זוהי]\u0006 שיטת ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 בברייתא שאמר: מן התורה אדם מביא את אשתו אל הכהן! ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 בהמשך, של \u0003\"אבל אמרו\",\u0004 שלדעת התנא הראשון תיקנו חכמים בכל זאת שיהיו תלמידי חכמים מביאים אותה, ולדעת ר' יהודה לא תיקנו תקנה זו.","\u0003היו מעלין אותה,\u0004 את האשה, \u0003לבית דין הגדול שבירושלים, ומאיימין עליה\u0004 שתודה על האמת \u0003כדרך שמאיימין על עדי נפשות\u0004 שמסבירים להם את חומרת המעשה שהם עושים.","\u0003ואומר לה\u0004 הדיין, כדי להקל עליה להודות: \u0003בתי, הרבה יין עושה\u0004 (גורם) שתבוא אשה לזנות, \u0003הרבה שחוק עושה, הרבה ילדות\u0004 (נערות, גיל צעיר) \u0003עושה, הרבה שכנים הרעים עושין,\u0004 לומר לה שהוא מבין שלא כל האשמה תלויה בה, אלא היו גורמים אחרים לדבר.","\u0003עשי לשמו הגדול\u0004 של הקדוש ברוך הוא \u0003שנכתב בקדושה\u0004 ש\u0003לא ימחה על המים,\u0004 שהרי אם מודה שזנתה — שוב אין מוחקים את המגילה, שכתוב בה שם ה', בתוך המים. \u0003ואומר לפניה דברים שאינם כדי לשומען\u0004 (שאינם ראויים לשמעם) \u0003היא וכל משפחת בית אביה,\u0004 וכל זה לפייס אותה כדי שתודה.","\u0003אם אמרה\u0004 לאחר כל אלה \u0003\"טמאה אני\" —\u0004 \u0003שוברת כתובתה,\u0004 כלומר, כותבת שובר (קבלה) שאין לה עוד תביעות מבעלה, והפסידה כתובתה, \u0003ויוצאת\u0004 (מתגרשת מבעלה).","\u0003ואם אמרה \"טהורה אני\" —\u0004 \u0003מעלין אותה לשער המזרח שעל פתח שער נקנור, ששם\u0004 היו עושים שלושה דברים: \u0003משקין את הסוטות, ומטהרין את היולדות, ומטהרין את המצורעין.\u0004","\u0003וכהן אוחז בבגדיה\u0004 ומושכם, \u0003אם נקרעו\u0004 הבגדים — \u0003נקרעו, ואם נפרמו\u0004 התפרים — \u0003נפרמו, עד שהוא מגלה את לבה\u0004 בקריעה זו. \u0003וסותר את\u0004 המקלעת שקלוע בה \u0003שערה. ר' יהודה אומר: אם היה לבה נאה —\u0004 \u0003לא היה מגלהו, ואם היה שערה נאה —\u0004 \u0003לא היה סותר\u0004 אותו.","אם \u0003היתה\u0004 כרגיל \u0003מתכסה בלבנים —\u0004 \u0003מכסה\u0004 עכשיו \u0003ב\u0004בגדים \u0003שחורים. היה עליה כלי זהב\u0004"],["\u0003וקטליאות\u0004 (תכשיטים), \u0003נזמים, וטבעות —\u0004 \u0003מעבירין\u0004 (מסירים) אותם \u0003ממנה, כדי לנוולה\u0004 (לכערה ולבזותה). \u0003ואחר כך מביא חבל מצרי\u0004 (עשוי מסיבי דקל) \u0003וקושרו למעלה מדדיה,\u0004 כדי שלא יישמטו בגדיה לגמרי,","\u0003וכל הרוצה לראות\u0004 את הדבר \u0003בא לראות, חוץ מעבדיה ושפחותיה\u0004 שאין באים לראותה, \u0003מפני שלבה גס בהן\u0004 שמפני שרגילה בהם אינה מתביישת מהם ואף מתחזקת על ידם. \u0003וכל הנשים מותרות לראותה, שנאמר: \"ונוסרו כל הנשים ולא תעשינה כזמתכנה\"\u0004 (יחזקאל כג, מח).","שואלים: \u0003מנהני מילי\u0004 \u0005[מניין הדברים הללו]\u0006 שמביאים אותה לבית דין הגדול דווקא? \u0003אמר ר' חייא בר גמדא אמר ר' יוסי בר' חנינא: אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 הדבר בגזירה שווה \u0003\"תורה\" \"תורה\": כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 בפרשת סוטה \u0003\"ועשה לה הכהן את כל התורה\"\u0004 (במדבר ה, ל), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בענין זקן ממרא שיש ללכת אל המקום אשר יבחר ה', ולשאול מן השופט, ולברר את המשפט \u0003\"על פי התורה אשר יורוך\"\u0004 (דברים יז, יא), \u0003מה להלן\u0004 שנאמר \"על פי התורה אשר יורוך\" כוונתו \u0003ב\u0004בית דין של \u0003שבעים ואחד\u0004 איש שהוא סנהדרין גדולה — \u0003אף כאן\u0004 בסוטה המדובר הוא \u0003ב\u0004בית דין של \u0003שבעים ואחד.\u0004","שנינו במשנה כי משדלים \u0003ומאיימין עליה\u0004 שתודה על מנת שלא תשתה. \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 \u0003מראים סתירה\u0004\u0005]\u0006 ממה ששנינו: \u0003כדרך שמאיימין עליה\u0004 ש\u0003לא\u0004 \u0003תשתה —\u0004 \u0003כך מאיימין עליה שתשתה. אומרים לה: בתי, אם ברור לך הדבר שטהורה את —\u0004 \u0003עמדי על בוריך\u0004 (על בריאותך, על תוקפך) \u0003ושתי.\u0004 ואין לך ממה לחשוש \u0003לפי שאין מים המרים דומין אלא לסם יבש שמונח על בשר חי, אם יש שם מכה\u0004 (פצע) במקום — \u0003מחלחל\u0004 הסם \u0003ויורד\u0004 ומזיק, \u0003אין שם מכה —\u0004 \u0003אינו מועיל\u0004 (פועל) \u0003כלום.\u0004 הרי שיש כאן גם איום שתשתה!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003כאן\u0004 שאמרנו שמאיימים עליה שלא תשתה לכתחילה — הרי זה \u0003קודם שנמחקה\u0004 ה\u0003מגילה,\u0004 כדי למנוע מחיקת השם. \u0003כאן\u0004 שאמרנו שמשדלים אותה שתשתה — הרי זה \u0003לאחר שנמחקה\u0004 ה\u0003מגילה,\u0004 שאם תודה או תמנע עכשיו מלשתות נמצא שנמחקה המגילה לחינם.","שנינו במשנה: \u0003ואומר לפניה\u0004 הדיין דברים שאינה ראויה לשמעם. כהסבר לכך מביאים מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אומר לפניה דברים של הגדה, ומעשים שאירעו בכתובים הראשונים, כגון\u0004 הגדה זאת שדרשו על הפסוק \u0003\"אשר חכמים יגידו ולא כחדו מאבותם\"\u0004 (איוב טו, יח), שאף בזמן האבות היו שהודו בחטאם.","\u0003יהודה הודה\u0004 בחטאו עם תמר \u0003ולא בוש, מה היה סופו —\u0004 \u0003נחל חיי העולם הבא. ראובן הודה\u0004 בכך שבא על בלהה פילגש אביו \u0003ולא בוש, מה היה סופו —\u0004 \u0003נחל חיי העולם הבא. ומה שכרן?\u0004 ותוהים: \u0003מה שכרן?! כדקא אמרינן\u0004 \u0005[כפי שאמרנו]\u0006 שנחלו חיי העולם הבא! \u0003אלא\u0004 הכוונה היתה: \u0003מה שכרן בעולם הזה,\u0004 ועל כך נאמר \u0003\"להם לבדם נתנה הארץ\u0004 \u0003ולא עבר זר בתוכם\"\u0004 (איוב טו, יט).","ודנים בברייתא זו. \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ביהודה אשכחן דאודי\u0004 \u0005[מצאנו שהודה]\u0006 על חטאו, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ויכר יהודה ויאמר צדקה ממני\"\u0004 (בראשית לח, כו), \u0003אלא ראובן מנלן דאודי\u0004 \u0005[מניין לנו שהודה]?\u0006","ומשיבים: ש\u0003אמר ר' שמואל בר נחמני אמר ר' יוחנן: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 בברכת משה לשבטים בסוף ימיו \u0003\"יחי ראובן ואל ימת\"\u0004 (דברים לג, ו) ומיד אחר כך נאמר \u0003\"וזאת ליהודה\u0004 ויאמר שמע ה' קול יהודה ואל עמו תביאנו יד רב לו ועזר מצריו תהיה\u0003\"\u0004(דברים לג, ז)? מה הקשר בין ברכת ראובן לברכת יהודה שבגללו היא מתחילה בוי\"ו החיבור \"וזאת ליהודה\"?","ויש להסביר: \u0003כל אותן שנים שהיו ישראל במדבר היו עצמותיו של יהודה\u0004 שהעלו אותם בני ישראל ממצרים \u0003מגולגלין בארון,\u0004 שהתפרקו העצמות שבשלד, \u0003עד שעמד משה ובקש עליו רחמים. אמר לפניו: רבונו של עולם, מי גרם לראובן שהודה\u0004 על חטאו — \u0003יהודה, \"וזאת ליהודה\",\u0004 כלומר, האם זהו שכרו של יהודה שיהיו עצמותיו מגולגלות?!","\u0003מיד \"שמע ה' קול יהודה\"\u0004 (דברים לג, ז). \u0003על איבריה לשפא\u0004 \u0005[נכנסו איבריו למקומם]\u0006 ונתחברו העצמות, \u0003ו\u0004עדיין \u0003לא הוה קא מעיילין ליה למתיבתא דרקיעא\u0004 \u0005[היו מכניסים אותו לישיבה של\u0006 מעלה ב\u0005רקיע],\u0006 ביקש עליו משה \u0003\"ואל עמו תביאנו\"\u0004 (דברים לג, ז). הכניסוהו \u0003ולא הוה קא ידע משקל ומטרח בשמעתא בהדי רבנן\u0004 \u0005[היה יודע לשאת ולתת בהלכה עם החכמים\u0006 בישיבה שם\u0005],\u0006 ביקש עליו \u0003\"ידיו רב לו\"\u0004 (דברים לג, ז). \u0003לא הוה קא סלקא ליה שמעתא אליבא דהילכתא\u0004 \u0005[היתה עולה לו השמועה לפי ההלכה],\u0006 על כן ביקש עליו \u0003\"ועזר מצריו תהיה\"\u0004 (דברים לג, ז).","ועוד שואלים בנושא זה: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003יהודה דאודי כי היכי\u0004 \u0005[שהודה,\u0006 עשה כן \u0005כדי]\u0006 ש\u0003לא\u0004 \u0003תישרף תמר, אלא ראובן למה ליה דאודי\u0004 \u0005[לו שהודה]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב ששת: חציף\u0004 \u0005[חצוף]\u0006 \u0003עלי,\u0004 בעיני \u0003מאן דמפריט חטאיה\u0004 \u0005[מי שמפרט\u0006 את \u0005חטאו]\u0006 ומודיעו לרבים. ומדוע הודה ראובן? די היה בכך שיעשה תשובה! ומשיבים: הסיבה לכך שהודה במעשה היתה \u0003כי היכי דלא ליחשדו אחוהי\u0004 \u0005[כדי שלא ייחשדו אחיו]\u0006 במעשה זה שהם עשאוהו.","שנינו במשנה: \u0003אם אמרה\u0004 הסוטה \u0003\"טמאה אני\"\u0004 — שוברת את כתובתה. ומעירים: \u0003שמעת מינה\u0004 \u0005[לומד אתה מכאן]\u0006 מלשון המשנה \"שוברת\", כי \u0003כותבין שובר\u0004 כהוכחה של פרעון שטר, ואין קורעים את שטר החוב, שדבר זה שנוי במחלוקת חכמים.","\u0003אמר אביי, תני\u0004 \u0005[שנה]:\u0006 \u0003מקרעת\u0004 כתובתה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: והא\u0004 \u0003[והרי]\u0004 \u0003\"שוברת\" קתני\u0004 \u0005[שנה]!\u0006 \u0003אלא אמר רבא: במקום שאין כותבין כתובה עסקינן\u0004 \u0005[עוסקים אנו],\u0006 אלא סומכים על מה שתיקנו חכמים לתת כתובה כשמגרש את אשתו או כשמת. וכדי להוכיח שאין לבעל עוד התחייבות של כתובה חייבים לכתוב שובר.","שנינו במשנה: \u0003ואם אמרה \"טהורה אני\" מעלין אותה לשערי מזרח.\u0004 ותוהים: \u0003מעלין אותה?!\u0004"],["\u0003התם קיימא\u0004 \u0005[שם\u0006 היא \u0005עומדת]\u0006 בעזרה, שהרי שם יושב בית הדין! ומשיבים: \u0003דמסקינן לה ומחתינן לה\u0004 \u0005[שמעלים אותה ומורידים אותה]\u0006 \u0003כדי לייגעה,\u0004 שמא מתוך כך תודה מעצמה. \u0003דתניא\u0004 \u0003[ש\u0004כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 כעין סיבה זו: \u0003ר' שמעון בן אלעזר אומר: בית דין מסיעין את העדים\u0004 בדיני נפשות \u0003ממקום למקום, כדי שתטרף\u0004 (תתבלבל) \u0003דעתן עליהן ויחזרו בהן\u0004 ממה שהעידו אם היו משקרים.","שנינו במשנה \u0003ששם,\u0004 בשער המזרח, \u0003משקין את הסוטות\u0004 ומטהרים את המצורעים והיולדות. ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003סוטות\u0004 צריכות לעמוד שם, משום \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והעמיד הכהן את האשה לפני ה'\"\u0004 (במדבר ה, יח) ושער המזרח הוא בדיוק ממול הקודש (\"לפני ה'\"), \u0003מצורעין נמי\u0004 \u0005[גם כן]\u0006 עומדים שם, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והעמיד הכהן המטהר\u0004 את האיש המיטהר... לפני ה'\u0003\"\u0004 (ויקרא יד, יא), \u0003אלא יולדת מאי טעמא\u0004 \u0005[מה טעם]\u0006 עומדת היא שם?","\u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום דאתיין וקיימין אקורבנייהו\u0004 \u0005[ש\u0006היולדות \u0005באות ועומדות על קורבנן],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין קרבנו של אדם קרב אלא אם כן\u0004 בעליו \u0003עומד על גביו\u0004 בשעת הקרבתו, וכיון שלפני הבאת הקרבן אסור להן להכנס למקדש, כדין מחוסרי כפרה, לכן הן עומדות בשער המזרח שמותר להן לעמוד בו. אולם \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אם זו הסיבה — \u0003זבין וזבות\u0004 שגם הם מחוסרי כפרה \u0003נמי\u0004 \u0005[גם כן]\u0006 שיבואו לשם! ומשיבים: \u0003אין הכי נמי\u0004 \u0005[כן, כך\u0006 הוא \u0005גם כן]\u0006 \u0003ו\u0004ה\u0003תנא חדא מינייהו נקט\u0004 \u0005[אחת מהם אחז]\u0006 לדוגמה, ואף שאר מחוסרי כפרה בכלל.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין משקין שתי סוטות כאחת, כדי שלא יהא לבה\u0004 של האחת \u0003גס בחבירתה\u0004 שכשרואה שיש אחרת עימה שאינה מודה, אף היא מתחזקת ואינה מתביישת ואינה מודה. \u0003ר' יהודה אומר: לא מן השם הוא זה,\u0004 לא זה הטעם, \u0003אלא אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"והקריב \u0003אתה\u0004 הכהן והעמידה לפני ה'\" (במדבר ה, טז), \"אותה\" — משמע \u0003לבדה.\u0004","ושואלים: \u0003ו\u0004ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 מה הוא אומר על כך? \u0003הכתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"אתה\"\u0004 להדגשה והטעם ששותה לבד אינו משום שליבה גס בחבירתה אלא גזירת הכתוב! ומשיבים: דעת ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 דעת \u0003ר' שמעון היא, דדריש\u0004 \u0005[שדורש]\u0006 את \u0003טעם דקרא\u0004 \u0005[הכתוב]\u0006 ומה שאמר — בלשון \u0003ומה טעם קאמר\u0004 \u0005[אומר]:\u0006 \u0003מה טעם\u0004 הדגישה תורה \u0003\"אותה\" לבדה —\u0004 \u0003כדי\u0004 ש\u0003לא יהא לבה גס בחבירתה.\u0004","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם\u0006 למעשה\u0005]\u0006 אם הטעם הוא משום לבה גס בחבירתה או שזו גזירת הכתוב? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל לגבי אשה שהיתה \u0003רותתת\u0004 (רועדת) מפחד ובכל זאת אינה מודה, שבמקרה כזה הרי עינינו רואות שאין לבה גס בה, ולשיטת ר' שמעון אין צורך להשקותה לבדה.","\u0003ו\u0004שואלים: אפילו אם היתה \u0003רותתת מי\u0004 \u0005[האם]\u0006 \u0003משקין\u0004 שתים בבת אחת? \u0003והא\u0004 \u0005[והרי]\u0006 יש טעם אחר שלא להשקות שתים כאחת, שהרי אמרו \u0003אין עושין\u0004 \u0003מצות חבילות חבילות,\u0004 שאם אינו עושה כל מצוה לעצמה הרי זה מזלזל בכבוד המצוות.","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003אין משקין שתי סוטות כאחת, ואין מטהרין שני מצורעין כאחת, ואין רוצעין שני עבדים כאחת, ואין עורפין שתי עגלות כאחת, לפי שאין עושין מצות חבילות חבילות.\u0004 ואם כן אף לשיטת ר' שמעון בכל מקרה אין משקים שתי סוטות כאחת, ונמצא שאין הבדל בין שיטתו לשיטת ר' יהודה!","\u0003אמר אביי ואיתימא\u0004 \u0005[ויש אומרים]\u0006 \u0003רב כהנא: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003כאן בכהן אחד\u0004 לכל הדעות אינו משקה שתי סוטות בבת אחת. \u0003כאן בשני כהנים\u0004 אין כאן עשיית מצוות חבילות, ולדעת ר' שמעון אם אחת מהן רותתת אפשר להשקות את שתיהן בבת אחת.","שנינו במשנה: \u0003והכהן אוחז בבגדיה\u0004 וקורעם או פורמם... עד שהוא מגלה את ליבה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 על מה שנאמר \u0003\"ופרע את ראש האשה\"\u0004 (במדבר ה, יח)\u0003,\u0004 \u0003אין לי\u0004 שהכהן פורע (מגלה) \u0003אלא\u0004 את \u0003ראשה, גופה מנין\u0004 שהוא פורע — \u0003תלמוד לומר: \"האשה\"\u0004 לרבות שאר חלקי גופה. \u0003אם כן מה תלמוד לומר\u0004 באופן מיוחד \u0003\"ופרע את ראשה\" —\u0004 \u0003מלמד שהכהן\u0004 לא רק מגלה את שערה, אלא גם \u0003סותר את שערה\u0004 אם היה קלוע.","שנינו במשנה ש\u0003ר' יהודה אומר: אם היה לבה\u0004 (חזה) נאה — לא היה מגלהו ואם היה שערה נאה לא היה סותר. ושואלים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 ש\u0003ר' יהודה חייש להרהורא\u0004 \u0005[חושש להרהור\u0006 עבירה\u0005]\u0006 ולכן אוסר לגלות שיער או לב נאה, \u0003ורבנן לא חיישי\u0004 \u0005[וחכמים אינם חוששים]\u0006 לכך?","\u0003והא איפכא שמעינן להו\u0004 \u0005[והרי ההיפך\u0006 מזה \u0005שמענו אותם\u0006 אומרים\u0005],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003האיש\u0004 שנתחייב סקילה, סוקלים אותו ערום ובכל זאת \u0003מכסין אותו פרק\u0004 (חתיכת בד) \u0003אחד מלפניו\u0004 במקום הערוה, \u0003;והאשה\u0004 מכסים אותה \u0003שני פרקים, אחד מלפניה ואחד מלאחריה, מפני שכולה ערוה,\u0004 גם מאחוריה, אלו \u0003דברי ר' יהודה. וחכמים אומרים: האיש נסקל\u0004 כשהוא \u0003ערום, ואין האשה נסקלת\u0004 כשהיא \u0003ערומה\u0004 כלל, אלא כשהיא לבושה!","\u0003אמר רבה:\u0004 בדרך כלל אין ר' יהודה חושש להרהור עבירה, אלא \u0003הכא טעמא מאי\u0004 \u0005[כאן טעם\u0006 הדבר \u0005מהו] —\u0006 \u0003שמא תצא מבית דין זכאית, ויתגרו בה פרחי כהונה\u0004 המצויים בבית המקדש ורואים אותה חשופה. \u0003התם\u0004 \u0005[שם]\u0006 הנסקלת — \u0003הא מסתלקא\u0004 \u0005[הרי\u0006 היא \u0005מסתלקת]\u0006 מן העולם בסקילתה ואין מקום להרהור. \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003אתי לאיגרויי באחרנייתא\u0004 \u0005[באים\u0006 על ידי כך \u0005להתגרות באחרות] —\u0006 \u0003האמר\u0004 \u0005[הרי אמר]\u0006 \u0003רבא: גמירי\u0004 \u0005[למודים\u0006 אנו\u0005]\u0006 ש\u0003אין יצר הרע שולט אלא במה שעיניו רואות.\u0004","\u0003אמר רבא:\u0004 וכי מדברי \u0003ר' יהודה אדר'\u0004 \u0005[על\u0006 דברי \u0005ר']\u0006 \u0003יהודה קשיא\u0004 \u0005[קשה],\u0006 \u0003דרבנן אדרבנן לא קשיא\u0004 \u0005[מ\u0006דברי \u0005חכמים על\u0006 דברי \u0005חכמים לא קשה]?\u0006 הלא גם בסברתם יש סתירה — האם חוששים או אין חוששים להרהור! \u0003אלא אמר רבא: דר' יהודה אדר' יהודה\u0004 \u0005[מ\u0006דברי \u0005ר' יהודה על\u0006 דברי \u0005ר' יהודה]\u0006 \u0003לא קשיא\u0004 \u0005[קשה],\u0006 \u0003כדשנין\u0004 \u0005[כפי שתירצנו],\u0006"],["\u0003דרבנן אדרבנן נמי לא קשיא\u0004 \u0005[מ\u0006דברי \u0005חכמים על\u0006 דברי \u0005חכמים גם כן אינו קשה];\u0006 \u0003הכא טעמא מאי\u0004 \u0005[כאן\u0006 בסוטה \u0005מהו הטעם]\u0006 שמבזים אותה בגילוי שערה וגופה — \u0003משום \"ונוסרו כל הנשים\"\u0004 (יחזקאל כג, מח), כדי להזהיר נשים אחרות. \u0003התם\u0004 \u0005[שם]\u0006 בסקילה — \u0003אין לך\u0004 כלפי הנשים הרואות אותה \u0003ייסור\u0004 (הפחדה) \u0003גדול מזה\u0004 מעצם הסקילה.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003לעביד בה תרתי\u0004 \u0005[שיעשו בה שנים]\u0006 גם סקילה וגם בזיון — \u0003אמר רב נחמן אמר רב בר אבוה, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ואהבת לרעך כמוך\"\u0004 (ויקרא יט, יח), לומר: אם עליך להורגו, \u0003ברור לו מיתה יפה.\u0004","ושואלים: \u0003לימא\u0004 \u0005[האם לומר]\u0006 שדברי \u0003רב נחמן תנאי היא\u0004 \u0005[\u0006במחלוקת \u0005תנאים הם\u0006 שנויים\u0005]\u0006 ולדעת ר' יהודה אין ציווי לברור לו מיתה יפה? ודוחים: \u0003לא,\u0004 אפשר לומר \u0003דכולי עלמא אית להו\u0004 \u0005[שהכל יש להם,\u0006 מקבלים, את שיטת\u0005]\u0006 \u0003רב נחמן. והכא בהא קמיפלגי\u0004 \u0005[וכאן בזה\u0006 הם \u0005חלוקים];\u0006 \u0003מר סבר\u0004 \u0005[חכם זה\u0006 חכמים \u0005סבור]:\u0006 \u0003בזיוניה\u0004 \u0005[בזיונו]\u0006 של אדם \u0003עדיף ליה\u0004 \u0005[לו]\u0006 חמור לו \u0003טפי מצערא דגופיה\u0004 \u0005[יותר מצער גופו]\u0006 ולפיכך מיתה יפה היא שנמנעת מכל בזיון, למרות שעל ידי הלבוש, שבולם את עוצמת החבטה, מתעכבת מיתתה מעט. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' יהודה, \u0005סבור]:\u0006 \u0003צערא דגופיה\u0004 \u0005[צער גופו]\u0006 \u0003עדיף ליה\u0004 \u0005[לו]\u0006 חמור לו לאדם \u0003טפי מבזיוניה\u0004 \u0005[יותר מבזיונו]\u0006 ולכן היא מעדיפה שלא תצטער בסקילה, אף שיש לה בזיון בעירום.","שנינו במשנה: אם \u0003היתה מכוסה\u0004 בבגדים \u0003לבנים\u0004 — מכסה בשחורים. \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003אם היו\u0004 בגדים \u0003שחורים נאים לה —\u0004 \u0003מכסין אותה בגדים מכוערים.\u0004","עוד שנינו במשנה שאם \u0003היו עליה כלי זהב\u0004 (תכשיטים) — מסירים אותם מעליה. ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 \u0003השתא נוולי מנוויל לה, הני מיבעיא\u0004 \u0005[עכשיו\u0006 הרי הוא \u0005מנוול אותה\u0006 בכל מיני בזיון, \u0005אלה,\u0006 תכשיטי הזהב, \u0005נצרכה\u0006 המשנה\u0005]\u0006 לומר שלא ישאירם עליה? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003בהני\u0004 \u0005[באלה],\u0006 בעוד התכשיטים עליה, \u0003אית\u0004 \u0005[יש]\u0006 \u0003לה בזיון טפי\u0004 \u0005[יתר],\u0006 \u0003כדאמרי אינשי\u0004 \u0005[כפי שאומרים אנשים\u0006 בפתגם מקובל\u0005]:\u0006 \u0003שליח ערטיל וסיים מסאני\u0004 \u0005[מופשט\u0006 ערום \u0005ולובש נעליים],\u0006 שלבוש הנעלים מדגיש את העירום. ואף כאן — התכשיטים ידגישו את הניוול, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שלא.","שנינו במשנה: \u0003ואחר כך מביא חבל\u0004 מצרי וקושרו. \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' אבא מרב הונא: חבל המצרי מהו שיעכב בסוטה?\u0004 וצדדי השאלה: האם טעם החבל הוא \u0003משום\u0004 ש\u0003לא\u0004 \u0003ישמטו בגדיה מעליה הוא, ובצלצול\u0004 (שרוך, רצועה) \u0003קטן נמי סגי\u0004 \u0005[גם כן די],\u0006 \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003משום\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 בטעמו של דבר: \u0003היא חגרה לו,\u0004 לפני זה שנסתרה עמו, את עצמה \u0003בצלצול\u0004 (בסרט נאה) \u0003לפיכך כהן מביא חבל המצרי וקושר לה למעלה מדדיה,\u0004 ולכן הוא \u0003מעכב?\u0004","\u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003תניתוה\u0004 \u0005[שניתם אותה]\u0006 במפורש: \u0003ואחר כך מביא חבל המצרי וקושרו לה למעלה מדדיה כדי\u0004 ש\u0003לא\u0004 \u0003ישמטו בגדיה מעליה\u0004 — משמע שזהו עיקר הטעם, ולפיכך חבל המצרי אינו מעכב.","שנינו במשנה: \u0003וכל הרוצה לראות בה יראה.\u0004 מעירים: \u0003הא גופא קשיא\u0004 \u0005[היא עצמה קשה],\u0006 שיש סתירה פנימית בהלכה זו. \u0003אמרת\u0004 מצד אחד: \u0003כל הרוצה לראות בה רואה, אלמא\u0004 \u0005[מכאן]\u0006 \u0003לא שנא גברי ולא שנא נשי\u0004 \u0005[אין\u0006 זה \u0005שונה גברים, ואין\u0006 זה \u0005שונה נשים],\u0006 שהכל שווים בכך, \u0003והדר תני\u0004 \u0005[וחזר\u0006 ו\u0005שנה]:\u0006 \u0003כל הנשים מותרות לראותה,\u0004 משמע: \u0003נשים —\u0004 \u0003אין\u0004 \u0003[כן],\u0004 \u0003אנשים —\u0004","\u0003לא! אמר אביי: תרגמה אנשים\u0004 \u0005[תרגם,\u0006 הסבר \u0005אותה על נשים].\u0006 כלומר, כל אשה הרוצה לראותה מותרת. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: והא\u0004 \u0005[והרי]\u0006 \u0003\"כל הרוצה לראות בה רואה\" קתני\u0004 \u0005[שנה],\u0006 וגברים בכלל זה!","\u0003אלא אמר רבא: כל הרוצה לראות בה —\u0004 \u0003רואה, לא שנא גברי ולא שנא נשי\u0004 \u0005[אין\u0006 זה \u0005שונה\u0006 ב\u0005גברים ואין\u0006 זה \u0005שונה\u0006 ב\u0005נשים],\u0006 \u0003ו\u0004אולם \u0003נשים חייבות לראותה, שנאמר \"ונוסרו כל הנשים ולא תעשינה כזמתכנה\"\u0004 (יחזקאל כג, מח).","בהמשך לדיני הסוטה מביאים דברי מוסר כלליים הנלמדים מכאן. \u0003במדה שאדם מודד —\u0004 \u0003בה מודדין לו; היא\u0004 הסוטה \u0003קשטה את עצמה\u0004 כדי \u0003ל\u0004עבור \u0003עבירה\u0004 על כן \u0003המקום\u0004 (הקדוש ברוך הוא) \u0003נוולה. היא גלתה את עצמה לעבירה\u0004 שעמדה במקום שתיראה לנואפים — \u0003המקום גלה עליה,\u0004 שמעמידים אותה בבזיון בפני רבים. \u0003בירך התחילה בעבירה תחילה, ואחר כך הבטן —\u0004 \u0003לפיכך תלקה הירך תחילה, ואחר כך הבטן, ושאר כל הגוף לא פלט\u0004 (לא ניצל) מפורענות.","\u0003אמר רב יוסף: אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003מדה\u0004 עצמה \u0003בטילה,\u0004 שאין בית דין בזמן הזה רשאי לדון ולהעניש בעונשי גוף כדין המפורש בהם, מכל מקום \u0003במדה,\u0004 בדין שראוי להיענש \u0003לא בטיל\u0004 \u0005[בטל],\u0006 ואדם נענש משמים כראוי לחטאיו.","ש\u0003אמר רב יוסף, וכן תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא: מיום שחרב בית המקדש, אף על פי שבטלה סנהדרי —\u0004 \u0003ארבע מיתות לא בטלו.\u0004 ותוהים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003בטלו! אלא,\u0004 הכוונה היא: \u0003דין ארבע מיתות לא בטלו\u0004 מן המציאות, כיצד?","\u0003מי שנתחייב סקילה —\u0004 \u0003או נופל מן הגג\u0004 בדומה למה שעושים תחילה לנידון בסקילה, \u0003או חיה דורסתו\u0004 ומשברת את איבריו. \u0003מי שנתחייב שריפה —\u0004 \u0003או נופל בדליקה\u0004 ונשרף, \u0003או נחש מכישו\u0004 שיש בזה תחושת שריפה כמו בשריפה ממש. \u0003מי שנתחייב הריגה\u0004 בחרב — \u0003או נמסר למלכות\u0004 והם הורגים אותו בחרב, \u0003או ליסטין\u0004 (שודדים) \u0003באין עליו\u0004 ורוצחים אותו. \u0003מי שנתחייב חניקה —\u0004 \u0003או טובע בנהר\u0004 ונחנק במים, \u0003או מת בסרונכי\u0004 (אסכרה), שנחנק בגרונו על ידי מחלה זו.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003היה רבי אומר: מנין שבמדה שאדם מודד בה מודדין לו\u0004 — \u0003שנאמר: \"בסאסאה בשלחה תריבנה\"\u0004 (ישעיה כז, ח), כלומר, במידה (סאה) שנהג בה — בה הוא נענש (\"תריבנה\").","\u0003אין לי אלא סאה\u0004 שהיא מידה גדולה, \u0003מנין לרבות תרקב\u0004 (חצי סאה) \u0003וחצי תרקב, קב וחצי קב, רובע\u0004 הקב \u0003וחצי רובע, תומן\u0004 (שמינית הקב) \u0003ועוכלא\u0004 שהיא אחת משלושים ושתים בקב \u0003מנין —\u0004 \u0003תלמוד לומר: \"כי כל סאון סאן ברעש\"\u0004 (ישעיה ט, ד), שהוא מפרש \"סאון\" סאה קטנה, שאפילו על עבירה קטנה אין מוותרים לאדם.","\u0003ומנין שכל פרוטה ופרוטה מצטרפת לחשבון גדול,\u0004 שגם אם אינו נענש מיד על העבירות הקטנות, בסופו של דבר הכל מצטרף לעונש חמור — \u0003תלמוד לומר: \"אחת לאחת למצא חשבון\"\u0004 (קהלת ז, כז).","\u0003וכן מצינו בסוטה, שבמדה שמדדה —\u0004 \u0003בה מדדו לה; היא עמדה על פתח ביתה ליראות לו\u0004 לנואף — \u0003לפיכך כהן מעמידה על שער נקנור ומראה קלונה לכל. היא פרסה לו\u0004 (עבורו) \u0003סודרין נאין על ראשה —\u0004 \u0003לפיכך כהן נוטל\u0004 (מוריד) \u0003כפה מעל ראשה ומניחו תחת רגליה. היא קשטה לו פניה —\u0004 \u0003לפיכך\u0004"],["\u0003פניה מוריקות,\u0004 שצבע פניה משתנה לירוק לאחר ששותה. \u0003היא כחלה לו\u0004 בכוחל וייפתה את \u0003עיניה —\u0004 \u0003לפיכך עיניה בולטות\u0004 לאחר ששותה. \u0003היא קלעה לו את שערה —\u0004 \u0003לפיכך כהן סותר את שערה. היא הראתה לו באצבע,\u0004 שרמזה לו לבוא אליה — \u0003לפיכך ציפורניה נושרות, היא חגרה לו בצילצול\u0004 (בסרט, חגורה) — \u0003לפיכך כהן מביא חבל המצרי וקושר לה למעלה מדדיה. היא פשטה לו את יריכה —\u0004 \u0003לפיכך יריכה נופלת.\u0004","\u0003היא קיבלתו על כריסה —\u0004 \u0003לפיכך בטנה צבה. היא האכילתו מעדני עולם —\u0004 \u0003לפיכך קרבנה מאכל בהמה\u0004 (שעורים). \u0003היא השקתהו יין משובח בכוסות משובחים —\u0004 \u0003לפיכך כהן משקה מים המרים במקידה\u0004 (כלי פשוט) \u0003של חרש.\u0004","\u0003היא עשתה בסתר —\u0004 \u0003\"ישב בסתר עליון\"\u0004 (תהלים צא, א), הקדוש ברוך הוא, \u0003שם בה פנים, שנאמר\u0004 בסוג כזה של מעשים \u0003\"ועין נאף שמרה נשף לאמר לא תשורני עין\u0004 וסתר פנים ישים","\u0003\"\u0004(איוב כד, טו). שהנואף בא בלילה (\"נשף\") שלא יראוהו (\"לא תשורני עין\"), והקדוש ברוך הוא עושה שיתגלה הדבר ברבים (\"פנים ישים\"). \u0003דבר אחר: היא עשתה בסתר —\u0004 \u0003המקום פירסמה בגלוי, שנאמר: \"תכסה שנאה במשאון תגלה רעתו בקהל\"\u0004 (משלי כו, כו), ששנאה וחטא שהיו מכוסים בחושך (\"משאון\") — לסוף מתגלים בקהל.","לענין זה שאמרנו שאף העבירות הקטנות שעושה אדם מצטרפות ונחשבות, ולבסוף נענש על הכל, שואלים: \u0003ומאחר דנפקא ליה\u0004 \u0005[שיצאה,\u0006 נלמדה, \u0005לו]\u0006 ההוכחה לענין זה \u0003מ\"אחת לאחת למצא חשבון\"\u0004 (קהלת ז, כז), אם כן הכתוב \u0003\"כי כל סאון סאן ברעש\"\u0004 (ישעיה ט, ד) המלמד שנענשים גם על עבירות קטנות, \u0003למה לי?\u0004 ומשיבים: להורות לנו שלא רק שהדברים מצטרפים ואין דבר אובד, אלא \u0003לכמדה,\u0004 שהעונש הוא מידה במידה.","ושואלים: \u0003ומאחר דנפקא ליה\u0004 \u0005[שיוצא,\u0006 נלמד, \u0005לו\u0006 הענין\u0005]\u0006 של מידה במידה \u0003מ\"כי כל סאון סאן ברעש\",\u0004 אם כן הכתוב \u0003\"בסאסאה בשלחה תריבנה\"\u0004 (ישעיה כז, ח) \u0003למה לי?\u0004","ומשיבים: כתוב זה נדרש לענין אחר, \u0003לכ\u0004 דברי \u0003רב חיננא בר פפא.\u0004 ש\u0003אמר רב חיננא בר פפא: אין הקדוש ברוך הוא נפרע מן האומה\u0004 החוטאת \u0003עד שעת שילוחה\u0004 איבודה הסופי מן העולם, \u0003שנאמר: \"בסאסאה בשלחה\u0004 תריבנה","\u0003\".\u0004 ושואלים: \u0003איני\u0004 \u0005[וכן הוא]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא: שלשה כוסות\u0004 (של פורענות) \u0003האמורות\u0004 בחלומו של שר המשקים \u0003במצרים\u0004 (\"וכוס פרעה בידי ואקח את הענבים ואשחט אותם אל כוס פרעה ואתן את הכוס על כף פרעה\". בראשית מ, יא), \u0003למה? אחת —\u0004 \u0003ששתת\u0004 (ששתתה) \u0003בימי משה\u0004 בעשר המכות, \u0003ואחת —\u0004 \u0003ששתת בימי פרעה נכה\u0004 מלך מצרים שנוצח בידי נבוכדנצר, \u0003ואחת —\u0004 \u0003שעתידה לשתות עם חברותיה\u0004 עם שאר האומות בימות המשיח. ואם כן נמצא שמצרים לקתה לא פעם אחת אלא פעמים אחדות!","\u0003וכי תימא הנך אזדו והני אחריני נינהו\u0004 \u0005[ואם תאמר\u0006 כי \u0005אלה,\u0006 המצרים הקדמונים, \u0005הלכו, ואלה\u0006 שנמצאים שם כעת \u0005אחרים הם] —\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' יהודה: מנימין גר המצרי היה לי חבר,\u0004 ואף הוא היה \u0003מתלמידי ר' עקיבא.\u0004 \u0003ו\u0004\u0003אמר מנימין גר המצרי: אני מצרי ראשון,\u0004 כלומר, שהוא עצמו התגייר \u0003ונשאתי מצרית ראשונה, אשיא לבני\u0004 (שהוא מצרי מדור שני) \u0003מצרית שניה, כדי שיהא בן בני מותר לבא בקהל\u0004 כי מצרים אסורים לבוא בקהל רק עד דור שלישי. משמע מכך שדיני המצרים הקדמונים חלים גם על המצרים שבזמן הזה והם אותה אומה!","\u0003אלא אי איתמר הכי איתמר\u0004 \u0005[אם נאמר כך נאמר],\u0006 \u0003אמר רב חיננא בר פפא: אין הקדוש ברוך הוא נפרע\u0004 (\"בסאסאה\") \u0003מן המלך עד שעת שילוחו\u0004 מן העולם, \u0003שנאמר \"בסאסאה בשלחה תריבנה\"\u0004 (ישעיה כז, ח).","\u0003אמימר מתני להא\u0004 \u0005[היה שונה את זו]\u0006 שאמר \u0003רב חיננא בר פפא אהא\u0004 \u0005[על זו]:\u0006 \u0003מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"כי אני ה' לא שניתי ואתם בני יעקב לא כליתם\"\u0004 (מלאכי ג, ו)? — \u0003\"אני ה' לא שניתי\"\u0004 מתפרש: \u0003לא הכיתי לאומה ושניתי לה\u0004 (נצרכתי להכותה שנית) שכאשר מכה אותה פעם אחת — שוב אין לה תקומה, \u0003\"ואתם בני יעקב\",\u0004 למרות שהוכיתם פעמים רבות — \u0003\"לא כליתם\" היינו דכתיב\u0004 \u0005[\u0006ו\u0005זהו שנאמר]\u0006 \u0003\"חצי אכלה בם\"\u0004 (דברים לב, כג), לומר: \u0003חצי כלין, והן,\u0004 ישראל, \u0003אינן כלין,\u0004 אלא נשארים קיימים למרות הפורענויות הרבות שעברו עליהם.","\u0003אמר רב המנונא: אין הקדוש ברוך הוא נפרע מן האדם עד שתתמלא סאתו\u0004 (המידה הראויה לו), \u0003שנאמר \"במלאות שפקו יצר לו\"\u0004 (איוב כ, כב). שכאשר מתמלא השיעור המספיק (\"ספקו\") אז תבוא עליו הצרה (\"יצר לו\").","\u0003ואגב כך הביאו עוד מה ש\u0004\u0003דרש ר' חיננא בר פפא: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"רננו צדיקים בה' לישרים נאוה תהלה\"\u0004 (תהלים לג, א)? \u0003אל תקרי \"נאוה תהלה\" אלא \"נוה\u0004 (בית) \u0003תהלה\",\u0004 לומר: \u0003זה משה ודוד\u0004 ש\u0003לא\u0004 \u0003שלטו שונאיהם במעשיהם,\u0004 שבנו נוה לה', והנוה הזה נשאר קיים.","\u0003דוד\u0004 מניין שלא הרסו זרים מעשיו — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"טבעו בארץ שעריה\"\u0004 (איכה ב, ט), לומר שבשערי המקדש לא שלטו השונאים, אלא טבעו השערים בארץ ונטמנו בה. \u0003משה\u0004 — ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003משנבנה מקדש ראשון נגנז אהל מועד, קרשיו קרסיו ובריחיו ועמודיו ואדניו.\u0004 ושואלים: \u0003היכא\u0004 \u0005[היכן]\u0006 נגנז? \u0003אמר רב חסדא אמר אבימי: תחת מחילות של היכל.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003סוטה נתנה עיניה במי שאינו ראוי לה,\u0004 באדם זר, ונענשה ש\u0003מה שביקשה\u0004 להיות עם הנואף — \u0003לא ניתן לה,\u0004 שהרי נאסרת עליו לעולם, \u0003ומה שבידה\u0004 (בעלה) — \u0003נטלוהו ממנה,\u0004 שנאסרת גם עליו. וכלל הוא: \u0003שכל הנותן עיניו במה שאינו שלו —\u0004 \u0003מה שמבקש אין נותנין לו, ומה שבידו נוטלין הימנו.\u0004"],["\u0003וכן מצינו בנחש הקדמוני\u0004 שפיתה את חוה, \u0003שנתן עיניו במה שאינו ראוי לו\u0004 שרצה לשאת את חוה, \u0003מה שביקש לא נתנו לו, ומה שבידו נטלוהו ממנו.\u0004 שכן \u0003אמר\u0004 \u0003הקדוש ברוך הוא: אני אמרתי\u0004 תחילה: \u0003יהא\u0004 הנחש \u0003מלך על כל בהמה וחיה, ועכשיו ארור הוא מכל הבהמה ומכל חית השדה\u0004 (ראה בראשית ג, יד).","\u0003אני אמרתי יהלך בקומה זקופה —\u0004 \u0003עכשיו על גחונו ילך. אני אמרתי יהא מאכלו מאכל אדם —\u0004 \u0003עכשיו עפר יאכל. הוא אמר אהרוג את אדם ואשא את חוה —\u0004 \u0003עכשיו \"איבה אשית בינך ובין האשה ובין זרעך ובין זרעה\"\u0004 (בראשית ג, טו).","\u0003וכן מצינו בקין,\u0004 שרצה לרשת לבדו את העולם, \u0003וקרח\u0004 שרצה כהונה, \u0003ובלעם\u0004 שרצה את ממונו של בלק, \u0003ודואג ואחיתופל\u0004 שקינאו בדוד, \u0003וגחזי\u0004 שלקח את ממונו של נעמן, \u0003ואבשלום ואדוניהו\u0004 שרצו במלוכה, \u0003ועוזיהו\u0004 שרצה כהונה גדולה, \u0003והמן\u0004 שרצה לאבד את כל היהודים, \u0003ש\u0004כל אלה \u0003נתנו עיניהם במה שאינו ראוי להם,\u0004 ולכן \u0003מה שביקשו לא ניתן להם, ומה שבידם נטלוהו מהם.\u0004","נאמר במשנה: \u0003בירך התחילה\u0004 הסוטה \u0003בעבירה\u0004 ואחר כך בבטן, ולפיכך נענשת תחילה בירך. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מניין הדברים הללו]\u0006 שכך סדר העונש? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בתת ה' את ירכך נפלת ואת בטנך צבה\"\u0004 (במדבר ה, כא), שמשמע שזה סדר העונש — \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 גם \u0003\"וצבתה בטנה ונפלה ירכה\"\u0004 (בראשית ג, כז), משמע שהפורענות באה בבטן תחילה ואחר כך בירך!","\u0003אמר אביי: כי לייט\u0004 \u0005[כאשר\u0006 הכהן \u0005מקלל]\u0006 — הריהו \u0003לייט\u0004 \u0005[מקלל]\u0006 \u0003תחילה\u0004 את ה\u0003ירך והדר\u0004 \u0005[ואחר כך]\u0006 את ה\u0003בטן לייט\u0004 \u0005[מקלל],\u0006 \u0003ומיא כי בדקי\u0004 \u0005[והמים כאשר בודקים\u0006 הם אותה\u0005] —\u0006 \u0003כי אורחייהו בדקי\u0004 \u0005[כדרכם בודקים\u0006 אותה\u0005],\u0006 שהמים נכנסים ב\u0003בטן ברישא\u0004 \u0005[בתחילה]\u0006 \u0003והדר\u0004 \u0005[ואחר\u0006 כך\u0005]\u0006 מגיעים ל\u0003ירך.\u0004 ומקשים: \u0003בקללה נמי כתיב\u0004 \u0005[גם כן נאמר]\u0006 \u0003\"לצבות בטן ולנפל ירך\"\u0004 (בראשית ג, כב), משמע שקודם שתחילת הפורענות הבטן ואחר כך בירך! ומשיבים: הכתוב \u0003ההוא\u0004 אותו בא לומר \u0003דמודע\u0004 \u0005[שמודיע]\u0006 \u0003לה\u0004 ה\u0003כהן\u0004 שה\u0003בטן\u0004 נבדקת \u0003ברישא\u0004 \u0005[בתחילה]\u0006 \u0003והדר\u0004 \u0005[ואחר כך]\u0006 ה\u0003ירך\u0004 נבדקת, ש\u0003לא\u0004 \u0003להוציא לעז על מים המרים,\u0004 שאם לא יהיה הדבר לפי הסדר הזה, יאמרו שהמים לא בדקו אותה.","ועוד בדברי אגדה על כך שאדם מקבל מידי שמים לפי המידה שהוא עצמו מודד. \u0003שמשון הלך אחר עיניו —\u0004 \u0003לפיכך\u0004 נענש מידה במידה כאשר \u0003נקרו פלשתים את עיניו, שנאמר: \"ויאחזוהו פלשתים וינקרו את עיניו\"\u0004 (שופטים טז, כא).","\u0003אבשלום נתגאה בשערו —\u0004 \u0003לפיכך נתלה בשערו. ו\u0004עוד, \u0003לפי שבא על עשר פלגשי אביו\u0004 (ראה שמואל ב טו, טז, ושם טז, כב) — \u0003לפיכך נתנו\u0004 (נתקעו) \u0003בו עשר לונביות\u0004 (חניתות), \u0003שנאמר: \"ויסבו עשרה נערים נשאי כלי יואב\u0004 ויכו את אבשלום וימיתוהו\u0003\"\u0004 (שמואל ב יח, טו). \u0003ולפי שגנב שלש גנבות,\u0004 שגנב ליבם של שלושה; \u0003לב אביו,\u0004 שרימה אותו כשאמר לו שהולך לזבוח, \u0003ולב בית דין\u0004 שרימה גם את בית הדין שיתמכו בו, \u0003ולב\u0004 כל \u0003ישראל, שנאמר: \"ויגנב אבשלום את לב אנשי ישראל\"\u0004 (שמואל ב טו, ו) — \u0003לפיכך נתקעו בו\u0004 בליבו \u0003שלשה שבטים, שנאמר: \"ויקח שלשה שבטים בכפו ויתקעם בלב אבשלום\"\u0004 (שמואל ב יח, יד).","\u0003וכן לענין הטובה\u0004 משלמים לאדם מידה כנגד מידה, \u0003מרים המתינה למשה שעה אחת\u0004 על שפת היאור, \u0003שנאמר: \"ותתצב אחתו מרחק\u0004 לדעה מה יעשה לו\u0003\"\u0004 (שמות ב, ד) — \u0003לפיכך נתעכבו לה ישראל שבעה ימים במדבר\u0004 כאשר לקתה בצרעת, \u0003שנאמר: \"והעם לא נסע עד האסף מרים\"\u0004 (במדבר יב, טו).","\u0003יוסף זכה לקבור את אביו, ו\u0004אף ש\u0003אין באחיו\u0004 מי שהיה \u0003גדול\u0004 בחשיבות \u0003ממנו, שנאמר: \"ויעל יוסף לקבר את אביו ויעלו... עמו גם רכב גם פרשים\"\u0004 (בראשית נ, ז. בראשית נ, ט) — \u0003מי לנו גדול מיוסף\u0004 ש\u0003לא נתעסק בו\u0004 בארונו \u0003אלא משה\u0004 שהיה גדול שבישראל.","\u0003משה זכה\u0004 להתעסק \u0003בעצמות יוסף ו\u0004אף ש\u0003אין בישראל גדול ממנו, שנאמר: \"ויקח משה את עצמות יוסף עמו\"\u0004 (שמות יג, יט) — \u0003מי גדול ממשה\u0004 ש\u0003לא נתעסק בו אלא המקום\u0004 (הקדוש ברוך הוא) עצמו, \u0003שנאמר: \"ויקבר אתו בגי\"\u0004 (דברים לד, ו), ואין מבואר בכתוב מי קברו, ללמדנו שה' הוא שקבר אותו. \u0003לא על משה בלבד אמרו\u0004 שהקדוש ברוך הוא התעסק בו, \u0003אלא על כל הצדיקים, שנאמר: \"והלך לפניך צדקך כבוד ה' יאספך\"\u0004 (ישעיה נח, ח).","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שמשון בעיניו מרד\u0004 שמשום שהלך אחר עיניו עבר עבירות, \u0003שנאמר: \"ויאמר שמשון אל אביו אותה קח לי כי היא ישרה בעיני\"\u0004 (שופטים יד, ג) — \u0003לפיכך נקרו פלשתים את עיניו, שנאמר: \"ויאחזוהו פלשתים וינקרו את עיניו\"\u0004 (שופטים טז, כא).","ומקשים: \u0003איני\u0004 \u0005[ו\u0006כי \u0005כן הוא]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"ואביו ואמו לא ידעו כי מה' היא\u0004 כי תואנה הוא מבקש מפלשתים\u0003\"\u0004 (שופטים יד, ד), משמע שלא היה זה מפני שהלך אחר עיניו, אלא מפני שעשה בכך שליחות המקום! ומשיבים: אמנם עונשם של פלשתים נועד מעם ה', אבל \u0003כי אזל מיהא\u0004 \u0005[כאשר הלך על כל פנים] —\u0006 \u0003בתר ישרותיה אזל\u0004 \u0005[אחר ישרותו,\u0006 נטיית ליבו, \u0005הלך]\u0006 ולא עשה לשם שמים.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003רבי אומר: תחילת קלקולו בעזה —\u0004 \u0003לפיכך לקה בעזה.\u0004 ומסבירים: \u0003תחילת קלקולו בעזה —\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וילך שמשון עזתה וירא שם אשה זונה\"\u0004 (שופטים טז, א), \u0003לפיכך לקה בעזה —\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויורידו אותו עזתה\"\u0004 (שופטים טז, כא).","ומקשים: \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 קודם לכן: \u0003\"וירד שמשון תמנתה\u0004 וירא אשה בתמנתה מבנות פלשתים\u0003\"\u0004 (שופטים יד, א), משמע שכבר בתמנה החל הדבר! ומשיבים: \u0003תחלת קלקולו מיהא\u0004 \u0005[על כל פנים]\u0006 \u0003בעזה היה,\u0004 שזאת שבתמנה נשא לאשה ואילו בזנות קילקל בעזה.","נאמר \u0003\"ויהי אחרי כן ויאהב אשה בנחל שורק ושמה דלילה\"\u0004 (שופטים טז, ד). \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003רבי אומר:\u0004 גם \u0003אילמלא\u0004 (אם לא) \u0003לא נקרא שמה \"דלילה\" —\u0004 \u0003ראויה היתה שתקרא \"דלילה\".\u0004 ומדוע? משום ש\u0003דילדלה את כחו, דילדלה את לבו, דילדלה את מעשיו.\u0004","ומבאר: \u0003דילדלה את כחו —\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 לאחר שגילחה את שערו: \u0003\"ויסר כחו מעליו\"\u0004 (שופטים טז, יט). \u0003דילדלה את לבו —\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ותרא דלילה כי הגיד לה את כל לבו\"\u0004 (שופטים טז, יח). \u0003דילדלה את מעשיו —\u0004 \u0003דאיסתלק\u0004 \u0005[שהסתלקה]\u0006 \u0003שכינה מיניה\u0004 \u0005[ממנו],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והוא לא ידע כי ה' סר מעליו\"\u0004 (שופטים טז, כ).","נאמר שם \u0003\"ותרא דלילה כי הגיד לה את כל לבו\"\u0004 (שופטים טז, יח). ושואלים: \u0003מנא\u0004 \u0005[מניין]\u0006 \u0003ידעה\u0004 שהפעם הוא מדבר דברי אמת? \u0003אמר ר' חנין אמר רב: ניכרין דברי אמת\u0004 מעצמם, והרגישה שהפעם הוא דובר אמת. \u0003אביי אמר: ידעה בו באותו צדיק\u0004 ש\u0003לא מפיק\u0004 \u0005[מוציא]\u0006 \u0003שם שמים לבטלה. כיון\u0004 ש\u0003אמר \"נזיר אלהים אני\"\u0004 (שופטים טז, יז) \u0003אמרה: השתא\u0004 \u0005[עכשיו]\u0006 \u0003ודאי קושטא קאמר\u0004 \u0005[אמת\u0006 הוא \u0005אומר].\u0006","נאמר \u0003\"ויהי כי הציקה לו בדבריה כל הימים ותאלצהו\"\u0004 (שופטים טז, טז). ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ותאלצהו\",\u0004 כיצד אילצה אותו? \u0003אמר ר' יצחק דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' אמי: בשעת גמר ביאה נשמטה מתחתיו\u0004 שלא יגמור ביאתו, ועל ידי כך היה מצטער ביותר.","נאמר בדברי המלאך לאימו של שמשון \u0003\"ועתה השמרי נא ואל תשתי יין ושכר ואל תאכלי כל טמא\"\u0004 (שופטים יג, ד). ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"כל טמא\"? ותו\u0004 \u0005[ועוד],\u0006 וכי \u0003עד השתא\u0004 \u0005[עכשיו]\u0006 \u0003דברים טמאים קאכלה\u0004 \u0005[היתה אוכלת]\u0006 שצריך היה לומר לה שמעכשיו לא תאכל בכלל דבר טמא?! \u0003אמר ר' יצחק דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003רבי אמי:\u0004 אין הכוונה לדבר טמא ממש, אלא ל\u0003דברים האסורים ב\u0004אכילה ל\u0003נזיר.\u0004","נאמר בשמשון \u0003\"ויבקע אלהים את המכתש אשר בלחי\"\u0004 (שופטים טו, יט). \u0003אמר ר' יצחק דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003רבי אמי: הוא איוה לדבר טמא\u0004 בזנות — \u0003לפיכך נתלו חייו בדבר טמא\u0004 בלחי החמור.","נאמר בשמשון \"ותחל רוח ה' לפעמו במחנה דן בן צרעה ובין אשתאול\" (שופטים יג, כה), וכך דרשו את הפסוק: \u0003\"ותחל רוח ה'\", אמר ר' חמא בר' חנינא: חלתה\u0004 (חלה, התקיימה) \u0003נבואתו של יעקב אבינו, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"יהי דן נחש עלי דרך\"\u0004 (בראשית מט, יז) והכוונה לשמשון שבא משבט דן.","\u0003\"לפעמו במחנה דן\", אמר ר' יצחק דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003רבי אמי: מלמד שהיתה שכינה מקשקשת לפניו כזוג\u0004 (כפעמון); \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 \u0003\"לפעמו במחנה דן\" וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בבגדי הכהן הגדול \u0003\"פעמן ורמן\"\u0004 (שמות לט, כו).","על הנאמר \u0003\"בין צרעה ובין אשתאול\", אמר ר' אסי: צרעה ואשתאול שני הרים גדולים היו, ועקרן שמשון וטחנן זה בזה.\u0004","נאמר בו \u0003\"והוא יחל להושיע את ישראל\"\u0004 (שופטים יג, ה) \u0003אמר ר' חמא בר' חנינא:\u0004"],["\u0003הוחל\u0004 (התחללה, בטלה) \u0003שבועתו של אבימלך\u0004 שנשבע לו אברהם בברית שכרתו ביניהם, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אם תשקר לי ולניני ולנכדי\"\u0004 (בראשית כא, כג). וכיון שהפלשתים לא שמרו את השבועה ושיעבדו בישראל — בטלה השבועה.","נאמר \u0003\"ויגדל הנער ויברכהו ה'\"\u0004 (שופטים יג, כד), ושואלים: \u0003במה ברכו?\u0004 שהרי לא מצאנו בו ברכה מיוחדת. \u0003אמר רב יהודה אמר רב: שברכו באמתו\u0004 (איבר המין שלו), שלמרות שהיה נער היתה \u0003אמתו כ\u0004שאר \u0003בני אדם, וזרעו כנחל שוטף.\u0004","נאמר \u0003\"ויקרא שמשון אל ה' ויאמר ה' אלהים זכרני נא וחזקני נא אך הפעם הזה האלהים ואנקמה נקם אחת משתי עיני מפלשתים\"\u0004 (שופטים טז, כח). \u0003אמר רב: אמר שמשון לפני\u0004 \u0003הקדוש ברוך הוא: רבונו של עולם, זכור לי עשרים ושתים שנה ששפטתי את ישראל\u0004 בלי לקבל כל שכר \u0003ולא אמרתי לאחד מהם\u0004 אפילו \u0003העבר לי מקל ממקום למקום.\u0004","נאמר \u0003\"וילך שמשון וילכד שלש מאות שועלים\"\u0004 (שופטים טו, ד), ושואלים: \u0003מאי שנא\u0004 \u0005[מה שונה,\u0006 מדוע דווקא\u0005]\u0006 \u0003שועלים? אמר ר' איבו בר נגדי אמר ר' חייא בר אבא, אמר שמשון: יבא מי שחוזר לאחוריו,\u0004 השועל, שבשעה שצדים אותו הריהו חוזר לאחוריו, למקום שהיה בו קודם לכן ואינו מרחיק לברוח, \u0003ויפרע מפלשתים שחזרו בשבועתן\u0004 שנשבע אבימלך לאברהם, ולא קיימו אותה.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' שמעון החסיד: בין כתיפיו של שמשון\u0004 רוחב \u0003ששים אמה היה, שנאמר: \"וישכב שמשון עד חצי הלילה ויקם בחצי הלילה ויאחז בדלתות שער העיר ובשתי המזזות ויסעם עם הבריח וישם על כתפיו\"\u0004 (שופטים טז, ג), למדנו שהיו כמידת כתפיו, \u0003וגמירי\u0004 \u0005[ולמודים\u0006 אנו\u0005]\u0006 במסורת, ש\u0003אין דלתות עזה פחותות\u0004 ברוחבן \u0003מששים אמה.\u0004","נאמר על שמשון: \u0003\"ויהי טוחן בבית האסורים\"\u0004 (שופטים טז, כא). \u0003אמר ר' יוחנן: אין טחינה אלא לשון עבירה\u0004 (כלומר, תשמיש), \u0003וכן הוא אומר \"תטחן לאחר אשתי\u0004 ועליה יכרעון אחרין\u0003\"\u0004 (איוב לא, י), \u0003מלמד שכל אחד ואחד הביא לו את אשתו לבית האסורים כדי שתתעבר הימנו. אמר רב פפא: היינו דאמרי אינשי\u0004 \u0005[זהו שאומרים אנשים\u0006 בפתגם מקובל\u0005]:\u0006 \u0003קמי דשתי חמרא —\u0004 \u0005[לפני\u0006 מי \u0005ששותה יין]\u0006 — נותנים \u0003חמרא\u0004 \u0005[יין],\u0006 \u0003קמי רפוקא גרידיא\u0004 \u0005[לפני\u0006 מי \u0005שחופר באדמה] —\u0006 נותנים \u0003דובלא\u0004 \u0005[דבלים]\u0006 (עשב) והוא שאירע בשמשון, שמה שעסק בו הוא שהביאו לפניו.","\u0003ואמר ר' יוחנן: כל המזנה\u0004 עם נשים אחרות — \u0003אשתו מזננת עליו, שנאמר \"אם נפתה לבי על אשה ועל פתח רעי ארבתי\"\u0004 (איוב לא, ט), \u0003ו\u0004על כך גם \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"תטחן לאחר אשתי ועליה יכרעון אחרין\"\u0004 (איוב לא, י). \u0003והיינו דאמרי אינשי\u0004 \u0005[והוא שאומרים אנשים\u0006 בפתגם עממי\u0005]:\u0006 \u0003איהו בי קארי ואיתתיה בי בוציני\u0004 \u0005[הוא\u0006 נמצא \u0005בין הדלעות ואשתו בין המלפפונים],\u0006 כלומר, כדרך שהוא עושה אף היא עושה.","\u0003ואמר ר' יוחנן: שמשון דן את ישראל כאביהם שבשמים\u0004 בצדק גמור, \u0003שנאמר: \"דן ידין עמו כאחד\" וגו'\u0004 (בראשית מט, טז) ודורשים — כמו ה' שהוא אחד. \u0003ואמר ר' יוחנן: שמשון על שמו של הקדוש ברוך הוא נקרא, שנאמר: \"כי שמש ומגן ה' אלהים\"\u0004 (תהלים פד, יב). ושואלים: \u0003אלא מעתה\u0004 אם הוא כינוי של הקדוש ברוך הוא, אם כן \u0003לא ימחה\u0004 (ימחק) שמו כשאר שמות הקודש! \u0003אלא\u0004 יש לומר: שמו הוא \u0003מעין שמו של הקדוש ברוך הוא,\u0004 ללמד: \u0003מה הקדוש ברוך הוא מגין על כל העולם כולו —\u0004 \u0003אף שמשון מגין בדורו על ישראל. ו\u0004עוד","\u0003אמר ר' יוחנן: בלעם חיגר ברגלו אחת היה, שנאמר \"וילך שפי\"\u0004 (במדבר כג, ג), ומפרשים: הלך בצליעה. \u0003שמשון חיגר בשתי רגליו היה, שנאמר\u0004 בדברי יעקב על שבט דן, והיא הנבואה על שמשון \u0003\"שפיפן עלי ארח\"\u0004 (בראשית מט, יז) — שפי כפול.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003חמשה נבראו\u0004 בצד מסויים \u0003מעין דוגמא של מעלה,\u0004 בדרגה שהיא למעלה מבני אדם רגילים, בתבנית מושלמת, \u0003וכולן לקו בהן,\u0004 באותם דברים שנתעלו בהם. \u0003שמשון בכחו\u0004 היה מעין מעלה, \u0003שאול בצוארו\u0004 שנאמר בו שהיה משכמו ומעלה גבוה מכל העם, \u0003אבשלום בשערו, צדקיה בעיניו, אסא ברגליו.\u0004","ומפרטים: \u0003שמשון\u0004 לקה \u0003בכחו —\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויסר כחו מעליו\"\u0004 (שופטים טז, יט).","\u0003שאול\u0004 לקה \u0003בצוארו —\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויקח שאול את החרב ויפל עליה\"\u0004 (שמואל א לא, ד), ומפרשים שעשה שתינעץ החרב בצווארו.","\u0003אבשלום\u0004 לקה \u0003בשערו —\u0004 \u0003כדבעינן למימר קמן\u0004 \u0005[כפי שרוצים אנו לומר אחר כך].\u0006 \u0003צדקיה\u0004 לקה \u0003בעיניו, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואת עיני צדקיהו עור\"\u0004 (מלכים ב כה, ז).","\u0003אסא\u0004 לקה \u0003ברגליו —\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"רק לעת זקנתו חלה את רגליו\"\u0004 (מלכים א טו, כג), \u0003ואמר רב יהודה אמר רב:\u0004 מה היתה מחלתו — \u0003שאחזתו פדגרא. אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחמן לרב נחמן: היכי דמי\u0004 \u0005[כיצד הוא\u0006 כאב\u0005]\u0006 \u0003פדגרא? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כמחט\u0004 הננעצת \u0003בבשר החי.\u0004 ושואלים: \u0003מנא\u0004 \u0005[מניין]\u0006 \u0003ידע\u0004 דבר זה? ומשיבים: \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003מיחש הוה\u0004 \u0005[הוא בעצמו היה]\u0006 \u0003חש ביה\u0004 \u0005[בו]\u0006 ממחלה זו. \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 \u0003מרביה\u0004 \u0005[מרבו]\u0006 \u0003שמע ליה\u0004 \u0005[זאת].\u0006 \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 שידע זאת כפי שנאמר \u0003\"סוד ה' ליראיו ובריתו להודיעם\"\u0004 (תהלים כה, יד).","\u0003דרש רבא: מפני מה נענש אסא\u0004 ברגליו — \u0003מפני שעשה אנגריא\u0004 (עבודת כפייה) \u0003בתלמידי חכמים, שנאמר \"והמלך אסא השמיע את כל יהודה אין נקי\"\u0004 (מלכים א טו, כב) לבנות את העיר רמה, ומריבוי הלשון \"את כל\" משמע שלקח לעבודה זו את כולם, גם תלמידי חכמים. ושאלו: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אין נקי\"? אמר רב יהודה אמר רב: אפילו חתן מחדרו וכלה מחופתה,\u0004 שנאמר בחתן \"נקי יהיה לביתו שנה אחת\" (דברים כד, ה).","\u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"וירד שמשון תמנתה\"\u0004 (שופטים יד, א), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בפרשת יהודה ותמר \u0003\"הנה חמיך עלה תמנתה\"\u0004 (בראשית לח, יג). ולכאורה יש סתירה בין הכתובים, שבמקום אחד נראה שתמנה היתה במקום נמוך, ובאחר שהיתה במקום גבוה. \u0003אמר ר' אלעזר:\u0004 אין להבין את הדבר במובן של תיאור הליכה למקום, אלא באופן מוסרי; \u0003שמשון שנתגנה בה\u0004 בהליכתו לתמנה — \u0003כתיב ביה\u0004 \u0005[נאמר בו]\u0006 לשון \u0003ירידה,\u0004 ואילו \u0003יהודה שנתעלה בה —\u0004 \u0003כתיב ביה\u0004 \u0005[נאמר בו]\u0006 לשון \u0003עליה.\u0004","\u0003ר' שמואל בר נחמני אמר: שתי תמנאות היו, חדא\u0004 \u0005[אחת\u0006 מהן\u0005]\u0006 \u0003בירידה\u0004 בעמק, \u0003וחדא\u0004 \u0005[ואחת]\u0006 \u0003בעליה,\u0004 במקום גבוה.","\u0003רב פפא אמר: חדא תמנה הואי\u0004 \u0005[תמנה אחת היתה]\u0006 וישבה במדרון של הר, לאדם \u0003דאתי מהאי גיסא\u0004 \u0005[שבא מצד זה],\u0006 מפסגת ההר — \u0003ירידה\u0004 היא, \u0003ודאתי מהאי גיסא\u0004 \u0005[ו\u0006ל\u0005שבא מצד אחר],\u0006 מתחתיתו — \u0003עליה\u0004 היא. ומביאים דוגמה \u0003כגון\u0004 המקומות \u0003ורדוניא ובי בארי ושוקא דנרש\u0004 שנמצאים בשיפוע הר, שלבני מקום אחד היא עליה, ולבני מקום אחר היא ירידה.","נאמר בתמר \u0003\"ותשב בפתח עינים\"\u0004 (בראשית לח, יד), ונחלקו אמוראים בפירוש \"פתח עינים\". \u0003אמר ר' אלכסנדרי: מלמד שהלכה וישבה לה בפתחו של אברהם אבינו, מקום שכל עינים צופות לראותו,\u0004 והיתה בטוחה שיעבור יהודה שם. \u0003ר' חנין אמר\u0004 בשם \u0003רב: מקום הוא ששמו עינים, וכן הוא אומר\u0004 בתוך רשימת ישובים \u0003\"תפוח והעינם\"\u0004 (יהושע טו, לד).","\u0003ר' שמואל בר נחמני אמר: שנתנה עינים\u0004 (הסבירה, הביאה ראיה) \u0003לדבריה. כשתבעה\u0004 יהודה למשכב \u0003אמר לה: שמא גויה את? אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003גיורת אני.\u0004 שאל: \u0003שמא אשת איש את? אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003פנויה אני. שמא קיבל בך אביך קידושין\u0004 ואינך יודעת על כך? \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003יתומה אני.\u0004 ועוד שאל: \u0003שמא טמאה\u0004 (נידה) \u0003את? אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003טהורה אני.\u0004 והוא אשר נאמר \"פתח עינים\" — שפתחה לו פתח להראות שהיא מותרת לו.","ועוד בענין ביתו של אברהם: נאמר \u0003\"ויטע אשל בבאר שבע\"\u0004 (בראשית כא, לג), \u0003אמר ריש לקיש: מלמד שעשה\u0004 אברהם \u0003פרדס, ונטע בו כל מיני מגדים.\u0004","בענין זה נחלקו תנאים, \u0003ר' יהודה ור' נחמיה; חד\u0004 \u0005[אחד\u0006 \u0003מהם\u0004\u0005]\u0006 \u0003אמר: פרדס\u0004 נטע, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: פונדק\u0004 עשה. ואומרים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר]\u0006 שנטע \u0003פרדס —\u0004 \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 \u0003\"ויטע\",\u0004 שלשון זו נופלת בפרדס. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003פונדק, מאי\u0004 \u0005[מה]\u0006 היא לשון \u0003\"ויטע\"?\u0004 ומשיבים: \u0003כדכתיב\u0004 \u0005[כפי שנאמר]:\u0006 \u0003\"ויטע אהלי אפדנו\"\u0004 (דניאל יא, מה) שאף באוהלים משתמשים בלשון נטיעה.","נאמר שם \u0003\"ויקרא שם בשם ה' אל עולם\"\u0004 (בראשית כא, לג). \u0003אמר ריש לקיש: אל תיקרי\u0004 \u0005[תקרא]\u0006 בפסוק הזה כמפורש בו \u0003\"ויקרא\",\u0004"],["\u0003אלא ויקריא. מלמד שהקריא,\u0004 כלומר, גרם \u0003אברהם אבינו לשמו של הקדוש ברוך הוא\u0004 שיקרא \u0003בפה כל עובר ושב. כיצד? לאחר ש\u0004אורחיו של אברהם \u0003אכלו ושתו, עמדו לברכו\u0004 ולהודות לו. \u0003אמר להם: וכי משלי אכלתם? משל אלהי עולם אכלתם! הודו ושבחו וברכו למי שאמר והיה העולם.\u0004 ועל ידי כך גרם לכולם להודות לה'. ושוב לענין תמר.","נאמר \u0003\"ויראה יהודה ויחשבה לזונה כי כסתה פניה\"\u0004 (בראשית לח, טו). ותוהים: \u0003משום\u0004 ש\u0003כסתה\u0004 את \u0003פניה חשבה לזונה?!\u0004 הלא דרך הזונות היא להיפך, שמגלות את פניהן!","\u0003אמר ר' אלעזר:\u0004 משום \u0003שכסתה פניה בבית חמיה,\u0004 כלומר, בביתו, מחמת צניעות, לכן לא הכירה עכשיו כשגילתה את פניה. ש\u0003אמר ר' שמואל בר נחמני אמר ר' יונתן: כל כלה שהיא צנועה בבית חמיה —\u0004 \u0003זוכה ויוצאין ממנה מלכים ונביאים. מנלן\u0004 \u0005[מניין לנו]\u0006 דבר זה — \u0003מתמר.\u0004 וכיצד אנו מוצאים שיצאו ממנה \u0003נביאים —\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"חזון ישעיהו בן אמוץ\"\u0004 (ישעיה א, א), \u0003מלכים —\u0004 \u0003מדוד. ואמר ר' לוי: דבר זה מסורת בידינו מאבותינו: אמוץ\u0004 אבי ישעיהו הנביא \u0003ואמציה\u0004 מלך יהודה מזרע דוד \u0003אחים הוו\u0004 \u0005[היו],\u0006 הרי שגם ישעיה הנביא היה מבית דוד ומצאצאיה של תמר.","נאמר בתמר \u0003\"היא מוצאת\"\u0004 (להישרף) (בראשית לח, כה) ושואלים: \u0003\"היא מיתוצאת\"\u0004 שהיא לשון המורה על כך שהוצאה בעל כרחה \u0003מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר! \u0003אמר ר' אלעזר: לאחר שנמצאו סימניה\u0004 שמיהודה היא מעוברת, \u0003בא סמאל\u0004 (השטן) \u0003וריחקן, בא גבריאל\u0004 המלאך \u0003וקירבן,\u0004 ולכן \"מוצאת\" רומז לשון מציאה, שנמצאו הסימנים.","ומעירים: \u0003היינו דכתיב\u0004 \u0005[הוא שנאמר]\u0006 \u0003\"למנצח על יונת אלם רחקים לדוד מכתם\"\u0004 (תהלים נו, א), \u0003אמר ר' יוחנן: משעה שנתרחקו סימניה נעשית כיונה אילמת. \"לדוד מכתם\" —\u0004 \u0003שיצא ממנה דוד שהיה מך\u0004 (נמוך ועניו) \u0003ותם לכל\u0004 הבריות. \u0003דבר אחר: \"מכתם\" —\u0004 \u0003שהיתה מכתו תמה\u0004 (שלימה), \u0003שנולד כשהוא מהול,\u0004 ולא היה צריך למול אותו. \u0003דבר אחר: \"מכתם\" —\u0004 \u0003כשם שבקטנותו הקטין עצמו אצל מי שגדול ממנו ללמוד תורה\u0004 ממנו, \u0003כך\u0004 היה נוהג \u0003בגדולתו\u0004 באופן שהיתה ענוותו (\"מכ—) שלימה (— תם\") כל ימיו.","נאמר \u0003\"והיא שלחה אל חמיה לאמר לאיש אשר אלה לו אנכי הרה\"\u0004 (בראשית לח, כה). ושואלים: \u0003ותימא ליה מימר\u0004 \u0005[ושתאמר לו]\u0006 במפורש, שלו היא הרה! \u0003אמר רב זוטרא בר טוביה אמר רב, ואמרי לה\u0004 \u0005[ו\u0006יש \u0005אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003רב חנא בר ביזנא אמר ר' שמעון חסידא, ואמרי לה\u0004 \u0005[ו\u0006יש \u0005אומרים]\u0006 \u0003אמר ר' יוחנן משום ר' שמעון בן יוחי: נוח לו\u0004 (מוטב לו) \u0003לאדם שיפיל עצמו לתוך כבשן האש, ואל ילבין פני חבירו ברבים. מנלן\u0004 \u0005[מניין לנו] —\u0006 \u0003מתמר,\u0004 שאם לא היה יהודה מודה — היתה היא מוכנה להישרף, כדי לא לביישו ברבים.","נאמר \u0003\"הכר נא\"\u0004 (בראשית לח, כה). \u0003אמר ר' חמא ברבי חנינא: ב\u0004לשון \u0003\"הכר\" בישר\u0004 הודיע יהודה \u0003לאביו,\u0004 ולכן \u0003ב\"הכר\" בישרוהו.\u0004 ומסבירים: \u0003ב\"הכר\" בישר\u0004 — שאמר לאביו על כתונת יוסף \u0003\"הכר נא הכתנת בנך היא\"\u0004 (בראשית לז, לב), \u0003ב\"הכר\" בישרוהו —\u0004 \u0003\"הכר נא למי\u0004 החותמת והפתילים והמטה\u0003\"\u0004 (בראשית לח, כה).","נאמר \u0003\"\u0004הכר \u0003נא\", אין \"נא\" אלא לשון בקשה.\u0004 ומסבירים: \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003בבקשה ממך, הכר פני בוראך ואל תעלים עיניך ממני.\u0004","\u0003\"ויכר יהודה ויאמר צדקה ממני\"\u0004 (בראשית לח, כו). \u0003היינו\u0004 \u0005[זהו]\u0006 ש\u0003אמר רב חנין בר ביזנא אמר ר' שמעון חסידא: יוסף שקדש שם שמים בסתר\u0004 כשעמד בפיתויה של אשת פוטיפר — \u0003זכה והוסיפו לו אות אחת משמו של\u0004 \u0003הקדוש ברוך הוא, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"עדות ביהוסף שמו\"\u0004 (תהלים פא, ו) הרי שהוסיפו לשמו את האות ה\"א משמו של הקדוש ברוך הוא.","\u0003יהודה שקדש שם שמים בפרהסיא\u0004 שהודה ברבים על חטאו — \u0003זכה ונקרא כולו על שמו של\u0004 \u0003הקדוש ברוך הוא,\u0004 שהרי כל השם המפורש כלול בתוך השם יהודה. \u0003כיון שהודה ואמר \"צדקה ממני\"\u0004 (בראשית לח, כו) \u0003יצתה\u0004 (יצאה) \u0003בת קול\u0004 משמים \u0003ואמרה: אתה הצלת\u0004 את \u0003תמר ושני בניה\u0004 שהיתה מעוברת בהם \u0003מן האור\u0004 (האש) — \u0003חייך שאני מציל בזכותך שלשה מבניך מן האור. מאן נינהו\u0004 \u0005[מי הם]\u0006 אותם שלושה — \u0003חנניה מישאל ועזריה.\u0004","יהודה אמר \u0003\"צדקה ממני\".\u0004 ושואלים: \u0003מנא\u0004 \u0005[מניין]\u0006 \u0003ידע\u0004 שבאמת ממנו תמר מעוברת? ומשיבים: \u0003יצתה בת קול\u0004 משמים \u0003ואמרה: ממני יצאו כבושים\u0004 (סודות) אלה, ועל פי ה' היה המעשה.","נאמר אחר כך על יהודה ותמר \u0003\"ולא יסף עוד לדעתה\"\u0004 (בראשית לח, כו). \u0003אמר שמואל סבא\u0004 \u0005[הזקן]\u0006 \u0003חמוה\u0004 \u0005[חמיו]\u0006 של \u0003רב שמואל בר אמי משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב שמואל בר אמי: כיון שידעה\u0004 שלשם שמים נתכוונה — \u0003שוב לא פסק ממנה; כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"ולא יסף עוד לדעתה\" וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 במתן תורה: \u0003\"קול גדול ולא יסף\"\u0004 (דברים ה, יט), שאנו מפרשים — לא פסק, לא נאסף ונגמר.","שנינו במשנה: \u0003אבשלום נתגאה בשערו\u0004 ובשערו נענש. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אבשלום ב\u0004גלל \u0003שערו מרד\u0004 וחטא, \u0003שנאמר: \"וכאבשלום לא היה איש יפה\u0004 בכל ישראל... \u0003ובגלחו את ראשו והיה מקץ ימים לימים אשר יגלח כי כבד עליו וגלחו ושקל את שער ראשו מאתים שקלים באבן המלך\"\u0004 (שמואל ב יד, כה-כו). ומהי אבן המלך? \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003אבן שאנשי טבריא\u0004 (טבריה) \u0003ואנשי ציפורי שוקלים בה.\u0004","ומפני שהיה שערו נאה ביותר ונתגאה בו \u0003לפיכך נתלה בשערו, שנאמר: \"ויקרא אבשלום לפני עבדי דוד ואבשלום רכב על הפרד, ויבא הפרד תחת שובך האלה הגדולה ויחזק ראשו באלה ויתן בין השמים ובין הארץ והפרד אשר תחתיו עבר\"\u0004 (שמואל ב יח, ט). \u0003שקל ספסירא בעא למיפסקיה\u0004 \u0005[לקח\u0006 אבשלום \u0005חרב\u0006 ו\u0005רצה לחתוך אותו\u0006 את השיער\u0005]\u0006 כדי להיחלץ. \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: באותה שעה נבקע שאול מתחתיו,\u0004 ופחד ליפול בתוכו, ולא חתך את שערו.","נאמר \u0003\"וירגז המלך ויעל על עלית השער ויבך, וכה אמר בלכתו בני אבשלום בני בני אבשלום מי יתן מותי אני תחתיך אבשלום בני בני\"\u0004 (שמואל ב יט, א) \u0003\"והמלך לאט את פניו ויזעק המלך קול גדול בני אבשלום אבשלום בני בני\"\u0004 (שמואל ב יט, ה). ושואלים: \u0003הני תמניא\u0004 \u0005[אותם שמונה]\u0006 פעמים \u0003\"בני\"\u0004 שאמר דוד \u0003למה\u0004 הם? ומסבירים: \u0003שבעה\u0004 פעמים התפלל עליו ועל ידי כך פעל \u0003דאסקיה\u0004 \u0005[שהעלה אותו]\u0006 \u0003משבעה מדורי גיהנם?\u0004 שהיה ראוי לו להיות בהם, \u0003ואידך\u0004 \u0005[והאחרת,\u0006 השמינית\u0005],\u0006 \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 \u0003דקריב רישיה לגבי גופיה\u0004 \u0005[שקירב\u0006 את \u0005ראשו אל גופו],\u0006 \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 \u0003דאייתיה לעלמא דאתי\u0004 \u0005[שהביא אותו ל\u0006חיי \u0005העולם הבא].\u0006","נאמר \u0003\"ואבשלם לקח ויצב לו בחיו\"\u0004 (שמואל ב יח, יח) ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003לקח\u0004 כאן, הרי לא נאמר מה לקח? \u0003אמר ריש לקיש: שלקח מקח רע לעצמו,\u0004 ומשום שלקח לעצמו עצה רעה נענש. על הנאמר \u0003\"את מצבת אשר בעמק המלך\"\u0004 (שמואל ב יח, יח) \u0003אמר ר' חנינא בר פפא,\u0004 רמז הוא: \u0003בעצה עמוקה של מלכו של עולם\u0004 (הקדוש ברוך הוא), והוא הנרמז בכתוב \"עמק המלך\"."],["\u0003\"הנני מקים עליך רעה מביתך\"\u0004 (שמואל ב יב, יא), ועל ידי אבשלום התקיימה בו נבואה זו. \u0003כיוצא בדבר אתה אומר\u0004 על יוסף ששלחו אביו לראות את שלום אחיו: \u0003\"וישלחהו מעמק חברון\"\u0004 (בראשית לז, יד) — \u0003אמר ר' חנינא בר פפא: בעצה עמוקה\u0004 (\"מעמק\") \u0003של אותו צדיק שקבור בחברון,\u0004 כלומר, אברהם אבינו, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 לו בברית בין הבתרים: \u0003\"ידע תדע כי גר יהיה זרעך\u0004 בארץ לא להם\u0003\"\u0004 (בראשית טו, יג) ועל ידי הליכתו זאת של יוסף נתגלגל לבסוף שירדו בני ישראל למצרים.","ועוד נאמר באבשלום \u0003\"כי אמר אין לי בן\"\u0004 (שמואל ב יח, יח). ותוהים: \u0003ו\u0004כי \u0003לא הוו ליה בני\u0004 \u0005[היו לו בנים]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ויולדו לאבשלום שלשה בנים ובת אחת\"\u0004 (שמואל ב יד, כז)! \u0003אמר רב יצחק בר אבדימי: שלא היה לו בן הגון\u0004 (ראוי) \u0003למלכות. רב חסדא אמר: גמירי\u0004 \u0005[למודים\u0006 אנו\u0005]\u0006 במסורת: \u0003כל השורף תבואתו של חבירו —\u0004 \u0003אינו מניח בן ליורשו. ואיהו קלייה לדיואב\u0004 \u0005[והוא שרף\u0006 את תבואתו \u0005של יואב],\u0006 \u0003דכתיב\u0004 \u0003[שנאמר]:\u0004 \u0003\"ויאמר אל עבדיו ראו חלקת יואב אל ידי ולו שם שערים לכו והציתוה באש ויצתו עבדי אבשלום את החלקה באש\"\u0004 (שמואל ב יד, ל).","עוד שנינו במשנה: \u0003וכן לענין הטובה\u0004 משלם הקדוש ברוך הוא מידה במידה; \u0003מרים\u0004 על שהמתינה למשה שעה אחת — המתינו לה כל ישראל שבעה ימים. ושואלים: \u0003מי דמי\u0004 \u0005[האם דומה]\u0006 הדבר? הלא לא נמדד שכרה באותה מידה שנהגה היא, שכן \u0003התם\u0004 \u0005[שם] —\u0006 המתינה מרים \u0003חדא שעתא\u0004 \u0005[שעה אחת],\u0006 \u0003הכא\u0004 \u0005[כאן] —\u0006 \u0003שבעה יומי\u0004 \u0005[ימים]\u0006 המתינו לה! \u0003אמר אביי: אימא\u0004 \u0005[אמור]\u0006 בשינוי קצת: \u0003ולענין הטובה אינו כן\u0004 ואין משלמים לאדם בדיוק מידה כנגד מידה אלא יותר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: הא\u0004 \u0005[הרי]\u0006 \u0003\"וכן לענין הטובה\" קתני\u0004 \u0005[שנה]\u0006 התנא, משמע שתשלום הרעה והטובה באותה מידה! \u0003אלא אמר רבא: הכי קתני\u0004 \u0005[כך שנה],\u0006 כך יש להבין: \u0003וכן\u0004 הוא \u0003לענין הטובה,\u0004 ש\u0003באותה מדה,\u0004 כלומר, באותו אופן, משלמים לו לאדם, \u0003ו\u0004אולם \u0003לעולם מדה טובה מרובה ממדת פורענות,\u0004 ולכן אינו מקבל כגמולו בלבד אלא יותר ממה שעשה.","נאמר במרים \u0003\"ותתצב אחתו מרחק\"\u0004 (שמות ב, ד). \u0003אמר ר' יצחק: פסוק זה כולו על שם שכינה נאמר,\u0004 שהוא רומז להשגחת השכינה על משה רבינו: \u0003\"ותתצב\" —\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויבא ה' ויתיצב\"\u0004 (שמואל א ג, י), \u0003\"אחותו\" —\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אמר לחכמה אחתי את\"\u0004 (משלי ז, ד), \u0003\"מרחק\" —\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"מרחוק ה' נראה לי\"\u0004 (ירמיה לא, ב), \u0003\"לדעת\" —\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי אל דעות ה'\"\u0004 (שמואל א ב, ג), \u0003\"מה\" —\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"מה ה' אלהיך שאל מעמך\"\u0004 (דברים י, יב), \u0003\"יעשה\" —\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי לא יעשה ה' אלהים דבר\"\u0004 (עמוס ג, ז), \u0003\"לו\" —\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויאמר לו ה' שלום\"\u0004 (שופטים ו, כג).","נאמר \u0003\"ויקם מלך חדש\u0004 על מצרים\u0003\"\u0004 (שמות א, ח), \u0003רב ושמואל\u0004 נחלקו בפירוש הדבר; \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 מלך \u0003חדש ממש, וחד\u0004 \u0005[ואחד]\u0006 \u0003אמר: שנתחדשו גזירותיו\u0004 כאילו היה זה מלך חדש. \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שמלך \u0003חדש ממש\u0004 היה — \u0003דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]\u0006 במפורש \u0003\"חדש\". ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 \u0003שנתחדשו גזירותיו,\u0004 הרי זה משום ש\u0003לא כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"וימת\u0004 מלך מצרים \u0003וימלוך\u0004 מלך חדש \u0003\"\u0004, משמע שאותו מלך היה. ולפי זה \u0003\"אשר לא ידע את יוסף\"\u0004 (שמות א, ח) הכוונה היא: \u0003דהוה דמי כמאן\u0004 \u0005[שהיה דומה כמי]\u0006 ש\u0003לא ידע ליה\u0004 \u0005[אותו]\u0006 \u0003כלל,\u0004 אף על פי שבודאי ידע את מעשי יוסף.","נאמר: \u0003\"ויאמר אל עמו הנה עם בני ישראל\"\u0004 (שמות א, ט). \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003הוא,\u0004 פרעה, \u0003התחיל בעצה תחילה —\u0004 \u0003לפיכך לקה תחילה\u0004 מכל עמו. \u0003הוא התחיל בעצה תחילה —\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויאמר אל עמו\", לפיכך לקה תחילה —\u0004 \u0003כדכתיב\u0004 \u0005[כפי שנאמר]:\u0006 \u0003\"ובכה ובעמך ובכל עבדיך\u0004 יעלו הצפרדעים","\u0003\"\u0004(שמות ז, כט). נאמר \u0003\"הבה נתחכמה לו\"\u0004 (שמות א, י) ותוהים: הלא \u0003\"להם\" מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר! \u0003אמר ר' חמא בר' חנינא: באו ונחכם למושיען של ישראל,\u0004 וזה טעם \"לו\" — לקדוש ברוך הוא. ומה היה צד התחכמות זה?","שדן בדבר: \u0003במה נדונם,\u0004 באיזו מיתה נמית את ישראל? \u0003אם\u0004 \u0003נדונם באש\u0004 — שמא ניענש מידה כנגד מידה באש, שהרי \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"כי הנה ה' באש יבוא\"\u0004 (ישעיה סו, טו), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"כי באש ה' נשפט\"\u0004 (ישעיה סו, טז). אם נדונם \u0003בחרב —\u0004 \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003[\"ובחרבו את כל בשר\"]\u0004 (ישעיה סו, טז).","\u0003אלא בואו ונדונם במים,\u0004 שלא יוכל הקדוש ברוך הוא להעניש אותנו באותה מידה, \u0003שכבר נשבע הקדוש ברוך הוא שאינו מביא מבול לעולם, שנאמר:\u0004 \u0003\"כי מי נח זאת לי\u0004 אשר נשבעתי מעבור מי נח עוד על הארץ\u0003\"\u0004 (ישעיה נד, ט). ומעירים: \u0003והן,\u0004 המצרים, \u0003אינן יודעין שעל כל העולם כולו\u0004 ביחד \u0003אינו מביא\u0004 מבול, שעל כך היתה השבועה, \u0003אבל על אומה אחת הוא מביא.\u0004","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 יש דרך אחרת להענישם במים: \u0003הוא אינו מביא\u0004 עליהם מבול, \u0003אבל הן באין ונופלין בתוכו\u0004 בתוך המים, \u0003וכן הוא אומר:\u0004 \u0003\"\u0004וישב הים לפנות בקר לאיתנו \u0003ומצרים נסים לקראתו\"\u0004 (שמות יד, כז). \u0003והיינו\u0004 \u0005[וזהו]\u0006 ש\u0003אמר ר' אלעזר: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"כי בדבר אשר זדו עליהם\"\u0004 (שמות יח, יא) — לומר: \u0003בקדירה שבישלו —\u0004 \u0003בה נתבשלו\u0004 שעונשם היה מידה כנגד מידה שטבעו בים. ושואלים: \u0003מאי משמע\u0004 \u0005[מהי המשמעות]\u0006 \u0003דהאי \"זדו\" לישנא דקדירה\u0004 \u0005[ש\"זדו\" זה לשון קדירה\u0006 (בישול)\u0005]\u0006 \u0003הוא —\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויזד יעקב נזיד\"\u0004 (בראשית כה, כט).","\u0003אמר ר' חייא בר אבא אמר ר' סימאי: שלשה\u0004 אנשי שם \u0003היו\u0004 עם פרעה \u0003באותה עצה\u0004 שהתייעץ עימם מה לעשות בישראל, והם: \u0003בלעם, ואיוב, ויתרו.\u0004","\u0003בלעם שיעץ\u0004 עצה זו לפרעה — עונשו היה ש\u0003נהרג\u0004 במלחמת מדין (ראה במדבר לא, ח), \u0003איוב ששתק\u0004 ולא אמר דבר — \u0003נידון ביסורין,\u0004 כפי שנאמר בספרו. \u0003יתרו שברח\u0004 מפני שלא רצה להשתתף בעצה — \u0003זכו מבני בניו שישבו בלשכת הגזית\u0004 בסנהדרין, \u0003שנאמר:\u0004 \u0003\"ומשפחות סופרים ישבי יעבץ תרעתים שמעתים שוכתים המה הקינים הבאים מחמת אבי בית רכב\"\u0004 (דברי הימים א ב, נה), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"ובני קיני חתן משה\"\u0004 (שופטים א, טז), משמע שהם היו הקינים \"יושבי יעבץ\" = יושבי מקום העצה של ישראל, לשכת הגזית.","נאמר שאמר פרעה: \u0003\"ונלחם בנו ועלה מן הארץ\"\u0004 (שמות א, י), ולכאורה \u0003\"ועלינו\" מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר, שהרי התכוון לומר שישראל יילחמו במצרים ולבסוף יבריחו את המצרים ממקומם! \u0003אמר ר' אבא בר כהנא: כאדם שמקלל את עצמו, ו\u0004כיון שאינו רוצה להוציא מפיו קללה על עצמו \u0003תולה קללתו בחבירו.\u0004","נאמר \u0003\"וישימו עליו שרי מסים\"\u0004 (שמות א, יא), ולכאורה \u0003\"עליהם\" מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר! \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' אלעזר בר' שמעון: מלמד ש\u0004בתחילה \u0003הביאו מלבן\u0004 (כלי שעושים בו לבנים) \u0003ותלו לו לפרעה בצוארו\u0004 כאילו אף הוא משתתף בעבודה, \u0003וכל אחד ואחד מישראל שאמר להם\u0004 למצרים: \u0003איסטניס\u0004 (מפונק) \u0003אני\u0004 ואיני רגיל בעבודה כזו, \u0003אמרו לו: כלום איסטניס אתה יותר מפרעה?\u0004 ולכן נאמר ששמו \"עליו\" — על פרעה, ועל ידי כך העבידו את כל ישראל בפרך.","מה שנאמר \u0003\"שרי מסים\" — הכוונה ל\u0004\u0003דבר שמשים\u0004 (רודה) \u0003(לבנים),\u0004 שכשרואים אותו חייבים לעבוד.","וכן המשך הכתוב \u0003\"למען ענתו בסבלתם\"\u0004 (שמות א, יא), הלא \u0003\"ענותם\" מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר! אלא הכוונה היא כפי שאמרנו: \u0003למען ענותו לפרעה בסבלותם\u0004 של \u0003ישראל.\u0004","בדיוק לשון הכתוב \u0003\"ויבן ערי מסכנות לפרעה\"\u0004 (שמות א, יא) נחלקו \u0003רב ושמואל,\u0004 \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 הכוונה היא \u0003שמסכנות את בעליהן,\u0004 שיש בהן בניינים גבוהים ומסוכן לעבוד בהן. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: שממסכנות\u0004 (גורמות עניות) \u0003את בעליהן,\u0004 שכל העוסק בבנין כך קורה לו, ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003כל העוסק בבנין מתמסכן\u0004 (נהיה עני), והוא לשון \"מסכנות\".","בענין הכתוב \u0003\"את פתם ואת רעמסס\"\u0004 (שמות א, יא) נחלקו \u0003רב ושמואל,\u0004 \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: פיתום שמה\u0004 באמת, \u0003ולמה נקרא שמה רעמסס\u0004 — כינוי הוא, \u0003שראשון ראשון\u0004 מן הבניינים שהיו בונים היה \u0003מתרוסס\u0004 (נשבר, מתמוטט). \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: רעמסס\u0004 היה \u0003שמה, ולמה נקרא שמה פיתום —\u0004 \u0003שראשון ראשון\u0004 מן הבניינים שהיו בונים \u0003פי תהום בולעו.\u0004","נאמר בהמשך \u0003\"וכאשר יענו אתו כן ירבה וכן יפרץ\"\u0004 (שמות א, יב), ושואלים: \u0003\"כן רבו וכן פרצו\" מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר! \u0003אמר ריש לקיש: רוח הקדש\u0004 היתה \u0003מבשרתן\u0004 את ישראל: שככל שיענו עם זה \u0003כן ירבה וכן יפרוץ.\u0004 נאמר \u0003\"ויקצו מפני בני ישראל\"\u0004 (שמות א, יב) ומסבירים: \u0003מלמד שהיו דומין\u0004 בני ישראל \u0003בעיניהם\u0004 של המצריים \u0003כקוצים\u0004 הדוקרים אותם.","על מה שנאמר \u0003\"ויעבדו מצרים את בני ישראל\u0004"],["\u0003בפרך\"\u0004 (שמות א, יג) \u0003ר' אלעזר אמר: בפה רך,\u0004 שהתחילו לשעבדם בדרך ריצוי ופיתוי. \u0003ר' שמואל בר נחמני אמר: בפריכה\u0004 (בשבירה).","נאמר: \u0003\"וימררו את חייהם בעבדה קשה בחמר ובלבנים\u0004 ובכל עבודה בשדה\u0003\"\u0004 (שמות א, יד). \u0003אמר רבא: בתחילה\u0004 נתנו להם עבודה \u0003בחומר ובלבנים, ולבסוף \"ובכל עבדה בשדה\"\u0004 (שמות א, יד).","על המשך הפסוק \u0003\"את כל עבדתם אשר עבדו בהם בפרך\"\u0004 (שמות א, יד), \u0003אמר ר' שמואל בר נחמני אמר ר' יונתן: שהיו מחליפין מלאכת אנשים לנשים ומלאכת נשים לאנשים,\u0004 וזוהי עבודת פרך — שהיו סובלים מעבודה שאינה לפי טבעם והרגלם. \u0003ולמאן דאמר נמי התם\u0004 \u0005[ול\u0006דעת \u0005מי שאומר גם כן שם]\u0006 בפסוק הקודם ש\"בפרך\" פירושו \u0003בפה רך, הכא\u0004 \u0005[כאן]\u0006 בפסוק זה העוסק בקושי הגופני של העבודה, \u0003ודאי\u0004 הכוונה היא \u0003בפריכה.\u0004","\u0003דרש רב עוירא: בשכר נשים צדקניות שהיו באותו הדור נגאלו ישראל ממצרים.\u0004 כיצד היה הדבר? \u0003בשעה שהולכות\u0004 הנשים \u0003לשאוב מים, הקדוש ברוך הוא מזמן להם דגים קטנים בכדיהן, ושואבות מחצה מים ומחצה דגים, ובאות ושופתות\u0004 (מניחות על האש) \u0003שתי קדירות, אחת של\u0004 מים \u0003חמין ואחת של דגים.\u0004","\u0003ומוליכות אצל בעליהן לשדה, ומרחיצות אותן\u0004 את הבעלים, \u0003וסכות אותן, ומאכילות אותן, ומשקות אותן, ונזקקות להן\u0004 לתשמיש \u0003בין שפתים\u0004 (בין גבולות וגדרות השדות), \u0003שנאמר: \"אם תשכבון בין שפתים\"\u0004 (תהלים סח, יד), ודרשו על כך: \u0003בשכר \"תשכבון בין שפתים\" זכו ישראל לביזת מצרים, שנאמר\u0004 בהמשך הפסוק: \u0003\"כנפי יונה נחפה בכסף ואברותיה בירקרק חרוץ\"\u0004 (תהלים סח, יד).","\u0003וכיון ש\u0004היו הנשים \u0003מתעברות באות לבתיהם, וכיון שמגיע זמן מולדיהן\u0004 (הלידה) \u0003הולכות ויולדות בשדה תחת\u0004 עצי \u0003התפוח, שנאמר: \"תחת התפוח עוררתיך\u0004 שמה חבלתך אמך, שמה חבלה ילדתך\u0003\"\u0004(שיר השירים ח, ה).","\u0003והקדוש ברוך הוא שולח\u0004 מלאך \u0003משמי מרום מי שמנקיר ומשפיר\u0004 (מנקה ומתקן) \u0003אותן\u0004 את הילודים, \u0003כחיה\u0004 (מילדת) \u0003זו שמשפרת את הולד, שנאמר: \"ומולדותיך ביום הולדת אותך לא כרת שרך ובמים לא רחצת למשעי\"\u0004 (יחזקאל טז, ד), כלומר, לא היתה להם מילדת שתוכל לטפל בהם. \u0003ומלקט להן\u0004 המלאך מן השדה אבנים כעין \u0003שני עגולין,\u0004 והיו נובעים מתוכם דברי מאכל \u0003אחד של שמן ואחד של דבש,\u0004 ומהם היו יונקים, \u0003שנאמר: \"וינקהו דבש מסלע ושמן\u0004 מחלמיש צור\u0003\"\u0004(דברים לב, יג).","\u0003וכיון שמכירין בהן מצרים\u0004 שהם ילדי ישראל \u0003באין להורגן, ונעשה להם נס ונבלעין בקרקע, ומביאין\u0004 המצרים \u0003שוורים וחורשין על גבן שנאמר: \"על גבי חרשו חרשים\"\u0004 (תהלים קכט, ג). \u0003לאחר שהולכין\u0004 המצרים \u0003היו מבצבצין\u0004 התינוקות \u0003ויוצאין\u0004 מן האדמה \u0003כעשב השדה, שנאמר: \"רבבה כצמח השדה נתתיך\"\u0004 (יחזקאל טז, ז).","\u0003וכיון שמתגדלין באין עדרים עדרים לבתיהן\u0004 בחזרה, \u0003שנאמר: \"ותרבי ותגדלי ותבאי בעדי עדיים\"\u0004 (יחזקאל טז, ז) \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"בעדי עדיים\" אלא \"בעדרי עדרים\".\u0004","\u0003וכשנגלה הקדוש ברוך הוא על הים\u0004 בים סוף \u0003הם\u0004 התינוקות \u0003הכירוהו תחלה, שנאמר: \"זה אלי ואנוהו\"\u0004 (שמות טו, ב), כלומר, זה שהכירוהו עוד מזמן שנגלה עליהם בעודם תינוקות.","נאמר \u0003\"ויאמר מלך מצרים למילדת העברית\"\u0004 (שמות \u0003א, טו);\u0004 \u0003רב ושמואל\u0004 נחלקו בכך, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 מילדות אלה היו \u0003אשה ובתה, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: כלה וחמותה. מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שהיו אלה \u0003אשה ובתה,\u0004 כוונתו היא ל\u0003יוכבד\u0004 אם משה ואהרן, \u0003ו\u0004לבתה \u0003מרים, ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 שהיו אלה \u0003כלה וחמותה —\u0004 \u0003יוכבד ו\u0004כלתה \u0003אלישבע\u0004 אשת אהרן.","\u0003תניא כמאן דאמר\u0004 \u0005[שנויה\u0006 ברייתא \u0005כ\u0006דעת \u0005מי שאומר]\u0006 שהיו אלה \u0003אשה ובתה, דתניא\u0004 \u0003[ש\u0004כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003שפרה —\u0004 \u0003זו יוכבד, ולמה נקרא שמה שפרה —\u0004 \u0003שמשפרת\u0004 (מתקנת) \u0003את הולד.\u0004 \u0003דבר אחר: \"שפרה\" —\u0004 \u0003שפרו ורבו ישראל בימיה.\u0004","\u0003\"פועה\" —\u0004 \u0003זו מרים, ולמה נקרא שמה \"פועה\" —\u0004 \u0003שהיתה פועה\u0004 (משמיעה קול) \u0003ומוציאה את הולד. דבר אחר: \"פועה\"\u0004 מלשון דיבור, \u0003שהיתה פועה ברוח הקודש ואומרת: עתידה אמי שתלד בן שמושיע את ישראל.\u0004","נאמר שם \u0003\"ויאמר\u0004 (פרעה) \u0003בילדכן את העבריות\u0004 וראיתן על האבניים\u0003\"\u0004 (שמות א, טז). ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"\u0004\u0003אבנים\"? אמר ר' חנן: סימן גדול מסר להן\u0004 פרעה. \u0003אמר להן: בשעה ש\u0004אשה \u0003כורעת לילד יריכותיה מצטננות כאבנים,\u0004 וזה יהיה לכן סימן שהיא עומדת ללדת.","\u0003ואית דאמר\u0004 \u0005[ויש\u0006 מי \u0005שאומר]:\u0006 \u0003כדכתיב\u0004 \u0005[כפי שנאמר]:\u0006 \u0003\"וארד בית היוצר והנה הוא עשה מלאכה על האבנים\"\u0004 (ירמיה יח, ג), \u0003מה יוצר\u0004 (קדר) \u0003זה\u0004 יושב באופן ש\u0003ירך\u0004 אחת שלו \u0003מכאן וירך מכאן, וסדן\u0004 שעליו הוא עובד \u0003באמצע, אף אשה —\u0004 \u0003ירך מכאן וירך מכאן והולד באמצע.\u0004","\u0003\"\u0004וראיתן על האבניים \u0003אם בן הוא והמתן אתו\"\u0004 (שמות א, טז). \u0003אמר ר' חנינא: סימן גדול מסר להן\u0004 לדעת כבר בתחילת הלידה (\"על האבניים\") מהו מינו של הוולד; \u0003בן\u0004 נולד כש\u0003פניו למטה, בת\u0004 נולדת כש\u0003פניה למעלה.\u0004 ונתן להן סימן זה, כדי שתוכלנה להרוג את הוולד בסתר, עוד לפני שנולד.","\u0003\"ותיראן המילדת את האלהים ולא עשו כאשר דבר אליהן\u0004 מלך מצרים\u0003\"\u0004 (שמות א, יז). ושואלים: \u0003\"דיבר להן\" מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר! \u0003אמר ר' יוסי בר' חנינא:\u0004 שינוי הלשון \u0003מלמד ש\u0004נוסף לכך \u0003תבען לדבר עבירה\u0004 (כאמור במקום אחר ככינוי לביאה \"ויבוא אליה\", בראשית כט, כג), \u0003ולא נתבעו\u0004 (נענו).","\u0003\"ותחיין את הילדים\"\u0004 (שמות א, יז). \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003לא דיין שלא המיתו אותן\u0004 כפי שאמר פרעה, \u0003אלא שהיו מספיקות להם\u0004 עוד \u0003מים ומזון.\u0004 ולשון \"ותחיינה\" פירושו שהיו מסייעות להם לחיות.","נאמר: \u0003\"ותאמרן המילדת אל פרעה כי לא כנשים\u0004 המצריות העבריות כי חיות הנה\"\u0005(שמות א, יט)\u0006. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"\u0004\u0003חיות\"\u0004\u0003? אילימא\u0004 \u0005[אם נאמר]\u0006 \u0003חיות ממש\u0004 במובן מילדות, \u0003אטו חיה מי לא צריכה חיה אחריתי לאולודה\u0004 \u0005[האם מילדת אינה צריכה מילדת אחרת לילד אותה]?\u0006","\u0003אלא אמרו לו\u0004 המילדות לפרעה: \u0003אומה זו כחיה נמשלה,\u0004 וחיות יולדות בלא מילדת. ומהיכן אתה לומד שנמשלה אומה זו לחיה? — \u0003יהודה\u0004 נאמר בו \u0003\"גור אריה\"\u0004 (בראשית מט, ט), \u0003דן —\u0004 \u0003\"יהי דן נחש\"\u0004 (בראשית מט, יז), \u0003נפתלי —\u0004 \u0003\"אילה שלחה\"\u0004 (בראשית מט, כא), \u0003יששכר —\u0004 \u0003\"חמר גרם\"\u0004 (בראשית מט, יד), \u0003יוסף —\u0004 \u0003\"בכור שור\"\u0004 (ראה דברים לג, יז), \u0003בנימין —\u0004 \u0003\"זאב יטרף\"\u0004 (בראשית מט, כז).","ומעירים: \u0003דכתיב ביה\u0004 \u0005[\u0006זה \u0005שנאמר בו]\u0006 דימוי לחיה — \u0003כתיב ביה\u0004 \u0005[נאמר בו],\u0006 \u0003ודלא כתיב ביה\u0004 \u0005[ו\u0006זה \u0005שלא נאמר בו]\u0006 במפורש, מכל מקום \u0003כתיב ביה\u0004 \u0005[נאמר בו]\u0006 בעם ישראל באופן כללי: \u0003\"מה אמך לביא בין אריות רבצה\"\u0004 (יחזקאל יט, ב).","בענין הנאמר \u0003\"ויהי כי יראו המילדת את האלהים ויעש להם בתים\"\u0004 (שמות א, כא) נחלקו \u0003רב ושמואל;\u0004 \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: בתי\u0004 (משפחות) \u0003כהונה ולויה\u0004 עשה להן, \u0003וחד\u0004 \u0005[ואחד]\u0006 \u0003אמר: בתי מלכות. מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003בתי כהונה ולויה\u0004 — הרי הם \u0003אהרן ומשה\u0004 שיצאו מיוכבד. \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 \u0003בתי מלכות —\u0004 \u0003דוד נמי\u0004 \u0005[גם כן]\u0006 \u0003ממרים קאתי\u0004 \u0005[בא],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ותמת עזובה (אשת כלב) ויקח לו כלב את אפרת ותלד לו את חור\"\u0004 \u0003(דברי הימים א ב, יט) וכאשר יבואר להלן אפרת היא מרים,\u0004 \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ודוד בן איש אפרתי\"\u0004 (שמואל א יז, יב).","נאמר בדברי הימים \u0003\"וכלב בן חצרון הוליד את עזובה אשה ואת יריעות ואלה בניה ישר ושובב וארדון\"\u0004 (דברי הימים א, ב, יח). את הכתוב הזה דורשים: וכי \u0003בן חצרון\u0004 הוא כלב? הלא \u0003בן יפנה הוא!\u0004 (כאמור במדבר יג, ו). ומסבירים: \"בן יפונה\" הוא כינוי — \u0003בן שפנה מעצת מרגלים.\u0004","ותוהים, \u0003ואכתי\u0004 \u0005[ועדיין]\u0006 קשה: הלא \u0003בן קנז הוא, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וילכדה עתניאל בן קנז אחי כלב\"\u0004 (שופטים א, יג), משמע שאביו של כלב שמו היה קנז! \u0003אמר רבא:\u0004 בנו \u0003חורגו\u0004 של \u0003קנז הוה\u0004 \u0005[היה]\u0006 כלב, ועתניאל היה אח חורג לו."],["\u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 ממה \u0003דכתיב\u0004 \u0003[שנאמר]:\u0004 \u0003\"\u0004כלב בן יפונה \u0003הקנזי\"\u0004 (יהושע יד, ו), משמע שהיה קשור למשפחת קנז, אבל לא היה בן קנז ממש. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003\"עזובה\"\u0004 (דברי הימים א ב, יח) — \u0003זו מרים, ולמה נקרא שמה עזובה —\u0004 \u0003שהכל עזבוה מתחילתה\u0004 ולא רצו לשאתה מפני שהיתה חולנית ולא יפה. ושואלים על הלשון: \u0003\"הוליד\"? והלא\u0004 כמו שפירשנו \u0003מינסב הוה נסיב לה\u0004 \u0005[נשא אותה]!\u0006 \u0003אמר ר' יוחנן:\u0004 דבר זה מלמדנו כי \u0003כל הנושא אשה לשם שמים —\u0004 \u0003מעלה עליו הכתוב כאילו ילדה.\u0004","\u0003\"יריעות\"\u0004 נדרש — \u0003שהיו פניה דומין ליריעות\u0004 שהיתה חיוורת ביותר.","\u0003\"ואלה בניה\"\u0004 — \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003בניה אלא בוניה,\u0004 כלומר, אלה הם כינויים של בעלה, שעל ידי שנשאה כאילו בנה אותה, \u0003\"ישר\" —\u0004 \u0003שישר את עצמו,\u0004 ולא שמע לעצת המרגלים. \u0003\"שובב\" —\u0004 \u0003ששיבב\u0004 (שיבר) \u0003את יצרו, ו\"ארדון\" —\u0004 \u0003שרדה את\u0004 (משל על) \u0003יצרו, ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 \u0003על שהיו פניה\u0004 של מרים אשתו \u0003דומין לורד\u0004 לאחר שנישאת, ולכן נקרא ורדון.","נאמר \u0003\"ולאשחור אבי תקוע היו שתי נשים חלאה ונערה\"\u0004 (דברי הימים א ד, ה), ודורשים: \u0003\"אשחור\" —\u0004 \u0003זה כלב, ולמה נקרא שמו אשחור —\u0004 \u0003שהושחרו פניו בתעניות,\u0004 שהיה צם כדי שלא ייכשל בעצת המרגלים. \u0003\"אבי\" —\u0004 \u0003שנעשה לה\u0004 לאשתו \u0003כאב, \"תקוע\" —\u0004 \u0003שתקע\u0004 (חיבר) \u0003את לבו לאביו שבשמים.\u0004","\u0003\"היו שתי נשים\",\u0004 כלומר, — \u0003נעשה\u0004 (נעשית) \u0003מרים כשתי נשים\u0004 לפי שנשתנתה במשך הזמן. ולפיכך, \u0003\"חלאה ונערה\" —\u0004 \u0003לא\u0004 שתי נשים \u0003חלאה ונערה הואי\u0004 \u0005[היו],\u0006 \u0003אלא בתחילה\u0004 היתה מרים כ\u0003חלאה\u0004 (חולה וזנוחה), \u0003ולבסוף\u0004 היתה בריאה ויפה כ\u0003נערה.\u0004","נאמר \u0003\"ובני חלאה צרת וצהר ואתנן\"\u0004 (דברי הימים א ד, ז), ומפרשים שלא בנים הם, אלא מה נשתנה בה לאחר שנבנתה, \u0003\"צרת\" —\u0004 \u0003שנעשית צרה לחברותיה,\u0004 שהיתה יפה כל כך שכל אשה היתה מתקנאה ביופיה. \u0003\"צהר\" —\u0004 \u0003שהיו פניה\u0004 מאירים ו\u0003דומין כצהרים, \"אתנן\" —\u0004 \u0003שכל הרואה אותה\u0004 מתאוה עד שהוא \u0003מוליך אתנן\u0004 (מתנה) \u0003לאשתו\u0004 לרצותה.","ושוב לענין פרשת שיעבוד מצרים. נאמר: \u0003\"ויצו פרעה לכל עמו\u0004 לאמר כל הבן הילוד היאורה תשליכוהו \u0003\"\u0004\u0003(שמות א, כב).\u0004 \u0003אמר ר' יוסי בר' חנינא:\u0004 מלשון הכתוב \"לכל עמו\" משמע ש\u0003אף על עמו גזר\u0004 גזירה זו. \u0003ואמר ר' יוסי בר' חנינא: שלש גזירות גזר, בתחילה\u0004 אמר רק למילדות \u0003\"אם בן הוא והמתן אתו\"\u0004 (שמות א, טז), \u0003ולבסוף\u0004 גזר על ישראל בלבד \u0003\"כל הבן הילוד היארה תשליכהו\"\u0004 (שמות א, כב), \u0003ולבסוף אף על עמו גזר,\u0004 שאף את בני המצרים ישליכו.","נאמר \u0003\"וילך איש מבית לוי\"\u0004 (שמות ב, א). ושואלים: \u0003להיכן הלך? אמר רב יהודה בר זבינא: שהלך בעצת בתו\u0004 מרים. ומה עניינו?","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003עמרם גדול הדור היה, כיון שראה שאמר פרעה הרשע \"כל הבן הילוד היארה תשליכהו\"\u0004 (שמות א, כב) \u0003אמר: לשוא אנו עמלין\u0004 ומולידים בנים, שהרי בסופו של דבר הורגים אותם, \u0003עמד וגירש את אשתו. עמדו כולן\u0004 ועשו כמוהו \u0003וגירשו את נשותיהן.\u0004","\u0003אמרה לו\u0004 מרים \u0003בתו: אבא, קשה גזירתך\u0004 על ישראל \u0003יותר משל פרעה. שפרעה לא גזר אלא על הזכרים, ואתה גזרת על הזכרים ועל הנקיבות\u0004 שלא להוליד כלל. \u0003פרעה לא גזר אלא בעולם הזה\u0004 שיהרגום, \u0003ואתה בעולם הזה ולעולם הבא\u0004 שאם אין נולדים, אינם מגיעים כלל לחיי עולם הבא.","\u0003פרעה הרשע\u0004 כיון שרשע הוא — \u0003ספק מתקיימת גזירתו ספק אינה מתקיימת, אתה צדיק —\u0004 \u0003בודאי שגזירתך מתקיימת, שנאמר\u0004 בצדיקים: \u0003\"ותגזר אמר ויקם לך\"\u0004 (איוב כב, כח). שמע עמרם לדבריה, \u0003עמד והחזיר את אשתו,\u0004 ומשראו כך \u0003עמדו כולן והחזירו את נשותיהן.\u0004","ושואלים: הלא נאמר \u0003\"ויקח\u0004 את בת לוי \u0003\"\u0004\u0003(שמות ב, א), ולפי מה שאמרנו שגירשה והחזירה, אם כן\u0004 \u0003\"ויחזור\u0004 ויקח את בת לוי \u0003\" מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר! \u0003אמר רב יהודה בר זבינא: שעשה לו מעשה ליקוחין\u0004 (נישואין) כמו בנישואין ראשונים — \u0003הושיבה באפריון, ואהרן ומרים מרקדין לפניה, ומלאכי השרת אמרו \"אם הבנים שמחה\"\u0004 (תהלים קיג, ט).","נאמר: \u0003\"\u0004\u0003ויקח\u0004 \u0003את בת לוי\"\u0004 (שמות ב, א) ותוהים: \u0003אפשר בת מאה ושלשים שנה הויא\u0004 \u0005[היתה]\u0006 \u0003וקרי\u0004 \u0005[וקורא]\u0006 \u0003לה\u0004 עדיין \u0003\"בת\"?\u0004 ומניין שהיתה זקנה כל כך — ש\u0003אמר ר' חמא בר' חנינא:\u0004 בת לוי \u0003זו\u0004 היא \u0003יוכבד, שהורתה\u0004 (הריונה) היה \u0003בדרך\u0004 מארץ ישראל עם יעקב ובניו בירידתם למצרים \u0003ולידתה\u0004 עם כניסתם \u0003בין החומות\u0004 של מצרים, \u0003שנאמר:\u0004 \u0003\"\u0004\u0003ושם אשת עמרם יוכבד בת לוי\u0004 \u0003אשר ילדה אתה ללוי במצרים\"\u0004 (במדבר כו, נט), ודייק בלשון —","\u0003לידתה במצרים, ואין הורתה במצרים.\u0004 ואם כן כיצד קורא לה \"בת\"? \u0003אמר רב יהודה: שנולדו בה סימני נערות\u0004 ונעשתה שוב צעירה כבת.","נאמר: \u0003\"ותהר האשה ותלד בן\"\u0004 (שמות ב, ב). ושואלים: \u0003והא הות מיעברא ביה תלתא ירחי מעיקרא\u0004 \u0005[והרי היתה מעוברת בו\u0006 עוד \u0005שלושה חודשים קודם לכן]\u0006 לפני שחזר ולקחה, כפי שיבואר! \u0003אמר רב יהודה בר זבינא: מקיש\u0004 \u0005[משווה]\u0006 הכתוב \u0003לידתה להורתה, מה הורתה\u0004 (תחילת הריונה) \u0003שלא בצער —\u0004 \u0003אף לידתה\u0004 היתה \u0003שלא בצער. מכאן\u0004 אנחנו למדים \u0003לנשים צדקניות שלא היו בפיתקה\u0004 (בגזר דינה) \u0003של חוה,\u0004 שאשה הרה ויולדת בנים בצער.","נאמר \u0003\"ותרא אתו כי טוב הוא\"\u0004 (שמות ב, ב). \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' מאיר אומר: \"טוב\"\u0004 הוא \u0003שמו\u0004 האמיתי של משה, שניתן לו על יד הוריו בלידתו. \u0003ר' יהודה אומר: \"טוביה\" שמו. ר' נחמיה אומר:\u0004 שאמרו כן משום שבשעה שנולד ראו אותו שהוא \u0003הגון\u0004 (ראוי) \u0003לנביאות. אחרים אומרים: נולד כשהוא מהול. וחכמים אומרים: בשעה שנולד משה נתמלא הבית כולו אור,\u0004 וכך הוא לומד זאת: \u0003כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"ותרא אתו כי טוב הוא\" וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"וירא אלהים את האור כי טוב\"\u0004 (בראשית א, ד).","נאמר \u0003\"ותצפנהו שלשה ירחים\"\u0004 (שמות ב, ב) ומסבירים מדוע דווקא שלושה חודשים — ש\u0003לא מנו מצרים אלא משעה דאהדרה\u0004 \u0005[שהחזירה]\u0006 בעלה, שלפי חשבון זה החלו לחפש אחרי הילד, \u0003והיא הות מיעברא ביה תלתא ירחי מעיקרא\u0004 \u0005[והיא היתה מעוברת בו שלושה חודשים קודם לכן].\u0006","נאמר שם \u0003\"ולא יכלה עוד הצפינו\".\u0004 ושואלים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 לא יכלה? \u0003תצפניה ותיזיל\u0004 \u0005[תצפנהו ותלך\u0006 ותמשיך\u0005]!\u0006 \u0003אלא, כל היכא דהוו שמעי מצראי דמתיליד ינוקא, ממטו ינוקא התם\u0004 \u0005[כל מקום שהיו שומעים המצרים שנולד תינוק, היו מביאים תינוק\u0006 אחר \u0005לשם]\u0006 \u0003כי היכי דלישמעינהו ומעוי בהדיהו\u0004 \u0005[כדי שישמעו\u0006 אותו בוכה \u0005ויבכו ביחד],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אחזו לנו שועלים שעלים קטנים\"\u0004 (שיר השירים ב, טו) שהתינוקות הללו שהיו גורמים לגלות את הילדים המוחבאים נקראים \"שועלים קטנים\".","נאמר \u0003\"ותקח לו תבת גמא\"\u0004 (שמות ב, ג). ושואלים: \u0003מאי שנא\u0004 \u0005[במה שונה],\u0006 מדוע דווקא \u0003גומא? אמר ר' אלעזר: מיכן\u0004 (מכאן) \u0003לצדיקים שממונם חביב עליהן יותר מגופן,\u0004 ולכן לקחה דבר זול, משום שלא רצתה להוציא ממון הרבה. \u0003וכל כך למה\u0004 חביב עליהם יותר מגופם — \u0003לפי שאין פושטין ידיהן בגזל,\u0004 לפיכך חשוב הוא בעיניהם.","\u0003ר' שמואל בר נחמני אמר:\u0004 לא מטעם זה, אלא לקחה \u0003דבר רך\u0004 כגומא, \u0003שיכול לעמוד\u0004 הן \u0003בפני דבר רך ו\u0004הן \u0003בפני דבר קשה.\u0004 אבל אם היתה עושה התיבה מדבר קשה כעצים חששה שמא ייתקל בדבר קשה ויישבר.","בביאור הנאמר \u0003\"ותחמרה בחמר ובזפת\"\u0004 (שמות ב, ג), \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 מרחה \u0003חמר מבפנים וזפת מבחוץ, כדי שלא יריח אותו צדיק,\u0004 משה, \u0003ריח רע\u0004 של זפת.","על הנאמר \u0003\"ותשם בה את הילד ותשם בסוף\"\u0004 (שמות ב, ג) \u0003ר' אלעזר אומר:\u0004 ב\u0003ים סוף. ר' שמואל בר נחמני אמר:\u0004"],["\u0003אגם,\u0004 כלומר, במקום שצומחים בו שיחים וקנים הניחה אותו, \u0003כדכתיב\u0004 \u0005[כפי שנאמר]\u0006 ביאור מצרים: \u0003\"קנה וסוף קמלו\"\u0004 (ישעיה יט, ו).","נאמר: \u0003\"ותרד בת פרעה לרחץ על היאר\"\u0004 (שמות ב, ה). \u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' שמעון בן יוחי: מלמד שירדה לרחוץ מגלולי אביה,\u0004 שהיתה זו טבילה של קבלת מצוות, \u0003וכן הוא אומר: \"אם רחץ ה' את צאת בנות ציון\"\u0004 (ישעיה ד, ד), והכוונה שם לחטאים, ללמדנו שיש רחיצה שעיקר משמעה הוא רוחני ולא חומרי.","\u0003\"ונערתיה הלכת\"\u0004 (שמות ב, ה). \u0003אמר ר' יוחנן: אין הליכה זו אלא לשון מיתה, וכן הוא אומר \"הנה אנכי הולך למות\"\u0004 (בראשית כה, לב).","ומבארים: \u0003\"ותרא את התבה בתוך הסוף\"\u0004 (שמות ב, ה), \u0003כיון דחזו דקא בעו לאצולי\u0004 \u0005[שראו\u0006 נערותיה \u0005ש\u0006היא \u0005רוצה להציל]\u0006 את \u0003משה, אמרו לה: גבירתנו, מנהגו של עולם\u0004 כש\u0003מלך בשר ודם גוזר גזירה,\u0004 גם \u0003אם כל העולם כולו אין מקיימין אותה\u0004 — לפחות \u0003בניו ובני ביתו מקיימין אותה, ואת עוברת על גזירת אביך? בא\u0004 המלאך \u0003גבריאל וחבטן בקרקע\u0004 ומתו.","נאמר \u0003\"ותשלח את אמתה ותקחה\"\u0004 (שמות ב, ה). \u0003ר' יהודה ור' נחמיה\u0004 נחלקו בפירוש המלה \"אמתה\", \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 הכוונה ל\u0003ידה, וחד\u0004 \u0005[ואחד]\u0006 \u0003אמר:\u0004 הכוונה ל\u0003שפחתה.\u0004 ומסבירים: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003ידה —\u0004 \u0003דכתיב\u0004 \u0003[שנאמר]:\u0004 \u0003\"אמתה\"\u0004 שהיא אמת היד. \u0003ומאן\u0004 \u0003דאמר\u0004 \u0005[ומי שאומר]\u0006 \u0003שפחתה —\u0004 \u0003מ\u0004כיון ש\u0003לא כתיב\u0004 \u0005[נאמר]\u0006 \u0003ידה\u0004 במפורש.","ושואלים: \u0003ולמאן\u0004 \u0003דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 \u0003שפחתה, הא\u0004 \u0005[הרי]\u0006 \u0003אמרת\u0004 ש\u0003בא גבריאל וחבטן,\u0004 את שפחותיה \u0003בקרקע!\u0004 ומשיבים: ש\u0003שייר לה\u0004 גבריאל שפחה \u0003חדא\u0004 \u0005[אחת],\u0006 \u0003דלאו אורחא דבת מלכא למיקם לחודה\u0004 \u0005[שאין דרכה של בת מלך לעמוד,\u0006 להיות \u0005לבדה],\u0006 ואת אותה שפחה שלחה לקחת את התיבה.","ושואלים: \u0003ולמאן\u0004 \u0003דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 ש\"אמתה\" זו \u0003ידה, ליכתוב\u0004 \u0005[שיכתוב]\u0006 הכתוב במפורש \u0003\"ידה\"!\u0004 ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 \u0003דאישתרבב אישתרבובי\u0004 \u0005[שהשתרבבה]\u0006 ידה והתארכה אמות הרבה. ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 בענין אחר: \u0003וכן אתה מוצא באמתה של בת פרעה\u0004 שנשתרבבה, \u0003וכן אתה מוצא בשיני רשעים, דכתיב\u0004 \u0003[שנאמר]:\u0004 \u0003\"שני רשעים שברת\"\u0004 (תהלים ג, ח), \u0003ואמר ריש לקיש: אל תיקרי\u0004 \u0005[תקרא]\u0006 \u0003\"שברת\" אלא \"שריבבתה\".\u0004","נאמר \u0003\"ותפתח ותראהו את הילד\"\u0004 (שמות ב, ו), ותוהים על לשון \"ותראהו\": הלא \u0003\"ותרא\" מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר! \u0003אמר ר' יוסי בר' חנינא: שראתה שכינה עמו,\u0004 והכתוב מתפרש: \"ותראהו את\" — עם הילד ראתה את ה'.","נאמר: \u0003\"והנה נער בכה\"\u0004 (שמות ב, ו) \u0003קרי ליה\u0004 \u0005[קורא לו]\u0006 הכתוב \u0003\"ילד\", וקרי ליה\u0004 \u0005[וקורא לו]\u0006 באותו פסוק \u0003נער. תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003הוא ילד וקולו\u0004 גדול ועבה \u0003כנער,\u0004 אלו \u0003דברי ר' יהודה. אמר לו ר' נחמיה: אם כן עשיתו למשה רבינו בעל מום,\u0004 שהיה קולו עבה שלא כרגיל. \u0003אלא, מלמד שעשתה לו אמו חופת נעורים בתיבה,\u0004 כלומר, עשתה לו כעין חופה קטנה בתוך התיבה, ש\u0003אמרה: שמא לא אזכה לחופתו.\u0004","נאמר: \u0003\"ותחמל עליו ותאמר מילדי העברים זה\"\u0004 (שמות ב, ו). ושואלים: \u0003מנא\u0004 \u0005[מניין]\u0006 \u0003ידעה\u0004 שהוא מילדי העברים\u0003? אמר ר' יוסי בר' חנינא: שראתה אותו\u0004 שהוא \u0003מהול.\u0004","\u0003\"זה\" —\u0004 \u0003אמר ר' יוחנן: מלמד שנתנבאה שלא מדעתה,\u0004 כשאמרה \"זה\" הכוונה: \u0003זה נופל\u0004 במים \u0003ואין אחר נופל\u0004 עוד למים.","\u0003והיינו\u0004 \u0005[וזהו]\u0006 ש\u0003אמר ר' אלעזר, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"וכי יאמרו אליכם דרשו אל האבות ואל הידענים המצפצפים והמהגים\"\u0004 (ישעיה ח, יט), מהו פירוש \"המצפצפים והמהגים\": \u0003צופין ואינם יודעין מה צופין, מהגים ואינן יודעים מה מהגים.\u0004 שאמנם רואים האובות והידעונים משהו מן העתיד אבל אינם רואים אותו בבירור.","\u0003ראו\u0004 האיצטגנינים \u0003שמושיען של ישראל במים הוא לוקה\u0004 וידעו שפורענותו תהיה במים, \u0003עמדו וגזרו: \"כל הבן הילוד היארה תשליכהו\"\u0004 (שמות א, כב). \u0003כיון דשדיוה\u0004 \u0005[שהשליכו]\u0006 את \u0003משה\u0004 למים, שהיה ביאור, \u0003אמרו:\u0004 \u0003תו לא חזינן כי ההוא סימנא\u0004 \u0005[שוב אין אנחנו רואים\u0006 עוד \u0005כמו הסימן ההוא],\u0006 שמושיעם של ישראל כבר נמצא במים, \u0003בטלו לגזירתייהו\u0004 \u0005[את גזירתם]\u0006 מאותה שעה. \u0003והם אינן יודעין שעל מי מריבה הוא לוקה,\u0004 ועל דבר זה ראו שלוקה במים.","\u0003והיינו\u0004 \u0005[וזהו]\u0006 ש\u0003אמר ר' חמא בר' חנינא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"המה מי מריבה אשר רבו\"\u0004 (במדבר כ, יג) — \u0003המה\u0004 המים \u0003שראו איצטגניני פרעה וטעו\u0004 בהם. \u0003והיינו דקאמר\u0004 \u0005[וזהו שאמר]\u0006 \u0003משה \"שש מאות אלף רגלי\u0004 העם אשר אנכי בקרבו\u0003\"\u0004 (במדבר יא, כא); \u0003אמר להן משה לישראל: בשבילי\u0004 (בגללי, \"רגלי\") שנזרקתי למים \u0003נצלתם כולכם,\u0004 שמאז בטלה הגזירה ויש לי חלק בכם.","\u0003ר' חנינא בר פפא אמר: אותו היום\u0004 שהונח משה ביאור \u0003עשרים ואחד בניסן היה, אמרו מלאכי השרת לפני\u0004 \u0003הקדוש ברוך הוא: רבונו של עולם, מי שעתיד לומר שירה על הים ביום זה\u0004 שהוא יום קריעת ים סוף \u0003ילקה ביום זה?\u0004","\u0003ר' אחא בר חנינא אמר: אותו היום ששה בסיון היה, אמרו מלאכי השרת לפני\u0004 \u0003הקדוש ברוך הוא: רבונו של עולם, מי שעתיד לקבל תורה מהר סיני ביום זה, ילקה ביום זה?\u0004","ושואלים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר]\u0006 שהונח משה ביאור \u0003בששה בסיון, משכחת לה\u0004 \u0005[מוצא אתה]\u0006 \u0003תלתא ירחי\u0004 \u0005[שלושה חודשים]\u0006 של הצפנה, ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003בשבעה באדר מת\u0004 משה רבינו, \u0003ובשבעה באדר נולד משה, ו\u0004לפי זה \u0003משבעה באדר ועד ששה בסיון תלתא ירחי\u0004 \u0005[שלושה חודשים].\u0006 \u0003אלא למאן\u0004 \u0003דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שהיה \u0003בעשרים ואחד בניסן, היכי משכחת לה\u0004 \u0005[איך מוצא אתה]\u0006 שלושה חודשים?","ומשיבים: \u0003אותה שנה,\u0004 שנה \u0003מעוברת היתה,\u0004 שהיו בה שני חודשי אדר, ואם כן הצפינתו \u0003רובו של\u0004 חודש \u0003ראשון\u0004 (משבעה באדר ראשון שנולד בו), \u0003ורובו של אחרון\u0004 (עד עשרים ואחד בניסן), \u0003ואמצעי\u0004 (אדר שני) \u0003שלם.\u0004","נאמר: \u0003\"ותאמר אחתו אל בת פרעה האלך וקראתי לך אשה מינקת מן העברית\"\u0004 (שמות ב, ז) ושואלים: \u0003ומאי שנא\u0004 \u0005[ומה שונה,\u0006 מדוע דווקא\u0005]\u0006 \u0003מעבריות?\u0004","\u0003מלמד ש\u0004לפני כן \u0003החזירוהו\u0004 (סובבוהו) \u0003למשה על כל\u0004 המניקות \u0003המצריות כולן, ולא ינק\u0004 מהן, \u0003אמר: פה שעתיד לדבר עם השכינה יינק דבר טמא? והיינו דכתיב\u0004 \u0005[וזהו שנאמר]\u0006 \u0003\"את מי יורה דעה\u0004 ואת מי יבין שמועה \u0003\".\u0004 \u0003למי יורה דעה ולמי יבין שמועה,\u0004 כלומר, למי ילמד את התורה — \u0003לגמולי מחלב ולעתיקי משדים\u0004 (ראה ישעיה כח, ט), לזה שלא רצה לינוק (\"גמולי\") מחלב נכריה.","נאמר: \u0003\"ותאמר לה בת פרעה לכי\u0004 ותלך העלמה\u0003\"\u0004 (שמות ב, ח) \u0003אמר ר' אלעזר: מלמד שהלכה בזריזות כעלמה,\u0004 כלומר, כעלמה גדולה ולא כילדה. \u0003ר' שמואל בר נחמני אמר: \"העלמה\" —\u0004 \u0003שהעלימה את דבריה\u0004 ולא סיפרה לה שהיא מביאה אותו אל אמו.","נאמר שם \u0003\"ותאמר לה בת פרעה\u0004 (ליוכבד) \u0003היליכי את הילד הזה\"\u0004 (שמות ב, ט). \u0003אמר ר' חמא בר' חנינא: מתנבאה\u0004 היתה בת פרעה \u0003ואינה יודעת מה מתנבאה, \"היליכי\"\u0004 פירושו — \u0003הא שליכי\u0004 \u0005[זה שלך].\u0006 \u0003\"ואני אתן את שכרך\"\u0004 (שמות ב, ט). \u0003אמר ר' חמא בר' חנינא: לא דיין לצדיקים שמחזירין להן אבידתן, אלא שנותנין להן שכרן,\u0004 שהרי החזירו ליוכבד את בנה ואף קיבלה שכר על שהניקה אותו.","נאמר \u0003\"ותקח מרים הנביאה אחות אהרן\"\u0004 (שמות טו, כ). ושואלים: וכי היתה \u0003אחות אהרן ולא אחות משה? אמר רב עמרם אמר רב ואמרי לה\u0004 \u0005[ו\u0006יש \u0005אומרים אותה],\u0006 \u0003אמר רב נחמן אמר רב: מלמד שהיתה מתנבאה\u0004 עוד \u0003כשהיא אחות אהרן,\u0004 כשעדיין לא נולד משה,"],["\u0003ואומרת: עתידה אמי שתלד בן שמושיע את ישראל. וכיון שנולד משה נתמלא כל הבית כולה אור, עמד אביה ונשקה על ראשה, אמר לה: בתי, נתקיימה נבואתיך. וכיון שהטילוהו ליאור, עמד אביה וטפחה\u0004 (היכה לה) \u0003על ראשה, אמר לה: בתי היכן נבואתיך? והיינו דכתיב\u0004 \u0005[וזהו שנאמר]\u0006 \u0003\"ותתצב אחתו מרחק לדעה מה יעשה לו\"\u0004 (שמות ב, ד), לומר: \u0003לידע מה יהא בסוף נבואתה.\u0004","שנינו במשנה ש\u0003יוסף זכה\u0004 לקבור את אביו והוא היה הגדול שבאחיו. ובאים לפרש את הכתובים האמורים באותו ענין. שואלים: \u0003מאי שנא מעיקרא, דכתיב\u0004 \u0005[\u0006ב\u0005מה שונה מתחילה, שנאמר]\u0006 \u0003\"ויעל יוסף לקבר את אביו ויעלו אתו כל עבדי פרעה\"\u0004 (בראשית נ, ז) \u0003והדר\u0004 \u0005[ואחר כך]\u0006 נאמר: \u0003\"וכל בית יוסף ואחיו ובית אביו\"\u0004 (בראשית נ, ח), \u0003ומאי שנא\u0004 \u0005[ומה שונה]\u0006 \u0003לבסוף דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וישב יוסף מצרימה הוא ואחיו\"\u0004 (בראשית נ, יד) \u0003והדר\u0004 \u0005[ואחר כך]\u0006 \u0003\"וכל העלים אתו לקבר את אביו\"\u0004 (בראשית נ, יד)?","\u0003אמר ר' יוחנן: בתחילה עד שלא ראו\u0004 המצרים \u0003בכבודן של ישראל\u0004 בארצם — \u0003לא נהגו בהן כבוד,\u0004 ולכן היו הם בסוף, אחרי עבדי פרעה, \u0003ולבסוף שראו בכבודן —\u0004 \u0003נהגו בהן כבוד.\u0004","\u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויבאו עד גרן האטד\"\u0004 (בראשית נ, י), \u0003וכי גורן יש לו לאטד?\u0004 והלא אין פירותיו נאספים ונאכלים! \u0003אמר ר' אבהו: מלמד שהקיפוהו כתרים לארונו של יעקב כגורן זה שמקיפים לו אטד\u0004 שהוא צמח קוצני, לשמירה, \u0003שבאו בני עשו ובני ישמעאל ובני קטורה\u0004 כולם ונתנו לו כבוד.","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003כולם\u0004 מתחילה \u0003למלחמה באו, כיון שראו כתרו של יוסף\u0004 שהיה משנה למלך מצרים \u0003תלוי בארונו של יעקב —\u0004 \u0003נטלו כולן\u0004 אף הם \u0003כתריהן ותלאום בארונו של יעקב. תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003שלשים וששה כתרים נתלו בארונו של יעקב.\u0004","נאמר: \u0003\"ויספדו שם מספד גדול וכבד מאד\"\u0004 (בראשית נ, י). \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003אפילו סוסים ואפילו חמורים\u0004 עשו בהם מנהגי אבל.","\u0003(מאילו מאילו) כיון שהגיעו למערת המכפלה אתא\u0004 \u0005[בא]\u0006 \u0003עשו, קא\u0004 \u0005[\u0006ו\u0005היה]\u0006 \u0003מעכב\u0004 מלקבור את יעקב שם, \u0003אמר להן:\u0004 נאמר \u0003\"ממרא קרית הארבע היא חברון\"\u0004 (בראשית לה, כז), \u0003ואמר ר' יצחק: קרית ארבע\u0004 קרויה כך משום \u0003ארבע זוגות\u0004 ש\u0003היו,\u0004 שנקברו שם: \u0003אדם וחוה, אברהם ושרה, יצחק ורבקה, יעקב ולאה. איהו\u0004 \u0005[הוא],\u0006 יעקב, \u0003קברה ללאה בדידיה\u0004 \u0005[ב\u0006חלק \u0005שלו],\u0006 \u0003והאי דפייש\u0004 \u0005[וזה\u0006 המקום \u0005שנשאר] —\u0006 \u0003דידי\u0004 \u0005[שלי]\u0006 \u0003הוא.\u0004","\u0003אמרו ליה\u0004 \u0005[לו]\u0006 בני יעקב לעשיו: \u0003זבינתה\u0004 \u0005[מכרת אותה]\u0006 את נחלתך ליעקב. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003נהי דזביני בכירותא, פשיטותא מי זביני\u0004 \u0005[אם אמנם שמכרתי\u0006 את \u0005בכורתי,\u0006 את חלקי כאח \u0005פשוט האם מכרתי]?\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 גם את חלקך כאח פשוט מכרת ליעקב, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 שכך אמר יעקב: \u0003\"בקברי אשר כריתי לי\"\u0004 (בראשית נ, ה), \u0003ואמר ר' יוחנן משום ר' שמעון בן יהוצדק: אין \"כירה\" אלא לשון מכירה, שכן בכרכי הים קורין למכירה —\u0004 \u0003\"כירה\".\u0004","\u0003אמר להו\u0004 \u0005[להם]\u0006 עשיו: \u0003הבו\u0004 \u0005[תנו]\u0006 \u0003לי איגרתא\u0004 \u0005[שטר]\u0006 של מכירה זו! \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003איגרתא בארעא דמצרים היא\u0004 \u0005[השטר בארץ מצרים הוא].\u0006 אמרו: \u0003ומאן ניזיל\u0004 \u0005[ומי ילך]\u0006 להביאו — \u0003ניזיל\u0004 \u0005[ילך]\u0006 \u0003נפתלי דקליל כי איילתא\u0004 \u0005[ש\u0006הוא \u0005קל\u0006 רגליים \u0005כאיילה],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"נפתלי אילה שלחה הנתן אמרי שפר\"\u0004 (בראשית מט, כא), ו\u0003אמר ר' אבהו: אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"אמרי שפר\" אלא \"אמרי ספר\",\u0004 כלומר, שהוא הביא את הספר = השטר.","ומספרים: \u0003חושים בריה\u0004 \u0005[בנו]\u0006 של \u0003דן תמן הוה\u0004 \u0005[שם היה]\u0006 \u0003ויקירן ליה אודניה\u0004 \u0005[והיו כבדות לו אוזניו],\u0006 שלא שמע היטב. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מאי האי\u0004 \u0005[מהו זה]\u0006 שאין קוברים את הסב יעקב? \u0003ואמרו ליה\u0004 \u0005[לו]:\u0006 \u0003קא מעכב האי\u0004 \u0005[זה],\u0006 עשיו, \u0003עד דאתי\u0004 \u0005[שיבוא]\u0006 \u0003נפתלי מארעא דמצרים\u0004 \u0005[מארץ מצרים].\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003ועד דאתי\u0004 \u0005[שיבוא]\u0006 \u0003נפתלי מארעא דמצרים\u0004 \u0005[מארץ מצרים]\u0006 \u0003יהא אבי אבא מוטל בבזיון?\u0004 \u0003שקל קולפא מחייה ארישיה\u0004 \u0005[לקח אלה\u0006 ו\u0005היכה\u0006 בה את עשיו \u0005על ראשו],\u0006 \u0003נתרן עיניה\u0004 \u0005[קפצו עיניו]\u0006 \u0003ונפלו\u0004 מחוריהן \u0003אכרעא\u0004 \u0005[על רגליו]\u0006 של \u0003יעקב, פתחינהו\u0004 \u0005[פתח]\u0006 \u0003יעקב לעיניה ואחיך\u0004 \u0005[את עיניו וחייך].\u0006 \u0003והיינו דכתיב [וזהו שנאמר]:\u0004 \u0005\"ישמח צדיק כי חזה נקם פעמיו\u0006\u0005 (רגליו) \u0003ירחץ בדם הרשע\"\u0004 (תהלים נח, יא).\u0006","\u0003באותה שעה נתקיימה נבואתה של רבקה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"למה אשכל גם שניכם יום אחד\"\u0004 (בראשית כז, מה). ומעירים: \u0003ואף על גב\u0004 \u0005[ואף על פי]\u0006 ש\u0003מיתתן לא ביום אחד הואי\u0004 \u0005[היתה]\u0006 — \u0003קבורתן מיהא\u0004 \u0005[מכל מקום]\u0006 \u0003ביום אחד הואי\u0004 \u0005[היתה],\u0006 שהרי נהרג עשיו, וגם נקבר, באותו יום שנקבר יעקב.","ושואלים: \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא עסק ביה\u0004 \u0005[היה עוסק בו]\u0006 \u0003יוסף אחיו לא הוו מעסקי ביה\u0004 \u0005[היו מתעסקים בו,\u0006 ביעקב\u0005]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"וישאו אתו בניו ארצה כנען\"\u0004 (בראשית נ, יג), ומדוע לא התעסקו ביעקב בתחילה? אלא \u0003אמרו: הניחו לו\u0004 ליוסף לטפל בו, \u0003כבודו\u0004 של יעקב אבינו \u0003במלכים יותר מבהדיוטות.\u0004","ועוד שנינו במשנה: \u0003מי לנו גדול מיוסף\u0004 שלא התעסק בעצמותיו אלא משה רבינו. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בא וראה כמה חביבות\u0004 היו \u0003מצות על משה רבינו. שכל ישראל כולן נתעסקו\u0004 במהלך יציאת מצרים \u0003בביזה\u0004 של שלל מצרים, \u0003ו\u0004אילו \u0003הוא נתעסק במצות, שנאמר:\u0004 \u0003\"חכם לב יקח מצות\"\u0004 (משלי י, ח).","ושואלים: \u0003ומנין היה יודע משה רבינו היכן יוסף קבור? אמרו: סרח בת אשר נשתיירה מאותו הדור\u0004 שירד עם יעקב למצרים. \u0003הלך משה אצלה, אמר לה: כלום את יודעת היכן יוסף קבור? אמרה לו: ארון של מתכת עשו לו מצרים וקבעוהו בנילוס הנהר\u0004 לסגולה, \u0003כדי שיתברכו מימיו. הלך משה ועמד על שפת נילוס, אמר לו: יוסף יוסף! הגיע העת שנשבע הקדוש ברוך הוא שאני גואל אתכם, והגיעה השבועה שהשבעת את ישראל\u0004 שיעלוך ויקברוך בארץ ישראל. \u0003אם אתה מראה עצמך —\u0004 \u0003מוטב, אם לאו\u0004 \u0005[לא] —\u0006 \u0003הרי אנו מנוקין משבועתך,\u0004 שאין אנחנו יכולים למצוא את ארונך. \u0003מיד צף ארונו של יוסף.\u0004","\u0003ואל תתמה היאך ברזל צף, שהרי כתיב\u0004 \u0005[נאמר]\u0006 באלישע: \u0003\"ויהי האחד מפיל הקורה ואת הברזל נפל אל המים\u0004 ויצעק ויאמר \u0003אהה אדני והוא שאול. ויאמר איש האלהים אנה נפל ויראהו את המקום ויקצב עץ וישלך שמה ויצף הברזל\"\u0004 (מלכים ב ו, ה-ו). \u0003והלא דברים קל וחומר: ומה אלישע\u0004 שהיה \u0003תלמידו של אליהו, ואליהו\u0004 היה \u0003תלמידו\u0004 (מקבל תורתו) \u0003של משה —\u0004 \u0003צף ברזל מפניו, מפני משה רבינו על אחת כמה וכמה.\u0004","\u0003ר' נתן אומר: בקברניט\u0004 (מקום קבורה) \u0003של מלכים היה\u0004 יוסף \u0003קבור. הלך משה ועמד על קברניט של מלכים, אמר: יוסף, הגיע עת שנשבע הקדוש ברוך הוא שאני גואל אתכם, והגיעה\u0004 זמן קיום ה\u0003שבועה שהשבעת את ישראל. אם אתה מראה עצמך —\u0004 \u0003מוטב, ואם לאו\u0004 \u0005[לא] —\u0006 \u0003הרי אנו מנוקין משבועתך. באותה שעה נזדעזע ארונו של יוסף\u0004 בין הארונות, \u0003נטלו משה, והביאו אצלו.\u0004","\u0003וכל אותן שנים שהיו ישראל במדבר היו שני ארונות הללו, אחד של מת\u0004 (של יוסף) \u0003ואחד של שכינה\u0004 (ארון הברית) \u0003מהלכין זה עם זה, והיו עוברין ושבין אומרים: מה טיבן של שני ארונות הללו? אמרו\u0004 להם: \u0003אחד של מת ואחד של שכינה.\u0004 והיו תוהים: \u0003וכי מה דרכו של מת להלך עם שכינה? אמרו\u0004 להם:"],["\u0003קיים זה,\u0004 יוסף המת, \u0003כל מה שכתוב בזה,\u0004 בלוחות המונחים בארון, ולכן ראוי לו להיות לצידו.","ושואלים: \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא עסיק ביה\u0004 \u0005[היה עוסק בו]\u0006 \u0003משה\u0004 בארון יוסף — \u0003ישראל לא הוו מיעסקי ביה\u0004 \u0005[היו מתעסקים בו]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 לאחר מות משה: \u0003\"ואת עצמות יוסף אשר העלו בני ישראל ממצרים קברו בשכם\"\u0004 (יהושע כד, לב), משמע שלא נמנעו מלטפל בו! \u0003ותו, אי\u0004 \u0005[ועוד, אם]\u0006 \u0003לא איעסקו ביה\u0004 \u0005[היו מתעסקים בו]\u0006 כל \u0003ישראל —\u0004 \u0003בניו לא הוו מיעסקי ביה\u0004 \u0005[היו מתעסקים בו]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"ויהיו לבני יוסף לנחלה\"\u0004 (יהושע כד, לב), שקברוהו בנחלתם, ומדוע לא התעסקו בו בתחילה?!","אלא \u0003אמרו: הניחו לו, כבודו במרובים יותר מבמועטין\u0004 ומוטב שיטפלו בו כל ישראל ולא רק צאצאיו. \u0003ותו\u0004 \u0005[ועוד]\u0006 \u0003אמרו: הניחו לו, כבודו בגדולים\u0004 כמשה רבינו \u0003יותר מבקטנים.\u0004","נאמר שם שאת עצמות יוסף \u0003קברו בשכם.\u0004 ושואלים: \u0003מאי שנא\u0004 \u0005[מה שונה,\u0006 מדוע דווקא\u0005]\u0006 \u0003בשכם? אמר ר' חמא בר' חנינא,\u0004 כך אמרו: \u0003משכם גנבוהו\u0004 אחיו במכירתו \u0003ולשכם נחזיר אבידתו.\u0004","ומעירים: \u0003קשו קראי אהדדי\u0004 \u0005[קשים הכתובים זה על זה];\u0006 \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ויקח משה את עצמות יוסף עמו\"\u0004 (שמות יג, יט), משמע שמשה הוא שהעלה את העצמות, \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ואת עצמות יוסף אשר העלו בני ישראל\"\u0004 (יהושע כד, לב)!","\u0003אמר ר' חמא בר' חנינא: כל העושה דבר ולא גמרו, ובא אחר וגמרו —\u0004 \u0003מעלה עליו הכתוב על\u0004 זה \u0003שגמרו כאילו עשאו\u0004 כולו, ולכן אף העלאת עצמותיו של יוסף ממצרים נזקפת לזכותם של בני ישראל.","\u0003ר' אלעזר אומר:\u0004 מי שהתחיל לעשות מצוה ולא גמרה \u0003אף מורידין אותו מגדולתו, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויהי בעת ההיא וירד יהודה\"\u0004 (בראשית לח, א), שנאמרה בו לשון ירידה, שהורידוהו האחים מגדולתו, משום שיכול היה לגמור ולהציל את יוסף, ולא הצילו לגמרי.","\u0003ר' שמואל בר נחמני אמר:\u0004 משם ראיה ש\u0003אף קובר אשתו ובניו, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ותמת בת שוע אשת יהודה\"\u0004 (בראשית כד, יב), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בבניו \u0003\"וימת ער ואונן\"\u0004 (בראשית מו, יב).","\u0003אמר רב יהודה אמר רב: מפני מה נקרא יוסף עצמות בחייו,\u0004 שהרי הוא עצמו אמר \"והעליתם את עצמותי מזה\" (בראשית נ, כה) — \u0003מפני שלא מיחה\u0004 באחיו בדבר שהיה בו זלזול \u0003בכבוד אביו, דקאמרי ליה\u0004 \u0005[שאמרו לו]\u0006 האחים כמה פעמים \u0003\"עבדך אבינו\"\u0004 (בראשית מג, כח. בראשית מד, לא), \u0003ולא אמר להו\u0004 \u0005[להם]\u0006 \u0003ולא מידי\u0004 \u0005[דבר].\u0006","\u0003ואמר רב יהודה אמר רב, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' חמא בר' חנינא: מפני מה מת יוסף קודם לאחיו,\u0004 שהרי הוא מצווה אותם שיטפלו בקבורתו — \u0003מפני שהנהיג עצמו ברבנות\u0004 (שררה), וכך קורה לו לאדם שמפני גדולתו מתקצרים ימיו.","כיון שדובר בענין זה של לשון ירידה הקשורה במכירת יוסף, מזכירים מה שנאמר \u0003\"ויוסף הורד מצרימה\"\u0004 (בראשית לט, א). \u0003אמר ר' אלעזר: אל תיקרי\u0004 \u0005[תקרא]\u0006 \u0003\"הורד\" אלא \"הוריד\",\u0004 כלומר, \u0003שהוריד איצטגניני פרעה מגדולתן\u0004 שידע לפתור את חלומותיו של פרעה והם לא הצליחו לפותרם.","נאמר: \u0003\"ויקנהו פוטיפר סריס פרעה\"\u0004 (בראשית לט, א). \u0003אמר רב: שקנאו לעצמו\u0004 למשכב זכור. \u0003בא\u0004 המלאך \u0003גבריאל וסירסו, בא גבריאל ופירעו\u0004 הוסיף בסירוס זה. ורמז לדבר: \u0003מעיקרא כתיב\u0004 \u0005[מתחילה נאמר]\u0006 \u0003\"פוטיפר\"\u0004 (בראשית לט, א) \u0003ולבסוף \"פוטיפרע\"\u0004 (בראשית מא, מה), לשון קריעה ופריעה, ומשום שנסתרס לא יכול היה לעשות זאת.","שנינו במשנה: \u0003מי לנו גדול ממשה\u0004 שלא נתעסק בו אלא המקום. נאמר שביקש משה לבוא לארץ, ואז \u0003\"ויאמר ה' אלי רב לך\"\u0004 (דברים ג, כו). \u0003אמר ר' לוי: ב\"רב\" בישר, ב\"רב\" בישרוהו,\u0004 שכיון שהשתמש בלשון זו כדי לגעור בישראל נאמר לו גם כן באותה לשון. ומסבירים: \u0003ב\"רב\" בישר,\u0004 שאמר: \u0003\"רב לכם\u0004 בני לוי\u0003\"\u0004 (במדבר טז, ז). \u0003ב\"רב\" בישרוהו —\u0004 \u0003\"רב לך\u0004\".","\u0003דבר אחר:\u0004 \u0003\"רב לך\" —\u0004 \u0003רב יש לך\u0004 כעת, \u0003ומנו\u0004 \u0005[ומי הוא] —\u0006 זה \u0003יהושע\u0004 שנבחר להיות המנהיג בישראל.","\u0003דבר אחר: \"רב לך\",\u0004 יש לך רב (אדון, הקדוש ברוך הוא) ואתה צריך לכבדו, ומשום כך אל תפציר בי יותר, \u0003שלא יאמרו: הרב כמה קשה, ותלמיד כמה סרבן.\u0004 ושואלים: \u0003וכל כך למה,\u0004 מדוע נענש משה על חטאים קלים אלה? \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל,\u0004 לפי הפתגם שאומרים: \u0003לפום גמלא שיחנא\u0004 \u0005[לפי הגמל המשא].\u0006 כלומר, לפי גדולתו של אדם מדקדקים יותר במעשיו.","נאמר על משה \u0003\"ויאמר אלהם בן מאה ועשרים שנה אנכי היום\"\u0004 (דברים לא, ב), \u0003שאין תלמוד לומר\u0004 (שניתן הפסוק להכתב גם בלי המלה) \u0003\"היום\",\u0004 אלא אומר הוא זאת במכוון: \u0003היום מלאו ימי ושנותי\u0004 בדיוק מאה ועשרים שנה. \u0003ללמדך שהקדוש ברוך הוא משלים שנותיהם של צדיקים מיום ליום ומחדש לחדש, דכתיב\u0004 \u0005[שנאמר]:\u0006 בברכה: \u0003\"את מספר ימיך אמלא\"\u0004 (שמות כג, כו).","נאמר שם \u0003\"לא אוכל עוד לצאת ולבוא\"\u0004 (דברים לא, ב). ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"לצאת ולבוא\"? אילימא\u0004 \u0005[אם תאמר]\u0006 שתש כוחו \u0003לצאת ולבא ממש, והכתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"ומשה בן מאה ועשרים שנה במתו\u0004 לא כהתה עינו ו\u0003לא נס לחה\"\u0004 (דברים לד, ז), \u0003וכתיב\u0004 \u0005[ו\u0006עוד \u0005נאמר]\u0006 \u0003\"ויעל משה מערבת מואב אל הר נבו\"\u0004 (דברים לד, א), \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003שתים עשרה מעלות\u0004 (מדרגות) \u0003היו שם\u0004 במעלה זה, \u0003ופסען משה בפסיעה אחת.\u0004 ואיך אמר שלא יוכל לצאת ולבוא?","\u0003אמר ר' שמואל בר נחמני אמר ר' יונתן:\u0004 הכוונה היתה \u0003לצאת ולבוא בדברי תורה. מלמד שנסתתמו ממנו שערי חכמה.\u0004","נאמר: \u0003\"וילך משה ויהושע ויתיצבו באהל מועד\"\u0004 (דברים לא, יד). \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003אותה שבת\u0004 יום שמת בו משה \u0003של דיו זוגי\u0004 \u0005[שני זוגות]\u0006 \u0003היתה,\u0004 כלומר, שהיו שם שני חכמים משמשים במקום אחד, משה ויהושע, \u0003ניטלה רשות מזה, ונתנה לזה.\u0004","\u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' יהודה: אילמלא מקרא כתוב אי אפשר לאומרו\u0004 מדעתנו. \u0003היכן משה מת —\u0004 \u0003בחלקו של ראובן, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויעל משה מערבת מואב אל הר נבו\"\u0004 (דברים לד, א), \u0003ונבו בחלקו של ראובן קיימא\u0004 \u0005[עומדת],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ובני ראובן בנו... ואת נבו\"\u0004 (במדבר לב, לז-לח).","ועוד דרשו: \u0003\"נבו\" —\u0004 \u0003ששם מתו שלשה נביאים\u0004 (\"נבו\"): \u0003משה ואהרן ומרים.\u0004","\u0003והיכן משה קבור —\u0004 \u0003בחלקו של גד, דכתיב\u0004 \u0005[שנאמר]\u0006 בברכת משה לשבט גד: \u0003\"וירא ראשית לו\u0004 כי שם חלקת מחוקק ספון\u0003\"\u0004 (דברים לג, כא), כלומר, משה המחוקק טמון שם. \u0003ומחלקו של ראובן עד חלקו של גד כמה הוי\u0004 \u0005[הוא]\u0006 המרחק — \u0003ארבעה מילין. אותן ארבעה מילין\u0004 ממקום מותו למקום קבורתו \u0003מי הוליכו?\u0004","\u0003מלמד שהיה משה מוטל בכנפי שכינה,\u0004 כלומר, הקדוש ברוך הוא עצמו נשאו, \u0003ומלאכי השרת אומרים \"צדקת ה' עשה ומשפטיו עם ישראל\"\u0004 (דברים לג, כא), \u0003והקדוש ברוך הוא אומר: \"מי יקום לי עם מרעים מי יתיצב לי עם פעלי און\"\u0004 (תהלים צד, טז), כלומר, מי ישתדל עכשיו וילמד זכות על ישראל מפני המקטרגים עליהם.","\u0003ושמואל אמר,\u0004 כך אמר עליו: \u0003\"מי כהחכם ומי יודע פשר דבר\"\u0004 (קהלת ח, א), \u0003ור' יוחנן אמר\u0004 שכך אמר עליו: \"ו \u0003החכמה מאין תמצא\"\u0004 (איוב כח, יב), \u0003ורב נחמן אמר,\u0004 מה שאמר עליו היה: \u0003\"וימת שם משה\u0004 עבד ה'\u0003\"\u0004 (דברים לד, ה). החכם \u0003סמליון אמר\u0004 שכך אמר: \u0003וימת שם משה ספרא רבה דישראל\u0004 \u0005[הסופר הגדול של ישראל].\u0006","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר הגדול אומר:\u0004 מרחק של \u0003שנים עשר מיל על שנים עשר מיל, כנגד מחנה ישראל, בת קול משמיע ואומר: וימת משה ספרא רבה דישראל. ויש אומרים: לא מת משה\u0004 ממש, \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 \u0003\"וימת שם\"\u0004 (דברים לד, ה), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 \u0003\"ויהי שם עם ה'\"\u0004 (שמות לד, כח), \u0003מה להלן\u0004 \"ויהי שם עם ה'\" כוונתו \u0003עומד ומשמש\u0004 לפני ה', \u0003אף כאן\u0004 \"וימת שם\" — הכוונה היא שהוא עדיין \u0003עומד ומשמש.\u0004","נאמר: \u0003\"ויקבר אתו בגי בארץ מואב מול בית פעור\"\u0004 (דברים לד, ו). \u0003אמר ר' ברכיה:\u0004 לכאורה הרי זה \u0003סימן בתוך סימן,\u0004 כלומר, יש פה סימן מדוייק מאד היכן נקבר, \u0003ואפילו הכי\u0004 \u0005[כך]\u0006 \u0003\"ולא ידע איש את קברתו\"\u0004 (דברים לד, ו).","\u0003וכבר שלחה מלכות הרשעה\u0004 (מלכות רומי) \u0003אצל\u0004"]]};
